/* Gerado por roteiros/gerar.py a partir de roteiros/fonte. Não edite à mão. */
window.JP_SCRIPTS = Object.assign(window.JP_SCRIPTS || {}, {"121": {"dur": 22, "logline": "Seu Jairo, 74 anos, cai morto depois do café da manhã. O laudo aponta veneno. O sobrinho que preparou o café é endividado, único herdeiro e tinha uma passagem para fugir da cidade naquela noite. Tudo aponta para ele. É exatamente isso que incomoda a delegada Helena.", "twist": "Matar alguém é homicídio simples, com pena de 6 a 20 anos. Usar veneno, que a vítima não percebe, é meio insidioso; matar por herança é motivo torpe. Cada um, sozinho, já qualifica o crime: a pena sobe para 12 a 30 anos, e o caso vai para o Tribunal do Júri. Mas qualificar o crime não diz quem o cometeu. Isso o júri só decide com provas.", "guests": [{"n": "Jairo Mendes", "r": "Vítima, 74 anos", "d": "Comerciante aposentado e viúvo, apaixonado por bolero. Voltou a se apaixonar e escondeu isso de todos."}, {"n": "Vinícius Mendes", "r": "Sobrinho e herdeiro, 39 anos", "d": "Músico endividado, impulsivo e irônico quando tem medo. O suspeito perfeito."}, {"n": "Dona Zuleica", "r": "Vizinha, 71 anos", "d": "Vizinha de muro de Seu Jairo há quarenta anos. Sabe tudo o que acontece na rua."}, {"n": "Marisa Vilela", "r": "A mulher do enterro, 58 anos", "d": "Professora de dança de salão, encantadora em público e calculista em particular. Sempre com um lenço de seda."}, {"n": "Agente Bráulio", "r": "Agente penitenciário, 45 anos", "d": "Lacônico, mas humano"}, {"n": "Ferrugem", "r": "Agiota, 40 anos", "d": "Frio, debochado, calcula tudo em dinheiro"}, {"n": "Seu Toninho", "r": "Colega de cela de Vinícius, 66 anos", "d": "Paciente, sábio, aguarda julgamento há dois anos"}], "scenes": [{"s": "INT. CASA DE JAIRO — COZINHA — AMANHECER", "l": [["*", "Seis e quarenta da manhã. Um rádio antigo toca bolero baixinho. Cozinha simples e muito limpa: azulejo verde, toalha de crochê, um pote de açúcar azul de porcelana no centro da mesa."], ["*", "VINÍCIUS, 39, olheiras fundas, coa café num coador de pano. O celular vibra. Ele atende de costas para a porta, falando baixo e rápido."], ["VINÍCIUS", "Sexta. Eu já falei, sexta eu pago... Não, não precisa vir aqui. Não precisa vir aqui!"], ["*", "Ele desliga. JAIRO, 74, entra arrumado: camisa clara, calça vincada, o chapéu panamá na mão. Pendura o chapéu na cadeira, cantarolando o bolero do rádio."], ["JAIRO", "Esse café está com cheiro de sexta-feira."], ["VINÍCIUS", "É quarta, tio."], ["JAIRO", "Pra mim, hoje é sexta."], ["*", "Jairo se senta, puxa o pote azul e coloca duas colheres de açúcar na xícara. Mexe devagar, sorrindo para o nada."], ["VINÍCIUS", "O senhor está diferente. Saindo de terno de noite, ouvindo bolero às seis da manhã..."], ["JAIRO", "Homem velho também tem direito de ficar bobo."], ["VINÍCIUS", "Tio, eu preciso conversar sobre aquele dinheiro."], ["*", "O sorriso de Jairo desaparece."], ["JAIRO", "Já te dei o que eu podia, Vinícius. O bar acabou. Acabou."], ["VINÍCIUS", "Se eu não pagar até sexta, eles vêm aqui. Aqui, na sua casa."], ["JAIRO", "Então você resolve longe da minha casa."], ["*", "Silêncio pesado. Vinícius bate a xícara na pia, sai pela porta dos fundos e acende um cigarro no quintal, de costas para a janela."], ["*", "Na cozinha, Jairo bebe o café. Um gole. Dois. A mão começa a tremer. A xícara escorrega e se espatifa no piso. O rádio continua tocando."], ["*", "No quintal, Vinícius ouve o barulho. Vira-se. Corre."], ["VINÍCIUS", "Tio? Tio!"], ["*", "Corte seco para preto."]]}, {"s": "VINHETA", "l": [["*", "O triângulo laranja da JURISPLAY desenha o \"play\". Sobre o preto, surge em letras condensadas: ART. 121. Logo abaixo: \"O Café da Herança\"."]]}, {"s": "EXT. RUA DOS IPÊS — CASA DE JAIRO — MANHÃ", "l": [["*", "Uma ambulância parada com as portas abertas, sem pressa nenhuma. Uma viatura da Polícia Civil. Fita amarela no portão."], ["*", "DONA ZULEICA, 71, bobes no cabelo e roupão florido, rega as plantas do portão vizinho sem tirar os olhos da casa. CAÍQUE, 29, tablet de capa laranja na mão, se aproxima."], ["CAÍQUE", "Bom dia, senhora. Investigador Caíque, Polícia Civil. A senhora conhecia o Seu Jairo?"], ["ZULEICA", "Quarenta anos de muro com muro, meu filho. Conhecia até o barulho do chinelo dele."], ["CAÍQUE", "E hoje cedo, a senhora ouviu alguma coisa?"], ["ZULEICA", "Ouvi gritaria. O sobrinho. Coisa de dinheiro, eu acho. Esse menino só aparece quando precisa."], ["*", "Um carro preto encosta. HELENA ROCHA, 47, blazer cinza-chumbo, desce sem pressa. Para na calçada e olha a casa inteira antes de entrar: janelas, quintal, portão."], ["CAÍQUE", "Doutora, morte na cozinha. O sobrinho chamou o SAMU às seis e cinquenta e dois. A vizinha ouviu briga antes."], ["HELENA", "Quem já entrou?"], ["CAÍQUE", "Os socorristas. E a perita chegou faz dez minutos."], ["HELENA", "Então a gente entra pisando onde ela mandar."], ["*", "Caíque abre a boca para dizer mais alguma coisa. Helena levanta um dedo."], ["HELENA", "Fato primeiro. Artigo depois."]]}, {"s": "EXT. CASA DE JAIRO — QUINTAL — MANHÃ", "l": [["*", "Antes de entrar na cozinha, Helena dá a volta na casa pelo corredor lateral. Caíque vai atrás, tentando não pisar nos canteiros."], ["*", "Quintal pequeno e cuidado: uma mangueira, um varal com duas camisas sociais penduradas, um banquinho de madeira encostado no muro. No chão, perto do banquinho, quatro bitucas de cigarro. Uma ainda solta fumaça."], ["HELENA", "Ele fumou aqui."], ["CAÍQUE", "O sobrinho disse que saiu para fumar depois da briga."], ["HELENA", "Quatro cigarros não cabem em cinco minutos."], ["CAÍQUE", "Talvez ele fume rápido. Ou talvez já estivesse aqui antes."], ["*", "Helena se abaixa e olha a janela da cozinha a partir do banquinho. Do lugar onde Vinícius estava sentado, a mesa da cozinha fica de costas: dá para ver a nuca de quem se senta ali, mas não as mãos."], ["HELENA", "Daqui ele não via o tio colocando o açúcar."], ["CAÍQUE", "E isso ajuda ou atrapalha o sobrinho?"], ["HELENA", "Por enquanto, isso é só um fato. Anota."], ["*", "Do outro lado do muro, Dona Zuleica estica o pescoço por cima de um vaso de samambaia."], ["ZULEICA", "O menino fuma escondido desde os quinze anos. O tio odiava cigarro."], ["HELENA", "Bom dia, Dona Zuleica."], ["ZULEICA", "Bom dia, doutora. Se precisar, eu estou sempre aqui."], ["CAÍQUE", "(baixinho) Isso eu não duvido."]]}, {"s": "INT. CASA DE JAIRO — COZINHA — MANHÃ", "l": [["*", "O corpo de Jairo já está coberto com um lençol. DRA. LÚCIA PAZ, 34, jaleco branco e luvas azuis, ajoelhada perto da xícara quebrada. Ela não levanta a cabeça."], ["LÚCIA", "Bom dia, delegada. Não pise na faixa de cerâmica perto da pia."], ["HELENA", "Bom dia. O que você tem?"], ["LÚCIA", "Pupilas muito contraídas. Salivação intensa. Tremores, segundo o socorrista. Isso não é infarto."], ["CAÍQUE", "Envenenamento?"], ["LÚCIA", "Suspeita de intoxicação por um tipo de pesticida proibido no Brasil. Aquele que o povo chama de chumbinho. Só o laboratório confirma."], ["*", "Caíque engole em seco e anota no tablet."], ["CAÍQUE", "Bom dia pra você também, Lúcia."], ["LÚCIA", "Bom dia, Caíque. Você está pisando na faixa."], ["*", "Caíque dá um pulo para trás. Lúcia quase sorri."], ["HELENA", "Leve tudo. Xícara, bule, coador, leite, a garrafa térmica. Tudo o que estava na mesa."], ["LÚCIA", "Já estou separando. Inclusive esse pote azul."], ["*", "Helena olha o pote de açúcar azul por um segundo a mais. Depois desvia o olhar para a sala, onde Vinícius está sentado no sofá, com as mãos na cabeça."]]}, {"s": "INT. CASA DE JAIRO — SALA — MANHÃ", "l": [["*", "Sala de móveis antigos. Na estante, discos de vinil de bolero e um porta-retratos de Jairo jovem com a esposa. Helena se senta na poltrona em frente a Vinícius. Caíque fica de pé, perto da porta."], ["HELENA", "Sinto muito pelo seu tio."], ["VINÍCIUS", "Eu fiz o café. Ele toma... tomava todo dia às seis e meia. Eu fiz o café, saí pra fumar e quando eu voltei..."], ["HELENA", "O senhor brigou com ele hoje cedo?"], ["VINÍCIUS", "A senhora já falou com a Dona Zuleica, né?"], ["HELENA", "Brigou?"], ["VINÍCIUS", "Discuti. Eu devo dinheiro. Muito dinheiro. Abri um bar, o bar quebrou, peguei dinheiro com quem não devia. Ele já tinha me ajudado. Hoje disse que não ia ajudar mais."], ["*", "Os olhos de Helena descem para a mesa de centro. Um envelope de agência de viagem aberto. Uma passagem de ônibus."], ["HELENA", "Vai viajar?"], ["*", "Vinícius olha a passagem como se só agora lembrasse dela."], ["VINÍCIUS", "Ia. Hoje à noite. Pra Salvador."], ["HELENA", "Por quê?"], ["VINÍCIUS", "Porque se eu não pagar até sexta, as pessoas pra quem eu devo vêm atrás de mim. Eu ia sumir um tempo."], ["HELENA", "E quem herda esta casa?"], ["*", "Silêncio."], ["VINÍCIUS", "Eu sou o único parente dele. A senhora sabe a resposta."], ["*", "Caíque e Helena trocam um olhar."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — TARDE", "l": [["*", "Quadro de cortiça. Caíque prende com tachinhas: foto de Jairo, foto de Vinícius, a passagem de ônibus, um print de conversa com o agiota. Fio vermelho ligando tudo."], ["CAÍQUE", "Dívida de trezentos mil. Único herdeiro de três imóveis. Briga às seis e meia. Ele mesmo fez o café. E uma passagem pra fugir da cidade no mesmo dia. Doutora, se isso fosse novela, a gente já estava nos créditos."], ["HELENA", "Por isso mesmo eu quero mais."], ["CAÍQUE", "Mais o quê?"], ["HELENA", "Mais fato. Quando tudo aponta pra um lado só, eu desconfio da bússola."], ["*", "Helena se senta na beira da mesa."], ["HELENA", "Me diz, Caíque. Se for ele, que crime é?"], ["CAÍQUE", "Homicídio. Artigo 121."], ["HELENA", "Que diz o quê?"], ["CAÍQUE", "\"Matar alguém.\" Só isso. Duas palavras."], ["HELENA", "Duas palavras e a pena mais alta do Código. Homicídio simples: seis a vinte anos de reclusão. Mas tem um parágrafo que muda tudo."], ["CAÍQUE", "As qualificadoras."], ["HELENA", "Parágrafo segundo. Se o crime é cometido com veneno, que a vítima não percebe, é meio insidioso: crime qualificado. Se foi por dinheiro de herança, motivo torpe: qualificado de novo. Basta uma qualificadora. Doze a trinta anos. E vira crime hediondo."], ["CAÍQUE", "E se fosse sem querer?"], ["HELENA", "Aí é homicídio culposo. Parágrafo terceiro. Detenção de um a três anos. Mas ninguém coloca pesticida proibido no café sem querer."], ["CAÍQUE", "E aquele homicídio \"com desconto\"?"], ["HELENA", "Privilegiado. Quando a pessoa mata por relevante valor moral ou social, ou sob violenta emoção logo depois de uma provocação injusta. A pena cai de um sexto a um terço. Não é o nosso caso."], ["*", "O telefone de Helena vibra. Ela coloca no viva-voz."], ["LÚCIA", "(telefone) Delegada, laudo preliminar. Pesticida confirmado no resto de café da xícara. Concentração alta."], ["HELENA", "E no bule?"], ["LÚCIA", "(telefone) O bule ainda não. Tenho trinta itens desta cozinha na fila. Prioridade?"], ["HELENA", "A xícara já responde o que eu precisava hoje. Obrigada, Lúcia."], ["LÚCIA", "(telefone) Ah, e diga ao Caíque que ele deixou o boné na cena do crime."], ["*", "Caíque leva a mão à cabeça. Está sem boné."], ["CAÍQUE", "Ela reparou no meu boné."], ["HELENA", "Ela reparou que você contaminou a cena."]]}, {"s": "EXT. LAVA-JATO BRILHO TOTAL — TARDE", "l": [["*", "Um lava-jato barulhento na periferia, com caixas de som tocando funk. Caíque desce do carro sem distintivo à mostra. Um homem magro de óculos escuros e corrente de ouro, FERRUGEM, 40, conta notas no balcão de um escritório improvisado."], ["CAÍQUE", "Ferrugem?"], ["FERRUGEM", "Depende de quem pergunta."], ["CAÍQUE", "Alguém que quer saber quanto o Vinícius Mendes te deve."], ["*", "Ferrugem para de contar dinheiro. Tira os óculos."], ["FERRUGEM", "Polícia."], ["CAÍQUE", "Polícia. Mas hoje eu não vim por você. Vim pelo tio dele."], ["FERRUGEM", "O velho morreu, eu soube. Péssima notícia."], ["CAÍQUE", "Para quem?"], ["FERRUGEM", "Para mim, investigador. O velho era a garantia. O moleque não tem nada. Quem ia pagar a dívida, no fim, era o tio. Morto não paga ninguém."], ["CAÍQUE", "E o senhor ameaçou o Vinícius?"], ["FERRUGEM", "Eu cobrei. Cobrar não é crime."], ["CAÍQUE", "Depende de como cobra."], ["*", "Ferrugem sorri e coloca os óculos de volta."], ["FERRUGEM", "Escreve aí no seu tablet: eu queria o velho vivo. Vivo e generoso. Quem matou o velho me deu prejuízo."], ["*", "Caíque olha em volta: os funcionários pararam de lavar os carros para observar. Ele recua devagar até o próprio carro."], ["CAÍQUE", "(para si, já dentro do carro) Ótimo. Até o agiota tem álibi moral."]]}, {"s": "INT. IML — SALA DE NECROPSIA — TARDE", "l": [["*", "Sala fria, azulejo branco. O corpo de Jairo coberto até o peito. Dr. Anselmo, de avental e máscara, conversa com Lúcia, que segura uma prancheta."], ["ANSELMO", "Morte entre seis e quarenta e sete da manhã. Falência respiratória. Pupilas puntiformes. O quadro bate com o que a senhora suspeitou no local."], ["LÚCIA", "Ele sofreu?"], ["ANSELMO", "Poucos minutos. Mas sofreu."], ["*", "Lúcia anota. Anselmo cobre o rosto de Jairo com cuidado, quase com carinho."], ["ANSELMO", "Coração de atleta, sabia? Para setenta e quatro anos. Pulmão limpo, nunca fumou. Joelhos gastos. Esse homem dançava."], ["LÚCIA", "Como o senhor sabe?"], ["ANSELMO", "Os sapatos. Vieram junto com o corpo, estavam no pé dele. Sola de couro lisa, gasta na ponta. Sapato de salão. Meu pai tinha um igual."], ["*", "Lúcia olha para o par de sapatos, num saco plástico, sobre a bancada."], ["LÚCIA", "Vou mandar isso para a delegada."]]}, {"s": "INT. CAFÉ DO FÓRUM — FIM DE TARDE", "l": [["*", "Balcão estreito, máquina de espresso chiando. IARA BASTOS, 38, terninho vinho, óculos dourados, pasta de couro debaixo do braço, chega ao balcão."], ["IARA", "Um café pequeno, por favor. Sem açúcar."], ["OTÁVIO", "(fora de quadro) Ainda sem açúcar."], ["*", "Iara fecha os olhos por um segundo antes de se virar. OTÁVIO LINS, 40, terno cinza gasto, gravata frouxa, mochila velha cheia de processos, segura uma caneca térmica."], ["IARA", "Doutor Otávio."], ["OTÁVIO", "Doutora Iara. Quinze anos e você ainda pede café como se fosse uma sentença."], ["IARA", "E você ainda carrega o fórum inteiro nas costas."], ["OTÁVIO", "Alguém tem que carregar."], ["*", "O café de Iara chega. Ela não toma."], ["IARA", "Soube do caso da Rua dos Ipês? O senhor envenenado."], ["OTÁVIO", "Soube que o sobrinho não tem dinheiro nem pra pagar o ônibus. Se não arrumar advogado, vem pra Defensoria. Vem pra mim."], ["IARA", "Homicídio doloso. Vai a júri. Eu vou acusar."], ["OTÁVIO", "Então vamos nos ver muito."], ["IARA", "Plenário não é lugar de reencontro, Otávio."], ["OTÁVIO", "Eu sei. É lugar de verdade."], ["*", "Ela pega a pasta e sai. No balcão fica o café intocado. Otávio olha a xícara e sorri de canto."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE INTERROGATÓRIO — NOITE", "l": [["*", "Mesa de metal, luz fria. Vinícius de um lado. Helena e Caíque do outro. A porta se abre. Otávio entra com a mochila."], ["OTÁVIO", "Boa noite. Otávio Lins, Defensoria Pública. Vou acompanhar o senhor Vinícius."], ["HELENA", "Fique à vontade, doutor."], ["OTÁVIO", "(para Vinícius) Antes de tudo: você não é obrigado a responder nada. O silêncio é um direito seu e não pode ser usado contra você."], ["VINÍCIUS", "Eu quero falar. Eu não tenho nada pra esconder."], ["OTÁVIO", "Todo mundo que diz isso tem alguma coisa pra esconder. Mas a decisão é sua."], ["VINÍCIUS", "Eu vou falar."], ["*", "Helena abre uma pasta."], ["HELENA", "O laudo encontrou veneno no café do seu tio. O café que o senhor fez."], ["VINÍCIUS", "Eu fiz o café como faço desde que me mudei pra lá. Seis meses. Por que eu ia matar ele justo hoje?"], ["HELENA", "Porque sexta é o prazo da sua dívida. E hoje à noite o senhor ia embora."], ["VINÍCIUS", "Eu ia fugir dos agiotas, não da polícia!"], ["HELENA", "E por que vocês brigaram?"], ["VINÍCIUS", "Porque ele estava estranho. Saía de terno toda quinta à noite. Voltava cantando. Comprou perfume, doutora. Meu tio, que usava o mesmo sabonete há quarenta anos. Eu achei que alguém estava se aproveitando dele. Que alguém ia levar o dinheiro todo."], ["HELENA", "Alguém quem?"], ["VINÍCIUS", "Eu não sei! Ele não me contava nada."], ["*", "Helena anota. Uma palavra só: \"quintas\"."]]}, {"s": "INT. CADEIA PÚBLICA — CELA 4 — NOITE", "l": [["*", "Cela coletiva, beliches de concreto. Vinícius, já de uniforme bege, sentado no chão encostado na parede, os olhos vermelhos. No beliche de baixo, um senhor de cabelo branco, SEU TONINHO, 66, lê uma revista de palavras cruzadas com os óculos na ponta do nariz."], ["TONINHO", "Primeira noite?"], ["VINÍCIUS", "Primeira."], ["TONINHO", "A primeira é a pior. Depois vira só ruim."], ["*", "Silêncio. Vinícius batuca com os dedos no joelho, sem perceber, um ritmo de bolero."], ["TONINHO", "Isso aí é bolero?"], ["VINÍCIUS", "É. Meu tio ouvia todo dia. Eu odiava. Achava coisa de velho."], ["TONINHO", "E agora?"], ["VINÍCIUS", "Agora eu não consigo parar de ouvir na cabeça."], ["*", "Ele ri, um riso que quase vira choro."], ["VINÍCIUS", "Foi ele que pagou a minha primeira guitarra. Eu tinha doze anos. Minha mãe disse que era perda de dinheiro. Ele disse: deixa o menino tocar. Ele foi a todos os shows da minha banda. Todos. Sentava no fundo e não batia palma, só balançava a cabeça."], ["TONINHO", "E te prenderam por matar ele."], ["VINÍCIUS", "Me prenderam porque eu fiz o café."], ["*", "Toninho fecha a revista."], ["TONINHO", "Eu estou aqui há dois anos esperando julgamento, rapaz. Um conselho: fala a verdade para o teu advogado. Toda. Até a parte que te faz parecer culpado."], ["VINÍCIUS", "E se a verdade me fizer parecer culpado?"], ["TONINHO", "Aí ela vai precisar de mais tempo para aparecer. Mas aparece."]]}, {"s": "INT. FÓRUM — 2ª VARA CRIMINAL — DIA", "l": [["*", "Sala de audiências de madeira escura. MARTA SIQUEIRA, 58, toga preta, óculos de leitura no cordão. Iara de um lado. Otávio e Vinícius, algemado, do outro."], ["IARA", "Excelência, o Ministério Público requer a prisão preventiva de Vinícius Mendes. Há indícios de autoria: ele preparou o café envenenado, tinha motivo financeiro e é o único herdeiro. E há risco concreto de fuga: o investigado comprou passagem para deixar o estado no dia do crime."], ["MARTA", "Defesa."], ["OTÁVIO", "Excelência, meu cliente não fugiu. Ele chamou o SAMU, esperou a polícia e respondeu a todas as perguntas. A passagem era para fugir de agiotas, gente que ameaça a vida dele, e não da Justiça. Prisão antes do julgamento é exceção. Peço medidas cautelares: entregar o passaporte, comparecer em juízo, não sair da cidade."], ["*", "Marta tira os óculos."], ["MARTA", "Prisão preventiva não é pena, senhor Vinícius. Ninguém aqui está dizendo que o senhor é culpado. A lei permite prender antes do julgamento quando há prova do crime, indícios de quem o cometeu e um risco concreto. Neste caso, o risco é de o senhor não estar aqui quando o processo terminar."], ["MARTA", "Decreto a prisão preventiva para garantir a aplicação da lei penal."], ["*", "Vinícius fecha os olhos. Otávio coloca a mão no ombro dele. Do outro lado, Iara guarda os papéis sem olhar para Otávio."]]}, {"s": "INT. APARTAMENTO DE HELENA — SALA — NOITE", "l": [["*", "A televisão ligada num telejornal local. Na tela, uma foto de Vinícius sendo levado algemado e a legenda: \"SOBRINHO PRESO POR ENVENENAR TIO POR HERANÇA\". PEDRO, 19, filho de Helena, come pipoca no sofá. Helena entra, larga a bolsa."], ["REPÓRTER", "(TV) ...a polícia acredita que o sobrinho, endividado, teria envenenado o próprio tio para ficar com três imóveis. O crime chocou a vizinhança da Rua dos Ipês..."], ["HELENA", "A polícia não acredita em nada ainda."], ["PEDRO", "Eles disseram que a polícia acredita."], ["HELENA", "Eles disseram o que dá audiência."], ["*", "Ela pega o controle e desliga a TV. Senta ao lado dele. Rouba um punhado de pipoca."], ["PEDRO", "Foi ele?"], ["HELENA", "Tudo indica que sim."], ["PEDRO", "Então por que você está com essa cara?"], ["HELENA", "Porque \"tudo indica\" não é a mesma coisa que \"foi\". Seu avô dizia que o caso mais perigoso é o que fica pronto rápido demais."], ["PEDRO", "Vovô falava isso sobre tudo. Sobre feijão também."], ["HELENA", "E estava certo sobre feijão também."], ["*", "Pedro ri. Helena olha o relógio de couro no pulso."]]}, {"s": "EXT. CEMITÉRIO DA SAUDADE — DIA CHUVOSO", "l": [["*", "Garoa fina. Um caixão simples. Pouca gente: Dona Zuleica com um guarda-chuva preto, dois senhores do bairro, Helena um pouco afastada, debaixo de uma árvore."], ["*", "Caíque se aproxima dela."], ["CAÍQUE", "O doutor Otávio pediu pra levarem o Vinícius ao enterro. Foi negado."], ["HELENA", "A lei permite saída escoltada para enterro de pais, filhos, cônjuge ou irmão. Tio não está na lista."], ["CAÍQUE", "É duro."], ["HELENA", "É a lei."], ["*", "Um táxi para no portão. Desce uma mulher: MARISA VILELA, 58, cabelo ruivo acobreado, vestido preto de corte elegante, um lenço de seda estampado no pescoço, batom vermelho."], ["*", "Ela caminha até o caixão sem guarda-chuva. Coloca sobre ele uma rosa vermelha e um disco de vinil de bolero. Fica alguns segundos de olhos fechados."], ["*", "Dona Zuleica cutuca o senhor ao lado."], ["ZULEICA", "(sussurrando) Quem é essa?"], ["SENHOR", "Nunca vi."], ["*", "Helena dá um passo na direção da mulher. Marisa abre os olhos, vira-se e caminha de volta ao táxi sem pressa."], ["HELENA", "Senhora! Um minuto!"], ["*", "A porta do táxi bate. O carro sai na chuva. Helena fica parada, olhando a rosa vermelha sobre o caixão."], ["CAÍQUE", "Doutora?"], ["HELENA", "Pegue a placa daquele táxi."], ["CAÍQUE", "Eu... não peguei."], ["*", "Helena olha para ele. Caíque guarda o tablet, envergonhado."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — NOITE", "l": [["*", "Chuva na janela. Iara entra com uma pasta. Helena está diante do quadro de cortiça. Agora há um post-it novo, escrito à mão: \"Mulher do enterro. Quem?\""], ["IARA", "Vim avisar que vou oferecer a denúncia contra Vinícius Mendes amanhã. Homicídio qualificado: veneno e motivo torpe."], ["HELENA", "A senhora tem o suficiente para denunciar."], ["IARA", "E a senhora?"], ["HELENA", "Eu ainda não tenho o suficiente para dormir."], ["IARA", "Delegada, quem decide se ele é culpado não somos nós. São sete jurados, no Tribunal do Júri. A Constituição manda: crime doloso contra a vida é julgado pelo povo."], ["HELENA", "Então eu vou entregar ao povo a história inteira. Não só a metade que parece pronta."], ["*", "Iara olha o post-it."], ["IARA", "Quem é?"], ["HELENA", "Ainda não sei. Mas ela levou um disco de bolero para o enterro. E o Seu Jairo saía para dançar toda quinta."]]}, {"s": "INT. CASA DE JAIRO — SALA — NOITE", "l": [["*", "Casa às escuras, lacres na porta da cozinha. Helena entra sozinha com uma lanterna. Para diante da estante de discos. Pega um, ao acaso. Coloca na vitrola antiga. O bolero do primeiro dia enche a sala vazia."], ["*", "Ela anda pela sala. Na mesa do telefone, um calendário de parede de uma farmácia do bairro. Todas as quintas-feiras dos últimos dois meses estão marcadas com uma florzinha desenhada a caneta vermelha."], ["*", "Helena tira uma foto do calendário. No quarto, atrás da porta, um terno escuro pendurado num cabide, com um lenço vermelho no bolso do paletó. No chão, uma caixa de sapatos vazia com a etiqueta de uma loja de artigos de dança."], ["*", "Helena senta na poltrona onde, de manhã, interrogou Vinícius. Fecha os olhos e ouve a música."], ["HELENA", "(para si) Quem era a sua flor, Seu Jairo?"], ["*", "O disco chega ao fim e a agulha fica girando no silêncio."]]}, {"s": "INT. CADEIA PÚBLICA — PARLATÓRIO — NOITE", "l": [["*", "Divisória de vidro, telefones de parede. O AGENTE BRÁULIO, 45, traz Vinícius, de uniforme bege. Do outro lado, Otávio."], ["BRÁULIO", "Vinte minutos, doutor."], ["OTÁVIO", "Obrigado, Bráulio."], ["*", "Vinícius pega o fone. Está mais magro em três dias."], ["VINÍCIUS", "Eles vão me condenar, né?"], ["OTÁVIO", "Ainda não tem julgamento, Vinícius. Tem acusação. Vamos por partes. Me conta a manhã de novo. Cada detalhe."], ["VINÍCIUS", "Eu acordei, passei o café no coador, ele entrou cantando, sentou, colocou o açúcar..."], ["OTÁVIO", "Quem colocou o açúcar?"], ["VINÍCIUS", "Ele. Sempre ele. Do pote azul. Era da minha tia, ele não deixava ninguém mexer."], ["OTÁVIO", "E você? Toma café com açúcar?"], ["VINÍCIUS", "Eu? Nunca. Desde moleque. Café é sem açúcar."], ["*", "Otávio fica imóvel com o fone no ouvido."], ["OTÁVIO", "Você bebeu o mesmo café?"], ["VINÍCIUS", "Bebi meia xícara. Antes de ele descer. Do mesmo bule."], ["*", "Otávio larga a caneta."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — MADRUGADA", "l": [["*", "Helena sozinha, com as fotos da cena do crime espalhadas na mesa. Ela para numa delas: a mesa da cozinha, o pote de açúcar azul no centro."], ["*", "O celular toca. É Otávio."], ["OTÁVIO", "(telefone) Delegada, desculpe a hora. O Vinícius tomou café do mesmo bule. E ele não usa açúcar."], ["*", "Helena já está olhando para a foto do pote azul."], ["HELENA", "Eu sei, doutor. Eu estou olhando para ele agora."], ["*", "Ela desliga e liga para outro número."], ["HELENA", "Lúcia, desculpe acordar você. O açucareiro azul. Já analisou?"], ["LÚCIA", "(telefone, sonolenta) Está na fila. Posição vinte e dois."], ["HELENA", "Passe ele para a posição um."]]}, {"s": "TELA PRETA", "l": [["VOZ", "Matar alguém. Duas palavras, a pena mais alta do Código Penal. Mas antes do artigo vem o fato. E o fato, neste caso, ainda está pela metade. No próximo episódio: quando um soco vira lesão grave. Artigo 129."]]}, {"s": "O VEREDITO — CARDS NARRADOS", "l": [["*", "Tela preta. Os cards do Veredito surgem um a um, com o texto em laranja e branco, enquanto a narradora lê."], ["VOZ", "Artigo 121 do Código Penal: matar alguém. É o crime de homicídio. Na forma simples, a pena é de seis a vinte anos de reclusão."], ["VOZ", "O parágrafo segundo traz as qualificadoras. Entre elas, o motivo torpe, como matar por herança, e o uso de veneno, que é meio insidioso porque a vítima não percebe. Basta uma qualificadora para a pena subir para doze a trinta anos. O homicídio qualificado é crime hediondo."], ["VOZ", "Se o crime foi cometido por relevante valor moral ou social, ou sob violenta emoção logo depois de injusta provocação da vítima, é o homicídio privilegiado: a pena diminui de um sexto a um terço. Se não houve intenção, é homicídio culposo: detenção de um a três anos."], ["VOZ", "Todo crime doloso contra a vida é julgado pelo Tribunal do Júri, formado por sete jurados. E a prisão preventiva, decretada antes do julgamento, não é pena: é uma medida de cautela que só se mantém enquanto o motivo existir."], ["VOZ", "Não confunda: o latrocínio, que é matar para roubar, é crime contra o patrimônio. E o feminicídio, desde 2024, é crime autônomo, no artigo 121-A."]]}]}, "129": {"dur": 20, "logline": "Uma fechada no trânsito vira briga e um soco derruba o motoboy Edson na calçada. Com o punho quebrado e a namorada grávida de sete meses, ele recebe uma oferta de R$ 5 mil para esquecer tudo. Mas o tamanho de uma lesão só se conhece depois de 30 dias.", "twist": "Lesão leve depende da vontade da vítima e cabe acordo no Juizado Especial. Mas quando a vítima fica mais de 30 dias sem poder trabalhar, a lesão é grave: a pena vai a 1 a 5 anos de reclusão e o processo segue mesmo que a vítima desista. É por isso que existe o exame complementar, feito depois do 30º dia. E quem empurra só para se soltar de uma agressão age em legítima defesa.", "guests": [{"n": "Edson Lima", "r": "Vítima, motoboy, 31 anos", "d": "Trabalhador, orgulhoso, de pouca fala, carinhoso com a namorada"}, {"n": "Kelly Santos", "r": "Namorada de Edson, 28 anos, grávida de sete meses", "d": "Prática, chora fácil e se recompõe rápido, quer proteger a família"}, {"n": "Marcelo Torres", "r": "Agressor, empresário, 44 anos", "d": "Pavio curto, acostumado a resolver tudo com dinheiro"}, {"n": "Dr. Fausto Leme", "r": "Advogado de Marcelo, 55 anos", "d": "Educado, frio, sempre oferecendo um acordo"}, {"n": "Dona Fátima", "r": "Florista e testemunha, 63 anos", "d": "Corajosa, fala o que pensa, filma tudo com o celular"}, {"n": "Dr. Anselmo", "r": "Médico-legista do IML, 60 anos", "d": "Bonachão, didático"}, {"n": "Vinícius Mendes", "r": "Réu do caso Jairo, 39 anos", "d": "Músico endividado, impulsivo e irônico quando tem medo. O suspeito perfeito."}], "scenes": [{"s": "ANTERIORMENTE", "l": [["*", "Imagens rápidas do episódio anterior, com a voz da narradora por cima."], ["VOZ", "Anteriormente, na JURISPLAY. Seu Jairo morreu envenenado depois do café da manhã. O sobrinho Vinícius, endividado e único herdeiro, foi preso. No enterro, uma mulher ruiva deixou uma rosa e um disco de bolero, e desapareceu. E o Vinícius contou ao defensor um detalhe: ele nunca usa açúcar."], ["*", "Corte para a cena de abertura."]]}, {"s": "EXT. CRUZAMENTO DA AVENIDA AURORA COM A RUA DAS FLORES — FIM DE TARDE", "l": [["*", "Hora do rush. Buzinas. Na esquina, uma banca de flores coloridas. DONA FÁTIMA, 63, avental verde, arruma girassóis num balde."], ["*", "EDSON, 31, motoboy, bolsa térmica nas costas, costura entre os carros. Uma SUV preta muda de faixa sem sinalizar e o fecha. Edson freia, a moto derrapa, ele quase cai. Bate a mão aberta no vidro da SUV."], ["EDSON", "Ô! Tá cego? Quase me mata!"], ["*", "O sinal fecha. A porta da SUV se abre. MARCELO TORRES, 44, camisa polo de grife, relógio grande, desce bufando."], ["MARCELO", "Bateu no meu carro? Você bateu no meu carro?"], ["EDSON", "Eu bati no vidro. O senhor me jogou pra fora da pista!"], ["*", "Marcelo agarra Edson pela gola da jaqueta. Edson empurra o peito dele com as duas mãos para se soltar. Marcelo recua, o cotovelo raspa na porta aberta da SUV."], ["MARCELO", "Ah, é assim?"], ["*", "Marcelo dá um soco no rosto de Edson. Edson cai para trás, tenta se apoiar com a mão. O punho bate no meio-fio. Um estalo seco."], ["*", "Dona Fátima larga o balde. Já está com o celular na mão, filmando."], ["FÁTIMA", "Covarde! Eu vi! Eu vi tudo!"], ["*", "Marcelo olha em volta, entra na SUV e arranca no sinal amarelo. Edson, no chão, segura o punho torto, sem conseguir respirar de dor."], ["*", "Corte seco para preto."]]}, {"s": "VINHETA", "l": [["*", "O triângulo laranja da JURISPLAY. ART. 129. \"Fechada no Cruzamento\"."]]}, {"s": "INT. HOSPITAL MUNICIPAL — CORREDOR DO PRONTO-SOCORRO — NOITE", "l": [["*", "Edson sentado numa cadeira de plástico, braço direito engessado até o cotovelo, olho roxo. KELLY, 28, grávida de sete meses, chega quase correndo, ofegante."], ["KELLY", "Edson! Meu Deus, olha teu rosto."], ["EDSON", "Calma. Senta. Não pode ficar nervosa."], ["KELLY", "Não pode ficar nervosa? Você quebrou o braço!"], ["EDSON", "O punho. Foi o punho."], ["KELLY", "E vai pilotar como?"], ["*", "Edson não responde. Kelly se senta ao lado dele, a mão na barriga."], ["KELLY", "O aluguel vence dia dez. O enxoval está pela metade."], ["EDSON", "Eu dou um jeito."], ["KELLY", "Com uma mão só?"], ["*", "Ele encosta a cabeça no ombro dela. Os dois ficam em silêncio, ouvindo o barulho do hospital."]]}, {"s": "INT. APARTAMENTO DE EDSON E KELLY — QUARTO DO BEBÊ — NOITE", "l": [["*", "Quitinete apertada. Num canto, um berço de madeira pela metade, peças espalhadas no chão, um manual de montagem aberto. Edson, com o braço engessado numa tipoia, tenta segurar uma tábua com o joelho e apertar um parafuso com a mão esquerda. A chave de fenda escapa e cai."], ["*", "Kelly aparece na porta com um envelope na mão."], ["KELLY", "Chegou do proprietário. Aviso de reajuste do aluguel."], ["EDSON", "Quanto?"], ["KELLY", "Cento e oitenta a mais. A partir do mês que vem."], ["*", "Edson pega a chave de fenda de novo. Tenta outra vez. Não consegue."], ["EDSON", "Eu monto isso amanhã."], ["KELLY", "Você disse isso ontem."], ["EDSON", "Então eu monto isso depois de amanhã!"], ["*", "O grito fica no ar. Kelly coloca a mão na barriga. Edson larga a chave de fenda e senta no chão, no meio das peças."], ["EDSON", "Desculpa. Não foi com você."], ["KELLY", "Eu sei com quem foi."], ["*", "Ela senta ao lado dele, com dificuldade por causa da barriga. Pega a chave de fenda e o parafuso."], ["KELLY", "Você segura a tábua. Eu aperto."], ["EDSON", "Grávida de sete meses montando berço."], ["KELLY", "E você, com uma mão só, segurando. Somos uma equipe excelente."], ["*", "Ele ri, finalmente. Os dois montam a primeira lateral do berço juntos."]]}, {"s": "INT. 3ª DELEGACIA — RECEPÇÃO — MANHÃ", "l": [["*", "Marcelo Torres, impecável, entra com DR. FAUSTO LEME, 55, terno azul-marinho, pasta preta. Caíque está no balcão."], ["FAUSTO", "Bom dia. Meu cliente veio registrar uma ocorrência. Ele foi agredido ontem por um motociclista."], ["CAÍQUE", "Agredido?"], ["*", "Marcelo arregaça a manga e mostra um arranhão no cotovelo."], ["MARCELO", "O sujeito bateu no meu carro e me empurrou contra a porta."], ["*", "Helena sai da sala dela com uma xícara de café, para no meio do corredor e observa a cena."], ["CAÍQUE", "Engraçado. Ontem à noite também registraram uma ocorrência sobre esse cruzamento. Só que quem estava com o punho quebrado era o motociclista."], ["FAUSTO", "Uma briga tem dois lados, investigador."], ["HELENA", "Às vezes tem dois lados e um soco só."], ["*", "Todos se viram para ela."], ["HELENA", "Bom dia. Helena Rocha, delegada. Os dois querem ser vítima. Ótimo. Vou ouvir os dois. Fato primeiro."], ["CAÍQUE", "(baixinho) Artigo depois."]]}, {"s": "INT. TORRES IMPORTADORA — ESCRITÓRIO DE MARCELO — DIA", "l": [["*", "Escritório envidraçado no alto de um prédio comercial. Marcelo, de pé, olha a cidade. Dr. Fausto, sentado, folheia a cópia do boletim de ocorrência."], ["MARCELO", "Eu não vou perder meu tempo com um motoboy, Fausto. Resolve."], ["FAUSTO", "Vou resolver, Marcelo. Mas resolver do jeito certo. Pelo que está no boletim, é lesão corporal leve. Pena de três meses a um ano. Vai para o Juizado Especial."], ["MARCELO", "E daí?"], ["FAUSTO", "E daí que, no Juizado, lesão leve depende da representação da vítima. Se a vítima não quiser processar, não tem processo. E existe a composição civil dos danos: a gente paga uma indenização, o juiz homologa e a vítima perde o direito de representar. Acabou. Nem antecedente fica."], ["MARCELO", "Quanto?"], ["FAUSTO", "Cinco mil é um bom começo para quem ganha por entrega."], ["*", "Marcelo vira-se para ele, satisfeito."], ["MARCELO", "Eu disse. Tudo se resolve."], ["FAUSTO", "Tudo se resolve se for lesão leve."], ["MARCELO", "E se não for?"], ["FAUSTO", "Se for grave, o processo anda sozinho, com ou sem vontade da vítima, e sai do Juizado. Por isso eu quero o acordo assinado antes do trigésimo dia."], ["MARCELO", "Por que trinta dias?"], ["FAUSTO", "Porque é depois dele que o médico-legista descobre se o seu soco quebrou só um punho ou quebrou um emprego."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — MANHÃ", "l": [["*", "Edson e Kelly sentados em frente à mesa. Helena com o boletim de ocorrência."], ["HELENA", "Seu Edson, o que aconteceu com o senhor tem nome no Código Penal. Lesão corporal. Artigo 129: \"Ofender a integridade corporal ou a saúde de outrem.\""], ["EDSON", "Então ele vai preso?"], ["HELENA", "Depende do tamanho da lesão. A lei divide em leve, grave e gravíssima. Lesão leve tem pena de três meses a um ano de detenção. É crime de menor potencial ofensivo: vai para o Juizado Especial Criminal."], ["KELLY", "E isso é bom ou ruim?"], ["HELENA", "É mais rápido e mais brando. E, na lesão leve, o processo só anda se a vítima quiser. Chama-se representação. O senhor tem seis meses para dizer se quer processar."], ["EDSON", "E se for grave?"], ["HELENA", "Aí a pena é de um a cinco anos de reclusão. E o processo anda com ou sem a vontade da vítima. O Estado assume."], ["EDSON", "E como a senhora sabe se é leve ou grave?"], ["HELENA", "Eu não sei. Quem diz é o médico-legista, no exame de corpo de delito. O senhor vai ao IML hoje."]]}, {"s": "INT. IML — SALA DE EXAME — DIA", "l": [["*", "DR. ANSELMO, 60, jaleco amarrotado, examina o gesso de Edson e as radiografias contra a luz."], ["ANSELMO", "Fratura no rádio distal. O cirurgião colocou uma placa. Hematoma na face. Muito bem."], ["EDSON", "Muito bem pra quem, doutor?"], ["ANSELMO", "Desculpe. Força do hábito. Quanto tempo o médico disse que você fica sem pilotar?"], ["EDSON", "Ele falou em dois meses. Mas eu volto antes. Eu preciso."], ["ANSELMO", "Hoje, meu laudo vai dizer o que eu vejo hoje: ofensa à integridade corporal. Mas o Código diz que, se a vítima fica incapacitada para as ocupações habituais por mais de trinta dias, a lesão é grave."], ["EDSON", "E como prova isso?"], ["ANSELMO", "Com outro exame. O exame complementar. Você volta aqui depois do trigésimo dia. Não antes. Se ainda não puder trabalhar, eu escrevo isso."], ["*", "Edson olha o gesso."], ["ANSELMO", "Não volte a pilotar escondido, rapaz. O seu punho é a prova."]]}, {"s": "EXT. 3ª DELEGACIA — ESTACIONAMENTO — TARDE", "l": [["*", "Edson e Kelly caminham até o ponto de ônibus. Dr. Fausto os alcança, sorridente."], ["FAUSTO", "Seu Edson? Fausto Leme. Advogado do senhor Marcelo. Posso tomar dois minutos?"], ["KELLY", "Fala."], ["FAUSTO", "Meu cliente se arrependeu. Foi um momento de nervoso no trânsito. Ele quer compensar o senhor. Cinco mil reais, hoje, por transferência. O senhor assina um termo dizendo que não tem interesse em processar e todo mundo segue a vida."], ["*", "Kelly olha para Edson. Cinco mil reais. Ela faz contas de cabeça."], ["EDSON", "E o meu braço?"], ["FAUSTO", "Cinco mil compram muita fisioterapia."], ["EDSON", "Eu vou pensar."], ["FAUSTO", "Pense rápido. A proposta vale até sexta."], ["*", "Fausto se afasta. Kelly segura a mão boa de Edson."], ["KELLY", "Edson, é o aluguel. É o berço."], ["EDSON", "E se eu assinar e depois ele fizer isso com outro?"], ["*", "Kelly não tem resposta."]]}, {"s": "EXT. RUA DE EDSON — AMANHECER", "l": [["*", "Cinco e meia da manhã. Edson, de capacete, tenta tirar a moto da garagem do prédio empurrando com a mão esquerda. A mão direita, com a tala, apoiada no guidão sem força."], ["*", "Kelly aparece no portão, de camisola e chinelo, descabelada."], ["KELLY", "Você ficou louco?"], ["EDSON", "Só umas entregas. Perto de casa. Quatro horas."], ["KELLY", "Com o punho quebrado?"], ["EDSON", "O aplicativo não paga atestado, Kelly!"], ["KELLY", "E o médico do IML? O que ele falou? Que o seu punho é a prova! Se você pilotar e alguém te fotografar, como é que você vai provar que não pode trabalhar?"], ["*", "Edson para. Tira o capacete."], ["EDSON", "E se eu não pilotar, como é que eu pago o aluguel?"], ["KELLY", "A gente dá um jeito. A minha mãe empresta. A minha cliente da escova paga adiantado. Mas você não sobe nessa moto."], ["*", "Os dois se encaram. Edson empurra a moto de volta para dentro da garagem. A tala bate no guidão e ele geme de dor. Kelly o abraça por trás, com a barriga entre os dois."]]}, {"s": "EXT. BANCA DE FLORES DE DONA FÁTIMA — DIA", "l": [["*", "Dona Fátima corta talos de rosas. Um homem de terno escuro, óculos escuros, para em frente à banca. Não olha as flores."], ["HOMEM", "A senhora trabalha aqui todo dia?"], ["FÁTIMA", "Desde 1989. Vai levar alguma coisa?"], ["HOMEM", "Na semana passada teve uma confusão aqui no cruzamento. Um motoboy caiu. A senhora viu?"], ["*", "Fátima para de cortar os talos. Olha para ele por baixo do chapéu de palha."], ["FÁTIMA", "Eu vejo muita coisa."], ["HOMEM", "Se a senhora tivesse filmado alguma coisa... seria melhor apagar. Para evitar dor de cabeça. Ninguém gosta de ir a delegacia, perder dia de trabalho."], ["*", "Fátima larga a tesoura sobre o balcão, devagar."], ["FÁTIMA", "O senhor está me ameaçando?"], ["HOMEM", "Estou dando um conselho."], ["FÁTIMA", "Pois eu vou dar outro. O senhor está na frente de uma câmera agora."], ["*", "Ela aponta para o celular, apoiado num vaso, gravando. O homem olha o celular, olha para ela, e vai embora sem dizer nada."], ["*", "Fátima pega o telefone e procura na agenda um cartão que alguém deixou dias antes: \"Investigador Caíque Moura — 3ª DP\"."]]}, {"s": "INT. INSTITUTO DE CRIMINALÍSTICA — LABORATÓRIO — DIA", "l": [["*", "Luz branca, bancadas de aço. Lúcia diante de um monitor com gráficos. Helena e Caíque entram. Caíque traz dois copos de café de papelaria."], ["CAÍQUE", "Trouxe café. O seu é sem açúcar."], ["LÚCIA", "Como você sabe?"], ["CAÍQUE", "Perguntei para a sua equipe."], ["LÚCIA", "Isso é investigação ou perseguição?"], ["CAÍQUE", "Depende de você aceitar o café."], ["*", "Lúcia pega o copo. Não agradece, mas também não devolve. Vira o monitor para Helena."], ["LÚCIA", "O açucareiro azul do Seu Jairo. Pesticida misturado ao açúcar, de cima até o fundo do pote. Alguém misturou com calma."], ["HELENA", "E o bule?"], ["LÚCIA", "Limpo. O café do bule não tinha nada. O veneno entrou na xícara junto com as duas colheres de açúcar."], ["CAÍQUE", "Então o Vinícius tomou o café do bule e não morreu porque não usa açúcar."], ["LÚCIA", "Exato. Quem envenenou o açúcar sabia que só o Seu Jairo usava aquele pote."], ["HELENA", "E não precisava estar na casa naquela manhã. Podia ter feito isso dias antes."], ["CAÍQUE", "Qualquer um com acesso à cozinha."], ["*", "Helena pega o paletó."], ["HELENA", "Caíque, quantas chaves tem aquela casa?"]]}, {"s": "INT. CAFÉ DO FÓRUM — FIM DE TARDE", "l": [["*", "Iara no balcão, lendo um processo. Otávio se encosta ao lado dela."], ["OTÁVIO", "O veneno estava no açúcar."], ["IARA", "Boa tarde para você também."], ["OTÁVIO", "O bule estava limpo. Meu cliente bebeu o mesmo café e está vivo. Você vai retirar a denúncia?"], ["IARA", "Não. Isso não inocenta o Vinícius. Ele morava lá. Sabia que o tio usava aquele pote."], ["OTÁVIO", "Então por que não colocou no café? Era mais fácil."], ["IARA", "Porque queria parecer exatamente o que você está dizendo agora. Inocente."], ["*", "Otávio ri, balançando a cabeça."], ["OTÁVIO", "Você ainda termina as minhas frases com uma acusação."], ["IARA", "E você ainda começa as suas com uma desculpa."], ["OTÁVIO", "Eu nunca te pedi desculpa."], ["IARA", "Esse é exatamente o problema, Otávio."], ["*", "Silêncio. O barista coloca dois cafés no balcão. Um sem açúcar. Otávio empurra o dela com dois dedos."], ["OTÁVIO", "Você não foi ao aeroporto."], ["IARA", "Você não me pediu para ir."], ["*", "Ela pega o café e sai. Otávio fica olhando a porta."]]}, {"s": "INT. CADEIA PÚBLICA — PARLATÓRIO — DIA", "l": [["*", "Otávio e Vinícius separados pelo vidro."], ["OTÁVIO", "O veneno estava no açúcar, Vinícius. O bule estava limpo."], ["*", "Vinícius solta o ar, como quem segurava a respiração havia dias."], ["VINÍCIUS", "Então eu estou livre?"], ["OTÁVIO", "Ainda não. A promotora acha que você podia saber que só o seu tio usava aquele pote."], ["VINÍCIUS", "Todo mundo que já tomou café naquela casa sabia! Ele não deixava ninguém encostar no pote da tia. Ele falava disso para qualquer visita."], ["OTÁVIO", "Quem visitava a casa?"], ["VINÍCIUS", "Ninguém. Quer dizer... ninguém que eu visse. A Dona Zuleica às vezes trazia bolo. O moço do gás. E nos últimos tempos ele saía muito, mas eu nunca vi ninguém entrar."], ["OTÁVIO", "Você trabalhava à noite?"], ["VINÍCIUS", "Tocava em bar, de quinta a sábado. Saía às oito, voltava às três."], ["OTÁVIO", "Então às quintas a casa ficava vazia."], ["VINÍCIUS", "Ficava. Por quê?"], ["*", "Otávio anota \"quintas\" e sublinha duas vezes."], ["OTÁVIO", "Porque é a terceira vez que alguém me fala de quinta-feira nesse caso."]]}, {"s": "INT. IML — SALA DE EXAME — DIA (TRINTA E UM DIAS DEPOIS)", "l": [["*", "Letreiro: \"31 dias depois\". Edson, ainda com tala no punho, faz força para fechar a mão. Não consegue. Dr. Anselmo anota."], ["ANSELMO", "Consegue segurar o guidão?"], ["EDSON", "Não, senhor."], ["ANSELMO", "Carregar a bolsa de entrega?"], ["EDSON", "Nem a sacola do mercado."], ["ANSELMO", "Fisioterapia por mais quanto tempo?"], ["EDSON", "Mais um mês, a médica disse."], ["*", "Anselmo assina o laudo e olha para Edson por cima dos óculos."], ["ANSELMO", "Incapacidade para as ocupações habituais por mais de trinta dias. Artigo 129, parágrafo primeiro, inciso um. Lesão corporal de natureza grave."], ["*", "Edson respira fundo. Não sabe se fica feliz ou triste."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — DIA", "l": [["*", "Dona Fátima entra de chapéu de palha, coloca o celular na mesa de Helena com força."], ["FÁTIMA", "Fiquei sabendo que o grandão disse que foi agredido. Então assista."], ["*", "Helena e Caíque assistem ao vídeo. Na tela: Marcelo agarra a gola de Edson, Edson empurra para se soltar, Marcelo bate o cotovelo na porta, depois o soco, a queda."], ["CAÍQUE", "Quem agarrou primeiro foi ele."], ["HELENA", "E o empurrão do Edson foi para se soltar. Moderado, contra uma agressão que estava acontecendo. Isso tem nome, Dona Fátima: legítima defesa. Artigo 25."], ["FÁTIMA", "Ou seja, o arranhão do grandão é problema do grandão."], ["HELENA", "Ou seja, o Edson não cometeu crime nenhum."], ["*", "Fátima guarda o celular, satisfeita."], ["FÁTIMA", "Eu filmo tudo naquela esquina, doutora. Até casamento."], ["*", "O celular de Helena vibra. Mensagem de Edson: \"O doutor do IML disse que é grave. E agora?\""], ["*", "Helena pega o telefone e liga."], ["HELENA", "Agora, Seu Edson, o senhor não precisa mais assinar nada. Nem aceitar nada. Lesão grave não depende da sua vontade. O processo vai andar."], ["EDSON", "(telefone) E os cinco mil?"], ["HELENA", "O senhor pode aceitar uma indenização se quiser. Mas ela não apaga o crime. E o juiz ainda pode fixar um valor mínimo de reparação na sentença."]]}, {"s": "INT. CLÍNICA DE FISIOTERAPIA DO SUS — DIA", "l": [["*", "Sala ampla com macas e aparelhos. Edson aperta uma bolinha de borracha com a mão direita, suando. Helena entra, sem blazer, e se senta na cadeira ao lado."], ["EDSON", "A senhora aqui?"], ["HELENA", "Vim avisar pessoalmente. A Dona Fátima tem um vídeo da briga. E um homem foi até a banca dela pedir para apagar."], ["EDSON", "O advogado dele?"], ["HELENA", "A gente vai descobrir quem era. Coagir testemunha é outro crime. Mas o vídeo está guardado, e cópia na delegacia."], ["*", "Edson aperta a bolinha. Não consegue fechar a mão por completo."], ["EDSON", "Doutora, a senhora acha que eu devia ter aceitado os cinco mil?"], ["HELENA", "Eu acho que a decisão é sua. Mas agora ela nem existe mais. Lesão grave não se resolve com acordo entre as partes."], ["EDSON", "Meu pai foi motoboy também. Antes de existir aplicativo. Ele dizia que motoboy é invisível: ninguém vê a gente até a gente cair."], ["HELENA", "O meu pai era investigador. Ele dizia que a vítima também é invisível: ninguém vê até alguém olhar de verdade."], ["*", "Edson olha para ela. Helena aponta para a bolinha."], ["HELENA", "Mais dez. A fisioterapeuta está olhando."]]}, {"s": "INT. FÓRUM — 2ª VARA CRIMINAL — DIA", "l": [["*", "Audiência. Marta preside. Iara acusa. Dr. Fausto ao lado de Marcelo, de terno escuro agora. Edson e Kelly no banco do público."], ["IARA", "Excelência, o réu deu um soco no rosto da vítima, que caiu e fraturou o punho. O laudo complementar comprova incapacidade para as ocupações habituais por mais de trinta dias. Lesão corporal grave, artigo 129, parágrafo primeiro, inciso um. Pena de um a cinco anos de reclusão."], ["MARTA", "Defesa."], ["FAUSTO", "Excelência, meu cliente deu um soco. Um. Ninguém aqui diz que ele quis quebrar o punho de ninguém. A fratura foi causada pela queda, pelo meio-fio. Um acidente. Se houve crime, foi lesão leve."], ["IARA", "Doutor, quem dá um soco aceita o risco de a vítima cair. A lei não exige que o réu quisesse a fratura. Basta que ele quisesse ferir e que o resultado grave decorra do que ele fez."], ["FAUSTO", "E a provocação? A vítima bateu no carro do meu cliente."], ["IARA", "Bateu no vidro com a mão aberta, depois de quase ser jogada para fora da pista. Isso não autoriza ninguém a agredir."], ["*", "Marta tira os óculos e olha para Marcelo."], ["MARTA", "Senhor Marcelo, um soco não é pequeno porque foi um só. Ele é do tamanho do estrago que causou."], ["MARTA", "Julgo procedente a denúncia. Condeno o réu por lesão corporal de natureza grave a um ano e quatro meses de reclusão, em regime aberto. Por ser crime com violência contra a pessoa, não cabe trocar a pena de prisão por penas alternativas. Concedo a suspensão condicional da pena por dois anos, com condições. E fixo em doze mil reais o valor mínimo para reparação dos danos à vítima."], ["*", "Kelly aperta a mão de Edson. Marcelo olha para Fausto, que já fecha a pasta."]]}, {"s": "EXT. BANCA DE FLORES DE DONA FÁTIMA — FIM DE TARDE", "l": [["*", "Edson, com a tala menor, escolhe um girassol no balde. Dona Fátima finge que não está vendo. Kelly espera na calçada."], ["EDSON", "Quanto é?"], ["FÁTIMA", "Pra quê?"], ["EDSON", "Pra pedir uma pessoa em casamento."], ["*", "Fátima tira o girassol mais bonito do balde e entrega."], ["FÁTIMA", "Esse é por conta da casa. E eu filmo."], ["*", "Edson vai até Kelly. Não consegue se ajoelhar direito por causa do braço. Ela ri, ele ri. Ele estende o girassol e uma aliança simples."], ["EDSON", "Eu não tenho discurso."], ["KELLY", "Você nunca teve. Sim."], ["*", "Dona Fátima filma, emocionada, enxugando o olho com a manga do avental."]]}, {"s": "INT. CASA DE JAIRO — CORREDOR DE ENTRADA — NOITE", "l": [["*", "Casa vazia, lacres da polícia. Helena acende a luz. Ao lado da porta, um porta-chaves de madeira entalhado com três ganchos."], ["*", "No primeiro gancho, um molho de chaves com chaveiro de time de futebol. No segundo, um molho com chaveiro de bolero, uma pequena castanhola."], ["*", "O terceiro gancho está vazio. Um retângulo mais claro na madeira mostra onde algo ficou pendurado por muito tempo."], ["CAÍQUE", "(entrando) O molho do Vinícius está com a gente. Esses dois são do Seu Jairo."], ["HELENA", "E o terceiro?"], ["CAÍQUE", "Terceiro?"], ["*", "Helena passa o dedo no gancho vazio."], ["HELENA", "Alguém tinha a terceira chave desta casa."]]}, {"s": "TELA PRETA", "l": [["VOZ", "Um soco. Um meio-fio. Trinta dias. Na lesão corporal, a pena acompanha o estrago. No próximo episódio: quando uma mensagem de madrugada vira crime, e quando não vira. Artigo 147."]]}, {"s": "O VEREDITO — CARDS NARRADOS", "l": [["*", "Tela preta. Os cards do Veredito surgem um a um."], ["VOZ", "Artigo 129 do Código Penal: ofender a integridade corporal ou a saúde de outrem. É o crime de lesão corporal."], ["VOZ", "A lesão leve tem pena de três meses a um ano de detenção. É infração de menor potencial ofensivo, julgada no Juizado Especial, e o processo depende da representação da vítima."], ["VOZ", "A lesão é grave quando causa incapacidade para as ocupações habituais por mais de trinta dias, perigo de vida, debilidade permanente de membro, sentido ou função, ou aceleração de parto. A pena é de um a cinco anos de reclusão, e o processo não depende da vontade da vítima. A incapacidade por mais de trinta dias se prova com o exame complementar, feito depois do trigésimo dia."], ["VOZ", "A lesão gravíssima, como a perda de um membro ou a deformidade permanente, tem pena de dois a oito anos. A lesão seguida de morte, de quatro a doze anos."], ["VOZ", "E quem se defende de uma agressão que está acontecendo, usando os meios necessários com moderação, age em legítima defesa e não comete crime."]]}]}, "147": {"dur": 21, "logline": "Depois que uma sociedade acaba mal, Rogério começa a receber mensagens de madrugada. Uma promete um processo. Outra diz que sabe onde o filho dele estuda. Só uma delas é crime. Na mesma semana, a delegada Helena recebe uma mensagem parecida, com o nome do próprio filho.", "twist": "Ameaça é prometer um mal injusto e grave. Prometer um processo é exercer um direito, e isso não é crime. Na ameaça comum, a pena é de 1 a 6 meses e o processo depende da representação da vítima. Mas a mesma ameaça, feita contra uma delegada para atrapalhar uma investigação, vira outro crime: coação no curso do processo, com pena de 1 a 4 anos, e o Estado age sozinho.", "guests": [{"n": "Rogério Alves", "r": "Vítima, dono de academia, 46 anos", "d": "Esquentado, mas pai devotado; o medo o deixa agressivo"}, {"n": "Fábio Rangel", "r": "Ex-sócio, 48 anos", "d": "Ressentido e barulhento, mas incapaz de machucar alguém"}, {"n": "Bruno Kalil", "r": "Sócio atual de Rogério, 35 anos", "d": "Simpático, ambicioso, manipulador"}, {"n": "Pedro Rocha", "r": "Filho de Helena, 19 anos", "d": "Filho de Helena, estudante de Engenharia. Cozinha macarrão medido no grama."}, {"n": "Vinícius Mendes", "r": "Réu do caso Jairo, 39 anos", "d": "Músico endividado, impulsivo e irônico quando tem medo. O suspeito perfeito."}, {"n": "Seu Alcides", "r": "Dono do Sabor da Praça", "d": "Dono do Sabor da Praça. Conhece todo mundo pelo nome e dança bolero às quintas."}, {"n": "Cida", "r": "Irmã de Fábio, 52 anos", "d": "Brava e leal ao irmão"}, {"n": "Renata", "r": "Ex-mulher de Rogério, enfermeira, 42 anos", "d": "Firme, protetora, racional"}], "scenes": [{"s": "ANTERIORMENTE", "l": [["*", "Imagens rápidas dos episódios anteriores."], ["VOZ", "Anteriormente, na JURISPLAY. O laudo mostrou que o veneno que matou Seu Jairo estava no açucareiro, não no café. O sobrinho Vinícius bebeu do mesmo bule e sobreviveu. O defensor Otávio assumiu a defesa dele, e a promotora Iara, a acusação. Os dois já foram um casal. E na casa de Jairo havia um gancho vazio: alguém tinha a terceira chave."], ["*", "Corte para a cena de abertura."]]}, {"s": "INT. APARTAMENTO DE ROGÉRIO — QUARTO — MADRUGADA", "l": [["*", "Escuro total. Um celular acende na mesa de cabeceira: 3:12. ROGÉRIO, 46, careca, barba ruiva, acorda e pega o aparelho."], ["*", "Na tela, um número desconhecido: \"Sei onde o Theo estuda. Escola Pequeno Príncipe. Portão azul. Seria uma pena se um dia ele não chegasse em casa.\""], ["*", "Rogério se levanta de uma vez. Atravessa o corredor descalço. Abre devagar a porta do quarto do filho: uma silhueta pequena dormindo sob o edredom de dinossauros, um abajur de estrelas girando."], ["*", "Ele fecha a porta. Encosta a testa nela. Volta para a sala e rola a tela do celular até uma conversa salva como \"Fábio\". Mensagens de dias antes:"], ["*", "\"Você me roubou, Rogério.\" \"Doze anos de sociedade e você me põe na rua.\" \"Vou te pôr na Justiça e tirar tudo de você.\""], ["ROGÉRIO", "(para si) Você passou do limite, Fábio."], ["*", "Ele digita \"Eu vou acabar com você\" e para, o dedo sobre o botão de enviar. Apaga. Joga o celular no sofá."], ["*", "Corte seco para preto."]]}, {"s": "VINHETA", "l": [["*", "O triângulo laranja da JURISPLAY. ART. 147. \"Mensagem das 3 da Manhã\"."]]}, {"s": "INT. APARTAMENTO DE HELENA — SALA — MADRUGADA", "l": [["*", "Três e doze da manhã. A mesma hora da mensagem de Rogério. Helena, sem conseguir dormir, sentada no escuro da sala com o celular na mão. A mensagem anônima aberta na tela."], ["*", "Ela se levanta, vai até a porta do quarto de Pedro, abre uma fresta. Pedro dorme de boca aberta, um livro de cálculo no peito."], ["*", "Helena fecha a porta. Volta à sala. Tira o relógio de couro do pulso e o segura nas duas mãos."], ["HELENA", "(baixinho, para o relógio) Você recebia dessas, pai?"], ["*", "Silêncio. Ela coloca o relógio de volta no pulso."], ["HELENA", "Recebia. E nunca fechou um caso por medo."], ["*", "Ela abre o notebook na mesa da sala e começa a escrever: \"Representação. Ameaça contra a autoridade policial. Caso Jairo Mendes.\""]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — MANHÃ", "l": [["*", "Rogério, de agasalho esportivo, coloca o celular na mesa de Helena. Caíque ao lado."], ["ROGÉRIO", "Foi o Fábio, meu ex-sócio. A gente desfez a sociedade da academia mês passado. Ele acha que eu passei a perna nele. Agora está ameaçando o meu filho."], ["HELENA", "Posso?"], ["*", "Ela rola as mensagens com calma. Lê em voz alta."], ["HELENA", "\"Vou te pôr na Justiça e tirar tudo de você.\" Esta é do número salvo como Fábio."], ["ROGÉRIO", "Ameaça!"], ["HELENA", "Não, senhor. Isso não é crime."], ["ROGÉRIO", "Como não?"], ["HELENA", "O artigo 147 diz: \"Ameaçar alguém, por palavra, escrito ou gesto, ou qualquer outro meio simbólico, de causar-lhe mal injusto e grave.\" Injusto, Seu Rogério. Processar alguém é um direito de qualquer pessoa. É um mal justo. Pode ser desagradável, mas não é crime."], ["*", "Rogério cruza os braços. Helena rola até a outra mensagem."], ["HELENA", "Agora esta, do número desconhecido. \"Sei onde o Theo estuda. Seria uma pena se um dia ele não chegasse em casa.\" Isso é promessa de mal injusto e grave contra o senhor, por meio do seu filho. Isso é ameaça."], ["CAÍQUE", "E o crime existe mesmo que nada aconteça. Basta ser capaz de causar medo."], ["ROGÉRIO", "Então prende ele."], ["HELENA", "Primeiro, o senhor precisa dizer formalmente que quer o processo. Na ameaça, a lei exige a representação da vítima. O senhor tem seis meses para isso."], ["ROGÉRIO", "Eu assino agora."], ["HELENA", "E segundo: a mensagem não veio do número do Fábio."], ["ROGÉRIO", "Ele usou outro chip! É óbvio!"], ["HELENA", "Óbvio é uma palavra que eu não uso antes de terminar a investigação."]]}, {"s": "EXT. ESCOLA PEQUENO PRÍNCIPE — PORTÃO AZUL — MANHÃ", "l": [["*", "Sete da manhã. Fila de carros, crianças de mochila entrando. Rogério, dentro do carro estacionado do outro lado da rua, observa o portão azul. Não tira os olhos de um menino de mochila de dinossauro que entra de mãos dadas com uma professora."], ["*", "Rogério olha pelo retrovisor. Um carro prata parado atrás dele, motor ligado, vidro escuro. Ele aperta o volante."], ["*", "O carro prata fica ali um minuto. Dois. Rogério desce do carro, caminha até ele e bate no vidro com força."], ["ROGÉRIO", "Abre! Abre esse vidro!"], ["*", "O vidro desce devagar. Uma mãe assustada, com uma criança pequena de pijama no banco de trás, segurando um copo de café."], ["MÃE", "Moço, eu estou esperando dar a hora da creche da minha filha."], ["*", "Rogério recua, envergonhado."], ["ROGÉRIO", "Desculpa. Desculpa, senhora. Eu achei que..."], ["*", "A mãe fecha o vidro e vai embora. Rogério fica sozinho na calçada, as mãos tremendo."], ["ROGÉRIO", "(para si) Você está ficando louco, Rogério."]]}, {"s": "INT. BAR DO ZECA — TARDE", "l": [["*", "Boteco de esquina, televisão ligada no futebol. FÁBIO, 48, camisa amassada, copo de cerveja na mão. Helena e Caíque se sentam à mesa dele."], ["FÁBIO", "Ele foi chorar na polícia, foi? Doze anos eu levantei aquela academia com ele. Doze anos. E ele me botou na rua com uma mão na frente e outra atrás."], ["HELENA", "O senhor mandou estas mensagens?"], ["*", "Caíque mostra a conversa do número salvo como Fábio."], ["FÁBIO", "Mandei. Mandei e mando de novo. Vou processar. Meu advogado já está preparando."], ["HELENA", "E esta?"], ["*", "Caíque mostra a mensagem das 3h12. Fábio lê. O rosto muda. Ele larga o copo."], ["FÁBIO", "Não. Não, não, não. Isso não fui eu."], ["CAÍQUE", "Todo mundo diz isso."], ["FÁBIO", "Eu sou padrinho do Theo! Eu levei esse menino pra tomar vacina quando o Rogério estava viajando. Eu posso odiar o pai dele, mas eu nunca ia falar de criança."], ["*", "Os olhos de Fábio se enchem de água. Helena observa por um longo segundo."], ["HELENA", "Onde o senhor estava às três da manhã de terça?"], ["FÁBIO", "Dormindo no sofá da minha irmã. Ela me acordou às seis pra eu sair antes do marido dela levantar."]]}, {"s": "INT. CASA DE CIDA — COZINHA — DIA", "l": [["*", "Cozinha pequena de periferia, panela de pressão chiando. CIDA, 52, irmã de Fábio, avental e chinelo, cruza os braços diante de Helena e Caíque."], ["CIDA", "Dormiu aqui, sim. Naquele sofá ali. Roncando que nem um trator. Eu acordei às duas pra tomar água e ele estava lá. Às quatro, o meu cachorro latiu e ele estava lá. Às seis eu chutei ele pra fora."], ["CAÍQUE", "E o celular dele?"], ["CIDA", "Carregando na tomada da cozinha. Ali. Do lado da minha panela. Eu tropecei no fio."], ["*", "Helena olha a tomada ao lado do fogão."], ["CIDA", "Doutora, o meu irmão é um idiota. Bebe demais, fala demais, briga com todo mundo. Mas ele chorou quando o Theo nasceu. Chorou mais que o pai."], ["HELENA", "A senhora ouviu falar de outra pessoa que tivesse raiva do Rogério?"], ["CIDA", "Raiva? Não. Mas o Fábio sempre disse que o sócio novo era sorriso demais. Aquele moço da roupa de marca. Disse que quem sorri o tempo todo está vendendo alguma coisa."], ["*", "Helena e Caíque se olham."]]}, {"s": "INT. ACADEMIA FORÇA TOTAL — RECEPÇÃO — FIM DE TARDE", "l": [["*", "Academia moderna, música alta, espelhos. Rogério conversa com BRUNO KALIL, 35, roupa fitness de marca, sorriso branco demais."], ["BRUNO", "Mano, eu sinto muito. Que coisa horrível. E o Theo, como está?"], ["ROGÉRIO", "Não sabe de nada. Mas eu não durmo mais."], ["BRUNO", "Sabe o que eu acho? Você devia tirar um tempo. Levar o Theo pra praia, pra casa da sua mãe no interior. Esse Fábio está descontrolado."], ["ROGÉRIO", "E a academia?"], ["BRUNO", "Eu seguro. Na verdade... eu já te disse. Se você quiser sair, eu compro a sua parte. Te pago hoje. Você recomeça longe disso tudo."], ["*", "Rogério olha para Bruno, cansado, quase convencido."], ["ROGÉRIO", "Quanto?"], ["BRUNO", "A gente conversa. Pensa no teu filho primeiro."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — FIM DE TARDE", "l": [["*", "Quadro de cortiça dividido em dois: à esquerda, o caso Jairo; à direita, um novo quadro com as fotos de Rogério, Fábio e Bruno. Caíque prende um post-it embaixo de cada um."], ["CAÍQUE", "Fábio: motivo, raiva da sociedade desfeita. Mas tem álibi e chorou de verdade. Ou é um ótimo ator."], ["HELENA", "Ele não é um ótimo ator. Ele derrubou a cerveja."], ["CAÍQUE", "A ex-mulher do Rogério, a Renata: brigam pela guarda. Mas ela mora em outra cidade e estava num plantão de hospital às três da manhã. Confirmado."], ["HELENA", "E o Bruno?"], ["CAÍQUE", "O sócio novo. Entrou na academia há oito meses. Comprou a parte do Fábio barato quando a sociedade acabou. Agora oferece comprar a parte do Rogério."], ["HELENA", "Barato também?"], ["CAÍQUE", "Barato também. Um homem que só compra na baixa."], ["HELENA", "E o que faz um preço baixar, Caíque?"], ["CAÍQUE", "Medo."], ["*", "Helena fica olhando a foto de Bruno, sorrindo com dentes muito brancos."], ["HELENA", "Pede o registro de acesso da porta da academia. E o nome da rede de internet de lá."], ["CAÍQUE", "Por quê?"], ["HELENA", "Porque ninguém manda mensagem anônima de casa. A não ser quem acha que é mais esperto que todo mundo."]]}, {"s": "INT. APARTAMENTO DE HELENA — COZINHA — NOITE", "l": [["*", "Apartamento simples, cheio de livros. PEDRO, 19, moletom da universidade, mexe uma panela de macarrão. Helena chega, larga a bolsa."], ["PEDRO", "Chegou na hora. Macarrão de engenheiro: medido no grama."], ["HELENA", "Cheiro de alho queimado."], ["PEDRO", "Medido no grama, não no fogo."], ["*", "Ela ri, beija a cabeça dele. O celular de Helena vibra. Número desconhecido."], ["*", "Na tela: \"Feche o caso Mendes, delegada. Seu filho sai da faculdade às 22h. Bloco C. Sozinho.\""], ["*", "Helena fica parada. O sorriso some. Pedro percebe."], ["PEDRO", "Mãe? Que foi?"], ["*", "Helena demora a responder. Pensa em guardar o celular. Desiste. Mostra a tela para ele."], ["PEDRO", "Isso é sobre aquele senhor envenenado?"], ["HELENA", "É."], ["PEDRO", "Você vai fechar o caso?"], ["HELENA", "Não."], ["*", "Pedro desliga o fogo. Senta à mesa."], ["PEDRO", "Então a gente faz o quê?"], ["HELENA", "A partir de amanhã, você volta de carona com o Caíque. E não anda sozinho até eu descobrir quem mandou isso."], ["PEDRO", "Mãe. Você sempre me ensinou: fato primeiro."], ["HELENA", "Artigo depois."], ["PEDRO", "Então vai descobrir o fato. Eu volto de carona."], ["*", "Ela segura a mão dele em cima da mesa. Não diz mais nada."]]}, {"s": "INT. CARRO DE CAÍQUE — NOITE", "l": [["*", "Dez da noite. Caíque dirige. Pedro, de mochila e fones, no banco do passageiro. Rádio baixinho."], ["PEDRO", "Você não precisava vir. Eu podia pegar um aplicativo."], ["CAÍQUE", "Ordem da delegada. E ela me ameaçou de coisa pior do que a mensagem que recebeu."], ["PEDRO", "Isso é a cara dela."], ["*", "Silêncio confortável. Pedro olha para Caíque de lado."], ["PEDRO", "A minha mãe disse que você gosta da perita."], ["*", "Caíque quase passa o sinal vermelho. Freia em cima."], ["CAÍQUE", "Ela disse isso?"], ["PEDRO", "Disse que você leva café sem açúcar para a perita todo dia e que ela finge que não percebe."], ["CAÍQUE", "Eu levo café para todo mundo."], ["PEDRO", "Você leva café pra mim?"], ["CAÍQUE", "...Não."], ["PEDRO", "Pois é."], ["*", "Caíque olha pelo retrovisor. Um carro escuro vem atrás deles desde a faculdade. Ele vira à direita sem sinalizar. O carro escuro vira também."], ["PEDRO", "Que foi?"], ["CAÍQUE", "Nada. Segura aí."], ["*", "Caíque entra num posto de gasolina e para. O carro escuro passa direto, devagar. Dentro, um casal de idosos discutindo, a senhora gesticulando com um mapa de papel."], ["*", "Caíque solta o ar."], ["PEDRO", "Estava achando que era o assassino?"], ["CAÍQUE", "Estava achando que era a minha mãe. Ela dirige daquele jeito."], ["*", "Os dois riem. Mas Caíque continua olhando pelo retrovisor até chegar ao prédio."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — MANHÃ", "l": [["*", "Iara está de pé diante da mesa de Helena, lendo a mensagem no celular."], ["HELENA", "Quero registrar uma ameaça. Eu represento contra quem for."], ["IARA", "Não precisa representar, delegada."], ["HELENA", "Ameaça exige representação."], ["IARA", "Ameaça comum, sim. Mas leia de novo: \"Feche o caso Mendes.\" Quem ameaça uma autoridade para interferir numa investigação não está cometendo só uma ameaça. Está cometendo coação no curso do processo. Artigo 344."], ["*", "Iara abre o Código no celular e lê."], ["IARA", "\"Usar de violência ou grave ameaça, com o fim de favorecer interesse próprio ou alheio, contra autoridade, parte, ou qualquer outra pessoa que funciona ou é chamada a intervir em processo judicial, policial ou administrativo.\" Reclusão de um a quatro anos. Ação pública incondicionada. O Ministério Público age sozinho."], ["HELENA", "As mesmas palavras."], ["IARA", "Com outra finalidade. E a finalidade muda o crime."], ["*", "Iara devolve o celular."], ["IARA", "Quem mandou isso tem medo do que você vai encontrar."], ["HELENA", "Então eu estou no caminho certo."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE INVESTIGAÇÃO — DIA", "l": [["*", "Caíque cercado de dois monitores e café frio. Helena entra."], ["CAÍQUE", "Duas notícias. Uma boa, uma esquisita. Qual primeiro?"], ["HELENA", "A esquisita."], ["CAÍQUE", "A mensagem pra senhora veio de um chip pré-pago ativado três semanas antes da morte do Seu Jairo. Cadastrado no CPF de um homem que morreu em 2019. Beco sem saída. Por enquanto."], ["HELENA", "Três semanas antes da morte."], ["CAÍQUE", "É. Quem mandou já estava se preparando."], ["HELENA", "E a boa?"], ["CAÍQUE", "A mensagem pro Rogério também foi de um aplicativo com número virtual. Só que quem mandou cometeu um erro. Às três e doze da manhã, o aparelho estava conectado a uma rede de internet sem fio. Nome da rede: \"ForcaTotal_Alunos\"."], ["HELENA", "A academia."], ["CAÍQUE", "Que fecha à meia-noite e abre às seis. E tem porta com biometria."], ["*", "Caíque abre o relatório de acessos da porta."], ["CAÍQUE", "Entrada às três e cinco da manhã. Digital cadastrada em nome de Bruno Kalil."], ["HELENA", "O sócio novo."], ["CAÍQUE", "Que, por coincidência, quer comprar a parte do Rogério baratinho."], ["HELENA", "Ele não queria só o medo do Rogério. Queria o medo do Rogério e a culpa do Fábio."]]}, {"s": "INT. APARTAMENTO DE ROGÉRIO — SALA — NOITE", "l": [["*", "Rogério arruma uma mala às pressas. RENATA, 42, ex-mulher dele, de jaleco de enfermeira por baixo do casaco, está de pé na porta, de braços cruzados."], ["RENATA", "Você ia levar o Theo para o interior sem me avisar?"], ["ROGÉRIO", "Eu ia te avisar quando chegasse lá."], ["RENATA", "Rogério, a guarda é compartilhada. Você não pode tirar o meu filho da cidade sem falar comigo."], ["ROGÉRIO", "Alguém ameaçou o nosso filho, Renata!"], ["RENATA", "E você ia fugir em vez de deixar a polícia trabalhar?"], ["*", "Rogério larga a mala. Senta no braço do sofá."], ["ROGÉRIO", "O Bruno disse que era melhor. Que ele cuidava da academia. Que me pagava a minha parte e eu recomeçava longe."], ["RENATA", "O Bruno disse."], ["ROGÉRIO", "É."], ["RENATA", "E desde quando você faz o que o Bruno diz?"], ["*", "Rogério não responde. O celular dele vibra. Mensagem de Helena: \"Não assine nada amanhã. Estou indo à academia às 10h.\""], ["*", "Ele mostra a tela para Renata. Os dois se olham, entendendo ao mesmo tempo."]]}, {"s": "INT. ACADEMIA FORÇA TOTAL — ESCRITÓRIO — DIA", "l": [["*", "Bruno assina papéis. Rogério está do outro lado da mesa com um contrato de venda na mão. A porta se abre. Helena, Caíque e Fábio, que fica no batente, sem coragem de entrar."], ["HELENA", "Seu Rogério, antes de assinar qualquer coisa, eu queria que o senhor visse um relatório de acesso."], ["*", "Caíque coloca o tablet na mesa. Rogério lê. Olha para Bruno."], ["BRUNO", "Isso é um erro. Eu vim buscar um documento."], ["CAÍQUE", "Às três e cinco da manhã. E às três e doze o seu celular mandou uma mensagem pelo wi-fi daqui."], ["*", "Rogério se levanta devagar."], ["ROGÉRIO", "Você usou o meu filho."], ["BRUNO", "Rogério, calma, eu..."], ["ROGÉRIO", "Você usou o meu filho pra me tirar da minha academia."], ["*", "Rogério avança. Caíque se coloca entre os dois."], ["HELENA", "Seu Rogério. Se o senhor encostar nele, o próximo episódio é sobre o senhor."], ["*", "Rogério para. Respira. Abaixa as mãos. Do batente, Fábio dá um passo para dentro."], ["FÁBIO", "Theo está bem?"], ["ROGÉRIO", "Está."], ["*", "Os dois se olham. Muita coisa não dita."]]}, {"s": "INT. JUIZADO ESPECIAL CRIMINAL — SALA DE AUDIÊNCIA — DIA", "l": [["*", "Sala menor que a do fórum. Marta preside. Iara, Bruno e o advogado dele, Rogério no lugar da vítima. Fábio sentado no fundo."], ["MARTA", "Doutora Iara."], ["IARA", "Excelência, o crime de ameaça tem pena máxima de seis meses. É infração de menor potencial ofensivo. O autor não tem antecedentes. Por isso, a lei permite que o Ministério Público proponha uma transação penal: uma pena alternativa, aplicada agora, sem processo."], ["ROGÉRIO", "Só isso? Ele ameaçou o meu filho!"], ["IARA", "Seu Rogério, o Juizado foi criado para crimes menores serem resolvidos rápido. A transação não é absolvição. O senhor Bruno vai pagar vinte salários mínimos a uma instituição de amparo à infância e prestar serviços por seis meses. E fica cinco anos sem poder receber esse benefício de novo."], ["MARTA", "Senhor Bruno, aceita a proposta?"], ["*", "Bruno olha para o advogado. Assente."], ["BRUNO", "Aceito."], ["MARTA", "Homologo a transação."], ["*", "Marta tira os óculos e olha para Rogério."], ["MARTA", "Senhor Rogério, a pena é pequena porque a lei mede o ato, não o medo. Mas o ato foi reconhecido. E está registrado."], ["*", "Rogério concorda, devagar. Na saída, para ao lado de Fábio."], ["ROGÉRIO", "Você ainda vai me processar?"], ["FÁBIO", "Vou. É um direito meu."], ["ROGÉRIO", "É mesmo."], ["*", "Quase um sorriso entre os dois."], ["FÁBIO", "Mas sábado tem aniversário do Theo."], ["ROGÉRIO", "Sete anos."], ["FÁBIO", "Eu sei. Eu sou o padrinho."]]}, {"s": "INT. CAFÉ DO FÓRUM — FIM DE TARDE", "l": [["*", "Iara no balcão, mexendo um café sem açúcar que não precisa ser mexido. Otávio chega, mochila no ombro."], ["OTÁVIO", "Soube da delegada. A mensagem sobre o filho dela."], ["IARA", "Coação no curso do processo. Eu mesma vou acompanhar."], ["OTÁVIO", "Alguém está com medo do que ela vai achar."], ["IARA", "Ou alguém quer que pareça que o Vinícius tem um cúmplice do lado de fora."], ["OTÁVIO", "Você sempre acha o ângulo que piora para o meu cliente."], ["IARA", "E você sempre acha o que melhora. É para isso que existem dois lados, Otávio."], ["*", "Pausa. Otávio pede um café. Olha para ela."], ["OTÁVIO", "Você ficou com medo? Quando soube da ameaça?"], ["IARA", "Por ela? Fiquei."], ["OTÁVIO", "E por você? Você acusa o mesmo homem."], ["*", "Iara para de mexer o café."], ["IARA", "Eu fiquei com medo, sim. Dormi de luz acesa. Satisfeito?"], ["OTÁVIO", "Não. Preocupado."], ["*", "Ela olha para ele de verdade, pela primeira vez no episódio."], ["IARA", "Não faz isso."], ["OTÁVIO", "Isso o quê?"], ["IARA", "Se preocupar comigo como se ainda tivesse o direito."], ["*", "Ela deixa o dinheiro no balcão e sai. Otávio fica olhando a xícara dela, ainda cheia."]]}, {"s": "INT. CADEIA PÚBLICA — PARLATÓRIO — DIA", "l": [["*", "Otávio e Vinícius, separados pelo vidro."], ["OTÁVIO", "Alguém ameaçou a delegada para ela parar de investigar."], ["VINÍCIUS", "Então alguém tem medo. Isso é bom pra mim?"], ["OTÁVIO", "É bom pra verdade. Pensa comigo. Você disse que seu tio andava diferente. Saía às quintas."], ["VINÍCIUS", "Saía de terno. Voltava tarde, cantando. Uma vez eu achei um papel no bolso do paletó dele. Uma conta de restaurante. Jantar pra dois."], ["OTÁVIO", "Que restaurante?"], ["VINÍCIUS", "Um na praça, perto do fórum. Sabor da alguma coisa."], ["*", "Otávio para de anotar."], ["OTÁVIO", "Sabor da Praça."]]}, {"s": "INT. RESTAURANTE SABOR DA PRAÇA — NOITE", "l": [["*", "Salão tranquilo depois do jantar. SEU ALCIDES, 68, bigode branco, avental azul, empilha cadeiras. Otávio entra."], ["ALCIDES", "Doutor Otávio! A cozinha fechou, mas pro senhor eu esquento um caldo."], ["OTÁVIO", "Hoje não, Seu Alcides. Uma pergunta só. O senhor conhecia um cliente chamado Jairo Mendes?"], ["*", "Alcides para de empilhar cadeiras. Tira o avental devagar."], ["ALCIDES", "Seu Jairo... Fiquei sabendo. Que tristeza. Vinha toda quinta-feira, doutor. Mesa dez, no canto. Pedia bacalhau e um vinho do Porto."], ["OTÁVIO", "Sozinho?"], ["ALCIDES", "Nunca. Com uma senhora muito elegante. Ruiva. Depois do jantar, os dois iam dançar no clube aqui ao lado. Eu mesmo vi, que eu também danço lá."], ["*", "Otávio pega o celular e liga."], ["OTÁVIO", "Delegada? A mulher do enterro tinha cabelo ruivo?"], ["*", "Silêncio do outro lado."], ["HELENA", "(telefone) Tinha."]]}, {"s": "TELA PRETA", "l": [["VOZ", "Uma palavra pode ser um direito ou um crime. Depende do mal prometido e de para quem ele é prometido. No próximo episódio: três carros, uma ciclista caída e ninguém parou. Artigo 135."]]}, {"s": "O VEREDITO — CARDS NARRADOS", "l": [["*", "Tela preta. Os cards do Veredito surgem um a um."], ["VOZ", "Artigo 147 do Código Penal: ameaçar alguém, por palavra, escrito, gesto ou qualquer outro meio simbólico, de causar-lhe mal injusto e grave. A pena é de detenção de um a seis meses, ou multa."], ["VOZ", "O mal precisa ser injusto. Prometer um processo, uma denúncia à polícia ou uma cobrança na Justiça é exercer um direito e não é crime. E o crime existe mesmo que o mal prometido nunca aconteça: basta a ameaça ser capaz de intimidar."], ["VOZ", "Em regra, a ameaça depende de representação da vítima, que tem seis meses para isso. Quando é cometida contra a mulher por razões da condição do sexo feminino, a pena é aplicada em dobro e o Ministério Público age sem precisar da representação."], ["VOZ", "Por ser crime de menor potencial ofensivo, a ameaça vai ao Juizado Especial, onde cabe a transação penal: uma pena alternativa aplicada sem processo, que só pode ser concedida uma vez a cada cinco anos."], ["VOZ", "Não confunda: a ameaça feita contra uma autoridade, uma parte ou uma testemunha para interferir numa investigação ou num processo é coação no curso do processo, artigo 344, com pena de um a quatro anos de reclusão."]]}]}, "135": {"dur": 21, "logline": "Numa noite de chuva, a violinista Carla cai da bicicleta e fica dez minutos no asfalto. Três carros passam. Um causou a queda e fugiu. Outro viu e seguiu para uma reunião. O terceiro não parou, mas telefonou. Três motoristas, três situações diferentes perante a lei.", "twist": "O artigo 135 não obriga ninguém a ser herói. Quem não pode ajudar sem correr risco cumpre o dever pedindo socorro à autoridade, como ligar para o 192. Só comete omissão de socorro quem podia ajudar ou ligar e não fez nada. E quem causou o acidente responde por outro crime, do Código de Trânsito, com pena aumentada por não socorrer e ainda pela fuga.", "guests": [{"n": "Carla Nogueira", "r": "Vítima, violinista, 27 anos", "d": "Determinada, sensível, sonha com a orquestra sinfônica"}, {"n": "Paulo Bessa", "r": "Motorista que não parou, 52 anos", "d": "Ansioso, carreirista, mas não é mau; carrega culpa"}, {"n": "Diego Farias", "r": "Motorista de aplicativo que causou a queda, 33 anos", "d": "Defensivo, mente por medo de perder o sustento"}, {"n": "Ana Cristina", "r": "Motorista que pediu socorro, 41 anos", "d": "Prática e protetora"}, {"n": "Seu Raimundo", "r": "Porteiro que socorreu, 63 anos", "d": "Generoso, conversador, ouve forró no rádio"}, {"n": "Dra. Cíntia Prado", "r": "Advogada de Paulo, 45 anos", "d": "Objetiva, técnica"}, {"n": "Seu Alcides", "r": "Dono do Sabor da Praça", "d": "Dono do Sabor da Praça. Conhece todo mundo pelo nome e dança bolero às quintas."}, {"n": "Maestro Evaristo", "r": "Professor de violino de Carla, 70 anos", "d": "Afetuoso e exigente"}, {"n": "Júlia Farias", "r": "Esposa de Diego, 30 anos", "d": "Direta, decepcionada"}, {"n": "Regina Bessa", "r": "Esposa de Paulo, 50 anos", "d": "Calma, moralmente firme"}], "scenes": [{"s": "ANTERIORMENTE", "l": [["*", "Imagens rápidas dos episódios anteriores."], ["VOZ", "Anteriormente, na JURISPLAY. Alguém ameaçou a delegada Helena e o filho dela para que ela parasse de investigar a morte de Seu Jairo. A mensagem veio de um chip pré-pago, comprado três semanas antes do crime. E o dono do restaurante Sabor da Praça contou que Seu Jairo jantava toda quinta com uma senhora ruiva. A mesma cor de cabelo da mulher do enterro."], ["*", "Corte para a cena de abertura."]]}, {"s": "EXT. AVENIDA BEIRA-RIO — NOITE", "l": [["*", "Chuva fina e constante. Avenida larga, mal iluminada, poucos carros. CARLA, 27, capa de chuva amarela, estojo de violino nas costas, pedala na faixa da direita."], ["*", "Um hatch branco com adesivo de aplicativo passa colado nela. O retrovisor do carro bate no guidão. A bicicleta perde o rumo, cai num buraco cheio d'água. Carla é arremessada no asfalto."], ["*", "No hatch, DIEGO, 33, olha pelo retrovisor. Freia um segundo. Acelera e some."], ["*", "Carla tenta se levantar. Grita de dor, segura o braço esquerdo."], ["*", "Um sedã prata se aproxima. PAULO BESSA, 52, camisa social, vê a ciclista caída. Diminui. Olha o relógio do painel: 19:48. Olha o celular: \"Reunião com a diretoria — 20h\". Desvia da bicicleta e segue."], ["*", "Um terceiro carro passa. ANA CRISTINA, 41, com duas crianças dormindo no banco de trás, vê a cena, olha a rua escura e deserta. Não para. Toca na tela do painel."], ["ANA", "Ligar para 192."], ["*", "Do outro lado da avenida, a porta de vidro de um prédio se abre. SEU RAIMUNDO, 63, uniforme azul de porteiro, atravessa correndo com um guarda-chuva preto e um rádio de pilha tocando forró no bolso."], ["RAIMUNDO", "Ô, minha filha! Fica quietinha, não mexe esse braço! Já vem ajuda!"], ["*", "Ele se ajoelha na chuva e cobre Carla com o guarda-chuva."], ["*", "Corte seco para preto."]]}, {"s": "VINHETA", "l": [["*", "O triângulo laranja da JURISPLAY. ART. 135. \"Ninguém Parou\"."]]}, {"s": "INT. EDIFÍCIO EMPRESARIAL — SALA DE REUNIÕES — NOITE (MESMA NOITE)", "l": [["*", "Oito e cinco da noite. Sala de vidro, mesa comprida, diretores de terno. Paulo Bessa entra apressado, a camisa com respingos de chuva, e se senta."], ["DIRETOR", "Paulo! Achamos que você não vinha."], ["PAULO", "Trânsito. Chuva. Desculpem."], ["DIRETOR", "Pois sente-se, porque a notícia é boa. A partir de segunda, você é o novo gerente regional."], ["*", "Aplausos. Alguém abre uma garrafa de espumante. Paulo sorri, aperta mãos. O celular vibra no bolso. Uma notificação de um portal de notícias local: \"Ciclista fica ferida na Avenida Beira-Rio; testemunhas dizem que motoristas não pararam\"."], ["*", "Paulo lê. O sorriso some por um segundo. Ele vira a tela do celular para baixo sobre a mesa."], ["DIRETOR", "Um brinde ao Paulo!"], ["*", "Paulo ergue a taça. Bebe. Os olhos fixos no celular virado."]]}, {"s": "INT. HOSPITAL MUNICIPAL — QUARTO — DIA", "l": [["*", "Carla na cama, braço esquerdo engessado do cotovelo à mão. No canto, o estojo do violino, intacto. Ela olha para ele como quem olha para alguém que morreu."], ["*", "Helena entra com Caíque."], ["HELENA", "Carla Nogueira? Delegada Helena Rocha."], ["CARLA", "A senhora veio dizer quem me derrubou?"], ["HELENA", "Vim ouvir a senhora primeiro."], ["CARLA", "Eu toco violino, delegada. Daqui a três semanas eu ia fazer a audição para a Orquestra Sinfônica. Seis anos me preparando. A mão esquerda é a que faz as notas."], ["*", "Ela levanta o gesso um pouco. A voz falha."], ["CARLA", "Eu fiquei dez minutos no chão. Eu contei os carros. Três. Um me derrubou. Os outros dois passaram por mim. Eu vi os faróis. Eu vi o rosto de um deles olhando pra mim."], ["HELENA", "E quem parou?"], ["CARLA", "Um porteiro. Um senhor de rádio no bolso."], ["HELENA", "Então começamos por ele."]]}, {"s": "INT. APARTAMENTO DE CARLA — FLASHBACK — TARDE (DIA DO ACIDENTE)", "l": [["*", "Letreiro: \"Naquela tarde\". Apartamento minúsculo com partituras coladas na parede. Carla toca violino diante de uma estante de partitura. A mão esquerda corre pelas cordas com agilidade. A música é difícil e linda."], ["*", "Batidas no teto. Uma voz abafada do apartamento de cima: \"Já chega, menina!\""], ["*", "Carla para, ri sozinha, e bate de volta no teto com o arco do violino, de leve."], ["CARLA", "(para o teto) Três semanas, Dona Iolanda! Só mais três semanas!"], ["*", "O celular dela vibra. Mensagem do professor: \"Ensaio com o pianista às 19h30 na escola de música. Não se atrase.\" Ela guarda o violino no estojo com cuidado de quem guarda um bebê. Veste a capa de chuva amarela. Olha pela janela: começa a chover."], ["CARLA", "Você vai de bicicleta mesmo, Carla. Taxi é para quem passa na audição."], ["*", "Ela sai batendo a porta."]]}, {"s": "INT. PRÉDIO RESIDENCIAL — PORTARIA — DIA", "l": [["*", "Portaria pequena, com monitor de câmeras. Seu Raimundo oferece café num copinho a Helena e Caíque."], ["RAIMUNDO", "Eu vi o carro branco encostar nela. Depois veio um prata, diminuiu, e foi embora. Depois um outro, escuro. Também não parou."], ["CAÍQUE", "E o senhor atravessou."], ["RAIMUNDO", "Ora, e eu ia ficar olhando? Liguei pro SAMU com uma mão e segurei o guarda-chuva com a outra."], ["HELENA", "O senhor tem as imagens da câmera da fachada?"], ["RAIMUNDO", "Tenho. Só que é câmera de prédio, doutora. Chovendo, à noite... é tudo borrão."], ["CAÍQUE", "(sorrindo) Borrão é o que eu mais gosto."]]}, {"s": "INT. PRÉDIO RESIDENCIAL — PORTARIA — NOITE", "l": [["*", "Seu Raimundo e Caíque assistem às imagens no pequeno monitor da portaria. O rádio de pilha toca forró baixinho."], ["CAÍQUE", "O senhor atravessou a avenida em quanto tempo? Nas imagens dá uns quinze segundos."], ["RAIMUNDO", "Nem pensei. Quando vi, já estava lá."], ["CAÍQUE", "Muita gente teria ficado olhando da portaria."], ["*", "Raimundo desliga o rádio. Fica sério."], ["RAIMUNDO", "Em 1994, o meu irmão caiu de bicicleta numa estrada lá em Caruaru. Voltando da roça. Ficou na beira do asfalto a noite inteira. Passaram uns trinta carros, disseram depois. Ninguém parou. Quando acharam ele, de manhã, já tinha ido."], ["*", "Caíque não sabe o que dizer."], ["RAIMUNDO", "Os médicos falaram que, se alguém tivesse levado ele para o hospital, ele vivia. Uma ligação. Um carro que parasse."], ["CAÍQUE", "Eu sinto muito, Seu Raimundo."], ["RAIMUNDO", "Desde então, meu filho, eu paro. Até para cachorro atropelado eu paro."], ["*", "Ele liga o rádio de novo."]]}, {"s": "INT. INSTITUTO DE CRIMINALÍSTICA — LABORATÓRIO — NOITE", "l": [["*", "Laboratório vazio, só a luz dos monitores. Lúcia e Caíque lado a lado diante das imagens. Uma caixa de pizza aberta entre os dois."], ["LÚCIA", "Você sabe que pizza não é procedimento oficial."], ["CAÍQUE", "É procedimento de hora extra."], ["*", "Lúcia amplia um quadro, ajusta o contraste. A placa do sedã prata fica legível."], ["LÚCIA", "Sedã prata. Placa completa. O terceiro, o escuro, também dá para ler. O hatch branco é o problema. O farol estoura a imagem. Só tenho três letras."], ["CAÍQUE", "E o adesivo de aplicativo no vidro de trás."], ["LÚCIA", "Isso não é suficiente."], ["CAÍQUE", "Para a empresa do aplicativo, é. Três letras, cor, modelo, horário, rota. Eles sabem quem estava ali."], ["*", "Lúcia olha para ele de um jeito novo."], ["LÚCIA", "Isso foi quase inteligente, Caíque."], ["CAÍQUE", "Quase?"], ["LÚCIA", "Você está com molho de tomate no queixo."], ["*", "Ela pega um guardanapo e limpa o queixo dele. Fica um segundo perto demais. Os dois se afastam ao mesmo tempo."]]}, {"s": "INT. HOSPITAL MUNICIPAL — QUARTO — NOITE", "l": [["*", "Carla sozinha no quarto escuro. A porta se abre. MAESTRO EVARISTO, 70, cabelo branco comprido preso num rabo, cachecol vermelho, entra com uma partitura enrolada debaixo do braço."], ["EVARISTO", "Disseram que a minha melhor aluna resolveu ir para a audição de gesso."], ["CARLA", "Maestro."], ["*", "Ele se senta na beira da cama. Olha o braço engessado."], ["EVARISTO", "Falei com a direção da orquestra. Não dá para adiar a audição. São trinta candidatos de todo o país."], ["CARLA", "Eu sei."], ["EVARISTO", "Mas abrem outra no ano que vem."], ["CARLA", "Um ano, maestro. Eu tenho vinte e sete. Eu ensaio seis horas por dia desde os vinte e um."], ["EVARISTO", "E vai ensaiar mais um ano. Com o braço remendado, que vai ter mais história que o braço de antes."], ["*", "Ele desenrola a partitura e coloca no colo dela."], ["EVARISTO", "A peça da audição do ano que vem. Comece a ler. Com os olhos, por enquanto."], ["*", "Carla olha para a partitura. Os dedos da mão direita começam, sem querer, a marcar o ritmo no lençol."], ["CARLA", "O senhor sabia que eu ia dizer sim."], ["EVARISTO", "Eu sabia que você ia chorar primeiro. Pode chorar. Eu espero."], ["*", "Carla ri e chora ao mesmo tempo."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — DIA", "l": [["*", "Carla, com o braço numa tipoia, sentada em frente a Helena. Caíque prende três fotos no quadro: um hatch branco, um sedã prata, um carro escuro."], ["CARLA", "Os três. Eu quero os três processados."], ["HELENA", "Fato primeiro, Carla. A lei olha para cada motorista de um jeito."], ["*", "Helena aponta a foto do carro escuro."], ["HELENA", "Esta é a Ana Cristina. Estava sozinha com dois filhos pequenos, à noite, numa avenida deserta, na chuva. Não parou. Mas ligou para o 192 no mesmo minuto. Foi a ligação dela que mandou a ambulância."], ["CARLA", "Ela me deixou lá."], ["HELENA", "Ela pediu socorro à autoridade. O artigo 135 diz que comete crime quem deixa de prestar assistência, quando possível fazê-lo sem risco pessoal, ou quem não pede, nesses casos, o socorro da autoridade pública. Ela pediu. Cumpriu o dever. Não cometeu crime."], ["*", "Carla abaixa os olhos. Helena aponta o sedã prata."], ["HELENA", "Este é o Paulo Bessa. Não causou a sua queda. Viu a senhora, diminuiu e seguiu. Não desceu, não ligou para ninguém. Se ele podia ter ligado sem risco nenhum, e podia, isso é omissão de socorro. Detenção de um a seis meses, ou multa."], ["CARLA", "Só isso?"], ["HELENA", "Se a omissão tivesse causado uma lesão grave, a pena aumentaria de metade. Se tivesse causado a sua morte, triplicaria. O médico disse que os dez minutos no chão não pioraram a fratura. Então é a pena simples."], ["*", "Helena aponta a última foto, o hatch branco."], ["HELENA", "E este é o mais grave. Ele causou a sua queda e fugiu. Para ele não é o 135. É o Código de Trânsito: lesão corporal culposa na direção de veículo, com pena aumentada por não prestar socorro à vítima, e mais o crime de fugir do local do acidente."], ["CARLA", "Então quem me derrubou e quem me viu caída respondem por crimes diferentes."], ["HELENA", "Exatamente. A lei pune o que cada um fez. E o que cada um deixou de fazer."]]}, {"s": "INT. 3ª DELEGACIA — RECEPÇÃO — DIA", "l": [["*", "Ana Cristina, de roupa de academia, chega ao balcão com os dois filhos pequenos pela mão. Parece nervosa. Helena se aproxima."], ["ANA", "Eu soube pelo jornal que vocês estão procurando os motoristas que passaram pela ciclista. Eu vim me apresentar. Eu passei por ela."], ["HELENA", "Ana Cristina? A senhora ligou para o 192."], ["ANA", "Liguei. Mas não parei. Eu tinha as crianças no carro, estava escuro, aquela avenida é perigosa. Eu fiquei com medo de ser uma armadilha. Já assaltaram uma amiga minha assim."], ["HELENA", "A senhora fez exatamente o que a lei pede."], ["ANA", "Eu não consigo dormir, delegada. Eu fico pensando que eu devia ter descido."], ["HELENA", "Dona Ana, a lei não exige que ninguém se arrisque. A senhora estava sozinha com duas crianças numa avenida deserta. A senhora pediu socorro à autoridade pública, e foi a sua ligação que levou a ambulância até ela."], ["*", "Ana enxuga os olhos. A filha mais nova puxa a manga da mãe."], ["ANA", "E se eu quiser visitar ela?"], ["HELENA", "Acho que ela vai gostar de conhecer quem chamou a ambulância."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE INTERROGATÓRIO — DIA", "l": [["*", "Diego, de boné, braços cruzados. Caíque coloca na mesa a foto do retrovisor direito do hatch branco, com um arranhão azul."], ["DIEGO", "Eu não senti nada. Juro. Pensei que tinha passado num buraco."], ["CAÍQUE", "A empresa do aplicativo confirma que você estava na Avenida Beira-Rio às dezenove e quarenta e sete. E a perita encontrou tinta azul no seu retrovisor."], ["DIEGO", "Muita coisa é azul."], ["*", "A porta se abre. Lúcia entra com um laudo e coloca na mesa sem cerimônia."], ["LÚCIA", "A tinta do seu retrovisor tem a mesma composição da tinta da bicicleta da vítima. Mesma marca, mesmo lote de pintura. E o seu carro freou por um segundo logo depois do impacto. Quem não sente nada não freia."], ["*", "Diego descruza os braços. Tira o boné."], ["DIEGO", "Eu tenho financiamento do carro. Se eu perco a habilitação, eu perco tudo."], ["CAÍQUE", "Ela também tinha uma audição, Diego."], ["*", "Diego enterra o rosto nas mãos."]]}, {"s": "INT. INSTITUTO DE CRIMINALÍSTICA — CORREDOR — DIA", "l": [["*", "Fim do dia. Caíque acompanha Lúcia de volta ao instituto. Os dois caminham pelo corredor de luz branca."], ["CAÍQUE", "Você entrou naquela sala como num filme."], ["LÚCIA", "Eu entrei com um laudo. Laudo é melhor que filme."], ["CAÍQUE", "Você sempre fala do trabalho quando eu tento falar de outra coisa."], ["LÚCIA", "E você sempre tenta falar de outra coisa quando eu estou trabalhando."], ["*", "Eles param diante da porta do laboratório. Lúcia segura a maçaneta. Não abre."], ["LÚCIA", "Caíque. A pizza foi boa."], ["CAÍQUE", "Foi?"], ["LÚCIA", "Foi. Só não conta para ninguém."], ["*", "Ela entra e fecha a porta. Caíque fica no corredor, sorrindo para a porta fechada como um bobo."]]}, {"s": "INT. APARTAMENTO DE DIEGO — COZINHA — NOITE", "l": [["*", "Cozinha pequena. Diego sentado à mesa diante de uma pilha de boletos. A esposa dele, JÚLIA, 30, embala o filho de colo andando de um lado para o outro."], ["JÚLIA", "O aplicativo suspendeu a sua conta?"], ["DIEGO", "Até o fim da investigação."], ["JÚLIA", "E a parcela do carro? São mil e duzentos por mês, Diego."], ["DIEGO", "Eu sei quanto é a parcela!"], ["*", "O bebê começa a chorar. Júlia para de andar."], ["JÚLIA", "Por que você não parou? Me diz só isso. Você sempre para pra ajudar todo mundo."], ["*", "Diego esconde o rosto nas mãos."], ["DIEGO", "Porque eu vi pelo retrovisor que ela se mexia. Pensei: ela está bem, se eu parar vão dizer que a culpa é minha, eu perco a habilitação, eu perco o carro, a gente perde tudo. Em dois segundos eu pensei tudo isso. E acelerei."], ["JÚLIA", "E agora?"], ["DIEGO", "Agora eu vou perder tudo do mesmo jeito. E ainda fugi."]]}, {"s": "INT. CASA DE PAULO — SALA — NOITE", "l": [["*", "Sala de classe média, quadros de família na parede. Paulo sentado no sofá, ainda de camisa social, a gravata frouxa. A esposa, REGINA, 50, se senta ao lado dele com duas xícaras de chá."], ["REGINA", "Você não comemorou a promoção. Não falou nada a semana inteira."], ["PAULO", "A delegada me ligou hoje. Sobre a ciclista da Beira-Rio."], ["REGINA", "Que ciclista?"], ["PAULO", "Eu vi ela caída, Regina. Eu diminuí o carro, olhei para ela, e fui para a reunião."], ["*", "Regina larga a xícara na mesa de centro."], ["REGINA", "Paulo."], ["PAULO", "Eu pensei que alguém ia parar. Eu juro que pensei. Todo mundo pensa que alguém vai parar."], ["REGINA", "E ela?"], ["PAULO", "Quebrou o braço. Ela é violinista. Ia fazer uma audição."], ["*", "Silêncio longo. Regina pega a mão dele."], ["REGINA", "E o que você vai fazer agora?"], ["PAULO", "A advogada diz para eu não falar com ninguém."], ["REGINA", "Eu não perguntei o que a advogada diz."], ["*", "Paulo olha para a esposa. Depois para uma orquídea num vaso, na janela."], ["PAULO", "Eu vou ao hospital."]]}, {"s": "INT. HOSPITAL MUNICIPAL — QUARTO — FIM DE TARDE", "l": [["*", "Carla olha pela janela. Batem na porta. Paulo Bessa entra, sem gravata, com um vaso de orquídea nas mãos. Para longe da cama."], ["PAULO", "Desculpe. A delegada me disse o número do quarto. Eu sei que não devia ter vindo."], ["CARLA", "O senhor é o do carro prata."], ["PAULO", "Sou."], ["*", "Silêncio longo."], ["CARLA", "Você olhou pra mim. Eu vi os seus olhos pelo vidro."], ["PAULO", "Eu tinha uma reunião às oito. Era a minha promoção. Eu pensei: alguém vai parar. Alguém sempre para."], ["CARLA", "E o senhor foi promovido?"], ["*", "Paulo demora a responder."], ["PAULO", "Fui."], ["*", "Carla olha para o violino no canto do quarto."], ["CARLA", "Parabéns."], ["*", "Paulo coloca a orquídea na mesa, perto da porta. Sai sem conseguir dizer mais nada."]]}, {"s": "INT. DEFENSORIA PÚBLICA — SALA DE OTÁVIO — DIA", "l": [["*", "Sala minúscula, processos empilhados até o teto, um vaso com uma planta quase morta. Iara bate na porta aberta com um processo na mão."], ["IARA", "Vim deixar a cópia do laudo do açucareiro. É seu direito ter acesso."], ["OTÁVIO", "Você podia ter mandado pelo sistema."], ["IARA", "O sistema estava lento."], ["*", "Otávio sorri. Ela coloca o processo na mesa. Os olhos dela encontram, numa estante, um porta-retratos: uma foto antiga de formatura, uma turma de Direito. Ela e Otávio lado a lado, rindo, jovens."], ["IARA", "Você ainda tem isso."], ["OTÁVIO", "Eu tenho todas."], ["*", "Iara pega o porta-retratos. Passa o polegar no vidro."], ["IARA", "Essa planta está morrendo, Otávio."], ["OTÁVIO", "Ela sente falta de alguém que lembre de regar."], ["*", "Iara coloca o porta-retratos de volta. Antes de sair, pega o copo d'água da mesa dele e despeja no vaso."]]}, {"s": "INT. HOSPITAL MUNICIPAL — QUARTO — DIA", "l": [["*", "Carla, já com o braço em gesso menor, recebe uma visita: Ana Cristina, com um buquê de girassóis e as duas crianças pela mão."], ["ANA", "Eu sou a motorista do carro escuro. A que não parou."], ["CARLA", "A que ligou para a ambulância."], ["*", "Ana fica sem graça."], ["ANA", "Eu queria pedir desculpas por não ter descido."], ["CARLA", "Eu ouvi a sirene chegando dez minutos depois. Eu pensei que alguém tinha me visto. E tinha."], ["*", "A menina mais nova de Ana se aproxima do estojo de violino no canto do quarto."], ["MENINA", "É um violino?"], ["CARLA", "É. Mas ele está de castigo até o meu braço sarar."], ["MENINA", "Você toca uma música quando sarar?"], ["CARLA", "Toco. Prometo."]]}, {"s": "INT. JUIZADO ESPECIAL CRIMINAL — SALA DE AUDIÊNCIA — DIA", "l": [["*", "Marta preside. Iara. Paulo, de terno, ao lado de DRA. CÍNTIA PRADO, 45. Carla, com a tipoia, no lugar da vítima. Seu Raimundo no fundo, de uniforme, com o rádio desligado."], ["IARA", "Excelência, ofereci ao senhor Paulo uma transação penal. Ele recusou."], ["CÍNTIA", "Meu cliente não aceita pena por um crime que não cometeu. A Avenida Beira-Rio, à noite, é uma das mais perigosas da cidade. Parar ali, no escuro e na chuva, era risco pessoal. E o artigo 135 só pune quem podia agir sem risco."], ["MARTA", "Doutora Iara."], ["IARA", "A defesa tem razão num ponto: o senhor Paulo não era obrigado a descer do carro naquela avenida. Ninguém é obrigado a se arriscar."], ["*", "Iara se vira para Paulo."], ["IARA", "Mas o artigo dá duas saídas: ajudar ou pedir socorro à autoridade. O senhor tinha o celular no painel, aberto na agenda da reunião. Uma ligação de dez segundos para o 192, de dentro do carro, de portas trancadas. Que risco havia nisso?"], ["*", "Paulo olha para as próprias mãos. Dra. Cíntia não responde."], ["IARA", "Uma outra motorista, sozinha com dois filhos, fez exatamente isso. E não está sentada nessa cadeira."], ["*", "Marta tira os óculos."], ["MARTA", "Ninguém é obrigado a ser herói, senhor Paulo. Mas todos são obrigados a, pelo menos, telefonar."], ["MARTA", "Julgo procedente a acusação. Condeno o réu por omissão de socorro, artigo 135 do Código Penal, à pena de multa."], ["*", "Paulo assente devagar. Na saída, para diante de Seu Raimundo."], ["PAULO", "O senhor é quem parou."], ["RAIMUNDO", "Parei, ué. Tinha uma moça no chão."], ["*", "Paulo não tem resposta para isso."]]}, {"s": "INT. RESTAURANTE SABOR DA PRAÇA — NOITE", "l": [["*", "Helena sentada ao balcão. Seu Alcides serve um caldo verde."], ["HELENA", "Seu Alcides, a senhora ruiva que jantava com o Seu Jairo. O senhor sabe o nome dela?"], ["ALCIDES", "Sabe que não, doutora? Ele chamava ela de \"minha flor\". E ela pagava a conta sempre em dinheiro. Mas eu nunca escutei o nome."], ["HELENA", "E o clube onde eles dançavam?"], ["ALCIDES", "Clube Atlético Aurora. Baile toda quinta, a partir das nove. Tem gente lá que dança há quarenta anos."], ["*", "O celular de Helena vibra. Caíque."], ["CAÍQUE", "(telefone) Doutora, lembra do chip que mandou a ameaça pra senhora? Eu achei onde ele foi vendido. Uma banca de jornal na praça do Clube Atlético Aurora. O dono tem câmera."], ["*", "Helena larga a colher."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE INVESTIGAÇÃO — NOITE", "l": [["*", "Caíque roda as imagens da câmera da banca. Data: três semanas antes da morte de Jairo. Uma mulher de óculos escuros compra um chip e uma recarga. Paga em dinheiro. Não mostra o rosto."], ["CAÍQUE", "Cabelo preso num chapéu, óculos escuros. Dá pra ver quase nada."], ["HELENA", "Volta."], ["*", "Caíque volta a imagem. Helena aponta para o pescoço da mulher."], ["HELENA", "Ali. Congela."], ["*", "No pescoço da mulher, um lenço de seda estampado, de padrão inconfundível: flores vermelhas sobre fundo verde."], ["*", "Helena abre no próprio celular uma foto tirada de longe no cemitério: a mulher ruiva colocando a rosa no caixão. O mesmo lenço."], ["CAÍQUE", "É ela."], ["HELENA", "A mulher do enterro comprou o chip que me ameaçou."], ["CAÍQUE", "E a gente ainda não sabe nem o nome dela."]]}, {"s": "EXT. AVENIDA BEIRA-RIO — PRÉDIO DE SEU RAIMUNDO — TRÊS MESES DEPOIS — FIM DE TARDE", "l": [["*", "Letreiro: \"Três meses depois\". Sol se pondo. Na portaria, Seu Raimundo atrás do balcão. A porta se abre. Carla entra, sem gesso, com o estojo do violino."], ["RAIMUNDO", "Olha quem voltou andando!"], ["CARLA", "Perdi a audição. A orquestra abriu outra para o ano que vem. Eu vou de novo."], ["RAIMUNDO", "Vai e passa."], ["*", "Carla abre o estojo. Afina o violino. A mão esquerda ainda está um pouco rígida."], ["CARLA", "Eu estou treinando de novo. Queria que o senhor fosse a primeira pessoa a ouvir."], ["*", "Seu Raimundo desliga o rádio de pilha. Carla toca. A música enche a portaria. Moradores param nas escadas para ouvir. Seu Raimundo enxuga os olhos com o lenço do bolso."]]}, {"s": "TELA PRETA", "l": [["VOZ", "A lei não exige heróis. Exige um telefonema. E pune quem não fez nem isso. No próximo episódio: um áudio num grupo de condomínio e uma acusação que não se apaga com um \"foi mal\". Artigo 138."]]}, {"s": "O VEREDITO — CARDS NARRADOS", "l": [["*", "Tela preta. Os cards do Veredito surgem um a um."], ["VOZ", "Artigo 135 do Código Penal: deixar de prestar assistência, quando possível fazê-lo sem risco pessoal, a pessoa ferida ou em grave e iminente perigo, ou não pedir, nesses casos, o socorro da autoridade pública. É a omissão de socorro."], ["VOZ", "A pena é de detenção de um a seis meses, ou multa. Se da omissão resulta lesão corporal de natureza grave, a pena aumenta de metade. Se resulta morte, é triplicada. O aumento só vale se a falta de socorro causou o resultado pior."], ["VOZ", "A lei não exige heroísmo. Quem não pode ajudar sem correr risco cumpre o dever pedindo socorro à autoridade pública, como ligar para o 192 ou para o 190."], ["VOZ", "Não confunda: o motorista que causa o acidente e não socorre a vítima responde pelo Código de Trânsito, por lesão corporal culposa na direção de veículo, com pena aumentada por não prestar socorro, e ainda pelo crime de fugir do local para escapar da responsabilidade."], ["VOZ", "E quem tem o dever legal de cuidar da vítima, como um salva-vidas em serviço ou os pais de uma criança, pode responder pelo próprio resultado, como se o tivesse causado."]]}]}, "138": {"dur": 21, "logline": "A uma semana do casamento da filha, a síndica Neide ouve, no grupo do condomínio, um áudio que a chama de ladra: \"Ela desviou oitenta mil do fundo de obras.\" O pior é que o dinheiro sumiu mesmo. Para se defender, o acusador vai tentar provar que disse a verdade.", "twist": "Calúnia é atribuir falsamente a alguém um fato definido como crime. Na calúnia, o acusado pode tentar provar que o fato é verdadeiro: é a exceção da verdade. Só que o desvio existiu, mas não foi Neide quem o cometeu, e a acusação contra ela continua falsa. Quem repassa a acusação sabendo que é falsa também responde. E quem se retrata por completo antes da sentença fica isento de pena, devendo fazer a retratação pelo mesmo meio, se a vítima pedir.", "guests": [{"n": "Neide Prado", "r": "Vítima, síndica, 59 anos", "d": "Organizada, orgulhosa da própria honestidade, mãe dedicada"}, {"n": "Larissa Prado", "r": "Filha de Neide, noiva, 27 anos", "d": "Alegre, protetora da mãe"}, {"n": "Osvaldo Reis", "r": "Acusador, 63 anos", "d": "Desconfiado, perdeu a eleição de síndico, acredita sinceramente que está denunciando um crime"}, {"n": "Wagner Assunção", "r": "Subsíndico e tesoureiro, 45 anos", "d": "Prestativo demais, nervoso quando ninguém está olhando"}, {"n": "Dona Gilda", "r": "Vizinha que repassou o áudio, 74 anos", "d": "Fofoqueira de boa-fé, repassa tudo sem ler"}, {"n": "Dr. Jurandir Lopes", "r": "Advogado de Osvaldo, 70 anos", "d": "Teatral, à moda antiga"}, {"n": "Dona Zuleica", "r": "Vizinha de Jairo", "d": "Vizinha de muro de Seu Jairo há quarenta anos. Sabe tudo o que acontece na rua."}, {"n": "Vinícius Mendes", "r": "Réu do caso Jairo", "d": "Músico endividado, impulsivo e irônico quando tem medo. O suspeito perfeito."}, {"n": "Dalva Reis", "r": "Esposa de Osvaldo, 60 anos", "d": "Sensata, sincera com o marido"}, {"n": "Rafael", "r": "Noivo de Larissa, 29 anos", "d": "Gentil e apaziguador"}], "scenes": [{"s": "ANTERIORMENTE", "l": [["*", "Imagens rápidas dos episódios anteriores."], ["VOZ", "Anteriormente, na JURISPLAY. A delegada Helena descobriu que o chip usado para ameaçá-la foi comprado numa banca em frente ao Clube Atlético Aurora, onde Seu Jairo dançava bolero toda quinta. Nas imagens da câmera, uma mulher de óculos escuros e um lenço de seda estampado. O mesmo lenço da mulher do enterro. Ninguém sabe o nome dela."], ["*", "Corte para a cena de abertura."]]}, {"s": "INT. CONDOMÍNIO JARDIM DAS ACÁCIAS — SALÃO DE FESTAS — FIM DE TARDE", "l": [["*", "Salão sendo decorado. Arranjos de flores brancas, luzes de varal. NEIDE PRADO, 59, chaveiro do condomínio no pescoço, sobe numa escada para pendurar um arranjo. LARISSA, 27, filha dela, segura a escada rindo."], ["LARISSA", "Mãe, desce daí. Tem gente pra isso."], ["NEIDE", "Tem gente pra isso, e tem a mãe da noiva. Sábado que vem, este salão vai estar o mais bonito da cidade."], ["*", "No salão há mais quatro moradores ajudando. De repente, todos os celulares vibram ao mesmo tempo. Um após o outro."], ["*", "Larissa olha o próprio celular. Grupo \"Moradores Acácias\". Um áudio de OSVALDO REIS, 1min12s. Ela aperta o play sem pensar."], ["OSVALDO", "(áudio) Boa tarde, vizinhos. Eu não posso mais ficar calado. Eu tenho prova. A dona Neide desviou oitenta mil reais do fundo de obras. É por isso que a fachada nunca fica pronta. Ela é uma ladra. E vai fazer festa de casamento com o nosso dinheiro."], ["*", "O salão fica em silêncio. Os vizinhos olham para Neide, lá no alto da escada. Uma senhora larga o arranjo que segurava."], ["*", "As flores escorregam das mãos de Neide e caem no chão."], ["*", "Corte seco para preto."]]}, {"s": "VINHETA", "l": [["*", "O triângulo laranja da JURISPLAY. ART. 138. \"O Áudio do Grupo\"."]]}, {"s": "INT. APARTAMENTO DE NEIDE — SALA — NOITE", "l": [["*", "Neide sentada no sofá, olhando o celular. O áudio já foi repassado para outros três grupos: \"Amigas da Hidro\", \"Igreja Santa Luzia\", \"Feira de Sábado\". Larissa ao lado."], ["LARISSA", "A Dona Gilda repassou para todos os grupos dela. A tia Rosa já me ligou perguntando se é verdade."], ["NEIDE", "Doze anos, Larissa. Doze anos de síndica, nenhuma conta rejeitada. Eu comprei a lâmpada do corredor com o meu dinheiro quando o caixa estava vazio."], ["LARISSA", "Mãe, ninguém que te conhece acredita nisso."], ["NEIDE", "Quem me conhece não precisa acreditar. Mas e os outros? Três pessoas cancelaram a presença no casamento hoje."], ["*", "Larissa abraça a mãe. Neide não chora. Fica olhando para o vestido de noiva pendurado na porta do quarto."]]}, {"s": "INT. CONDOMÍNIO JARDIM DAS ACÁCIAS — SALÃO DE FESTAS — NOITE (ASSEMBLEIA)", "l": [["*", "O mesmo salão das flores, agora com cadeiras de plástico enfileiradas. Assembleia extraordinária. Uns quarenta moradores. Neide na mesa da frente, com a pasta de prestação de contas. Ao lado dela, Wagner, o tesoureiro. Osvaldo de pé no fundo, de braços cruzados."], ["MORADOR 1", "Oitenta mil, Dona Neide! A senhora vai explicar ou não vai?"], ["NEIDE", "Eu vou explicar o que eu sei. Toda a prestação de contas está aqui. Cada nota. Cada recibo. Quem quiser pode olhar."], ["MORADORA 2", "Papel aceita qualquer coisa!"], ["OSVALDO", "(do fundo) E o extrato do banco, aceita qualquer coisa também?"], ["*", "Burburinho. Wagner se levanta, com as mãos para cima, conciliador."], ["WAGNER", "Gente, gente. Calma. Eu sou o tesoureiro e garanto: a Dona Neide é a pessoa mais honesta que eu conheço. Deve ser um erro do banco. Eu vou pessoalmente ao gerente amanhã."], ["*", "Neide olha para Wagner, agradecida. A câmera fica um segundo a mais no rosto dele: o sorriso não chega aos olhos."], ["MORADOR 1", "Eu proponho a destituição da síndica até a apuração!"], ["*", "Mãos se levantam. Muitas. Neide conta em silêncio. Larissa, sentada na primeira fila, aperta os punhos."], ["NEIDE", "Não precisam votar."], ["*", "Ela tira o chaveiro enorme do pescoço e o coloca sobre a mesa."], ["NEIDE", "Eu me afasto. Até provarem que eu não roubei. Mas o casamento da minha filha vai ser neste salão, no sábado. Está reservado e pago com o meu dinheiro."], ["*", "Ela sai do salão de cabeça erguida. Larissa vai atrás. Ninguém fala nada."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — MANHÃ", "l": [["*", "Neide, muito arrumada, com uma pasta de prestação de contas no colo. Helena ouve o áudio."], ["HELENA", "Dona Neide, o direito penal protege a honra de três formas. Calúnia, difamação e injúria. É importante saber a diferença."], ["NEIDE", "Eu só sei que ele mentiu."], ["HELENA", "Injúria é a ofensa à dignidade, sem contar nenhum fato. Chamar alguém de incompetente, por exemplo. Difamação é atribuir um fato que ofende a reputação, mas que não é crime. Calúnia é a mais grave: atribuir falsamente a alguém um fato definido como crime."], ["NEIDE", "Desviar dinheiro do condomínio é crime."], ["HELENA", "É. Por isso, o que ele disse é calúnia, se for falso. Artigo 138. Detenção de seis meses a dois anos e multa."], ["NEIDE", "E ele chamou de ladra também."], ["HELENA", "Isso, sozinho, seria injúria. Mas aqui veio junto com um fato: o desvio de oitenta mil do fundo de obras. É a acusação do fato que faz a calúnia."], ["NEIDE", "Então a senhora vai prender ele?"], ["HELENA", "Aí é que está. Nos crimes contra a honra de uma pessoa comum, quem acusa não é o promotor. É a própria vítima. A senhora precisa de um advogado para entrar com uma queixa-crime no fórum. E tem seis meses, a partir de quando soube quem foi o autor."], ["NEIDE", "Advogado custa caro. O dinheiro do casamento já acabou."], ["HELENA", "Então a senhora vai procurar a Defensoria Pública. Eu conheço um defensor que gosta de casos difíceis."]]}, {"s": "INT. DEFENSORIA PÚBLICA — SALA DE OTÁVIO — DIA", "l": [["*", "Otávio lê a pasta de prestação de contas de Neide. Na janela, a planta que estava morrendo agora tem uma folha nova."], ["OTÁVIO", "Dona Neide, normalmente eu sento do lado de quem é acusado. Hoje eu vou acusar."], ["NEIDE", "E o senhor sabe fazer isso?"], ["OTÁVIO", "Vou aprender com a melhor."], ["*", "Ele sorri sozinho. Neide não entende a piada."], ["OTÁVIO", "Vou preparar a queixa-crime por calúnia. E vou pedir o aumento de pena: a acusação foi feita na presença de várias pessoas e espalhada em grupos de mensagem."], ["NEIDE", "Eu só quero que todo mundo saiba que eu não roubei."], ["OTÁVIO", "Então a gente vai precisar provar duas coisas. Que a senhora não roubou. E que ele disse que roubou."]]}, {"s": "INT. APARTAMENTO DE OSVALDO — COZINHA — NOITE", "l": [["*", "Cozinha arrumada demais, com um rádio de notícias ligado. DALVA, 60, esposa de Osvaldo, lava a louça. Osvaldo, sentado à mesa, revisa a planilha dos extratos com uma régua e uma caneta marca-texto."], ["DALVA", "Você vai passar a noite olhando isso de novo?"], ["OSVALDO", "Oitenta mil, Dalva. Os números não mentem."], ["DALVA", "Os números não. Mas quem lê os números às vezes se engana."], ["*", "Osvaldo tira os óculos."], ["OSVALDO", "Você acha que eu inventei?"], ["DALVA", "Eu acho que você perdeu a eleição por três votos e nunca engoliu isso."], ["OSVALDO", "Isso não tem nada a ver."], ["DALVA", "Osvaldo, você mandou aquele áudio às onze da noite, depois de três copos de vinho, chamando a mulher de ladra. Uma mulher que levou sopa pra você quando você operou a vesícula."], ["*", "Osvaldo fica em silêncio. Dalva enxuga as mãos e se senta à frente dele."], ["DALVA", "Você tem certeza de que foi ela quem fez as transferências?"], ["OSVALDO", "Quem mais teria acesso?"], ["DALVA", "Você me diz. Você que é o bancário."], ["*", "Osvaldo olha a planilha de novo. Pela primeira vez, a certeza dele vacila."]]}, {"s": "INT. CONDOMÍNIO JARDIM DAS ACÁCIAS — ESCRITÓRIO DA ADMINISTRAÇÃO — DIA", "l": [["*", "Sala pequena com armário de pastas. WAGNER ASSUNÇÃO, 45, subsíndico e tesoureiro, camisa polo com o logotipo de uma construtora, recebe Helena e Caíque com um sorriso."], ["WAGNER", "Que coisa horrível com a Dona Neide. Uma santa. Eu cuido da tesouraria há dois anos e nunca vi nada errado."], ["CAÍQUE", "Quem tem acesso à conta do fundo de obras?"], ["WAGNER", "A síndica. E eu, como tesoureiro, para pagar fornecedores. O token do banco fica comigo, a Dona Neide não gosta de tecnologia."], ["HELENA", "E o seu Osvaldo diz que tem prova de um desvio."], ["WAGNER", "Seu Osvaldo perdeu a eleição. Desde então vê fantasma em tudo."], ["*", "Helena observa as unhas de Wagner, roídas até o sabugo."]]}, {"s": "INT. APARTAMENTO DE NEIDE — VARANDA — NOITE", "l": [["*", "Larissa e o noivo, RAFAEL, 29, sentados no chão da varanda com uma lista de convidados riscada."], ["RAFAEL", "Mais seis cancelaram hoje."], ["LARISSA", "A gente podia fazer em outro lugar. Num salão alugado. Longe daqui."], ["RAFAEL", "Ou podia adiar."], ["*", "Neide aparece na porta da varanda com uma bandeja de bolo."], ["NEIDE", "Ninguém vai adiar nada."], ["LARISSA", "Mãe, as pessoas estão falando."], ["NEIDE", "Deixa falar. Se eu mudar o casamento de lugar, é como se eu dissesse que tenho vergonha. E eu não tenho vergonha de nada."], ["*", "Ela coloca a bandeja no chão, entre os dois, e se senta com dificuldade."], ["NEIDE", "O seu pai e eu casamos naquele salão, Larissa. Trinta e um anos atrás. Ele teria orgulho de te ver lá."], ["*", "Larissa encosta a cabeça no ombro da mãe."], ["RAFAEL", "Então a gente imprime mais convites."], ["NEIDE", "Imprime. E manda um para o Seu Osvaldo também."], ["LARISSA", "Mãe!"], ["NEIDE", "Quando a verdade aparecer, eu quero ele lá. Pendurando flor."]]}, {"s": "INT. FÓRUM — 2ª VARA CRIMINAL — DIA", "l": [["*", "Primeira audiência. Marta preside. Otávio ao lado de Neide. DR. JURANDIR LOPES, 70, terno marrom antigo, ao lado de Osvaldo. Iara sentada à direita da juíza."], ["OTÁVIO", "(para Iara, baixinho) Você do outro lado da sala hoje."], ["IARA", "(baixinho) Eu não estou do outro lado. Na ação privada, quem acusa é a vítima. O Ministério Público só fiscaliza. Eu sou a fiscal da lei, doutor."], ["OTÁVIO", "Então me fiscaliza."], ["IARA", "Com prazer."], ["*", "Marta bate a caneta na mesa. Os dois se calam."], ["MARTA", "Doutor Jurandir."], ["JURANDIR", "Excelência, meu cliente não caluniou ninguém. Ele disse a verdade. E o Código permite provar a verdade. É a exceção da verdade, artigo 138, parágrafo terceiro."], ["*", "Jurandir ergue uma planilha com teatralidade."], ["JURANDIR", "Extratos bancários da conta do fundo de obras. Oitenta mil reais transferidos em seis vezes, nos últimos oito meses, para uma conta desconhecida. O dinheiro sumiu, Excelência!"], ["*", "Murmúrio na sala. Neide fica pálida. Otávio pega a planilha e lê rápido."], ["NEIDE", "(sussurrando) Doutor, eu não fiz isso."], ["OTÁVIO", "(sussurrando) Eu sei. Mas alguém fez."], ["MARTA", "Recebo a exceção da verdade. A defesa terá a oportunidade de provar o fato. Se provar que a querelante cometeu o desvio, não há calúnia. Audiência suspensa por quinze dias."]]}, {"s": "INT. FÓRUM — CORREDOR DE MÁRMORE — DIA", "l": [["*", "Saída da audiência. Neide, abalada, é levada por Larissa até o banco do corredor. Otávio para diante da janela. Iara sai da sala e para ao lado dele, sem olhar para ele."], ["IARA", "Você não esperava aquela planilha."], ["OTÁVIO", "Não."], ["IARA", "Se a exceção da verdade for provada, a sua cliente sai daqui como ladra. Com sentença."], ["OTÁVIO", "Ela não é ladra."], ["IARA", "Eu sei."], ["*", "Otávio vira a cabeça para ela."], ["OTÁVIO", "Você sabe?"], ["IARA", "Eu li a prestação de contas inteira ontem à noite. Ela comprou uma lâmpada com o próprio dinheiro e anotou: \"Devolver ao caixa quando houver saldo.\" Ladra não anota isso."], ["OTÁVIO", "Como fiscal da lei, você não devia estar do meu lado."], ["IARA", "Eu estou do lado da lei, Otávio. Hoje ela por acaso está do seu lado."], ["*", "Ela coloca um papel dobrado na mão dele."], ["IARA", "Os extratos mostram para onde foi o dinheiro. Peça a quebra do sigilo da conta de destino. Qualquer estudante pensaria nisso."], ["OTÁVIO", "Você podia ter pedido."], ["IARA", "Eu não sou parte. Você é."], ["*", "Ela vai embora pelo corredor. Otávio desdobra o papel: o número da conta de destino, circulado em caneta vermelha."]]}, {"s": "INT. CONDOMÍNIO JARDIM DAS ACÁCIAS — ESCRITÓRIO DA ADMINISTRAÇÃO — MADRUGADA", "l": [["*", "Duas da manhã. Escritório escuro, só a luz do computador. Wagner, de moletom com capuz, digita depressa. Na tela, o sistema do banco: \"Histórico de acessos\". Ele tenta clicar em \"Excluir registros\". Uma mensagem: \"Operação não permitida\"."], ["*", "Ele abre o armário de pastas. Tira uma pasta com o nome \"Fundo de Obras\", arranca algumas folhas e as enfia na mochila."], ["*", "No canto do teto, uma pequena luz vermelha pisca: a câmera de segurança do condomínio, que ele mesmo mandou instalar no ano passado."], ["*", "Wagner olha para a câmera. Fica pálido. Puxa o capuz sobre o rosto e sai depressa."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE INVESTIGAÇÃO — DIA", "l": [["*", "Caíque cruza os extratos com os registros de acesso ao banco. Helena e Otávio ao lado."], ["CAÍQUE", "Seis transferências. Todas feitas pelo aplicativo do banco, com o token da tesouraria."], ["OTÁVIO", "Token que fica com o tesoureiro."], ["CAÍQUE", "E olha para onde foi o dinheiro. Conta de uma empresa chamada Assunção Reformas e Pinturas."], ["HELENA", "Wagner Assunção."], ["CAÍQUE", "E tem mais. Quatro das seis transferências foram feitas em dias em que a Dona Neide estava viajando para a casa da irmã. Ela não tinha nem o token nem como fazer."], ["OTÁVIO", "O desvio é verdadeiro. Mas a autora não é a Neide."], ["HELENA", "Então a acusação contra ela continua falsa. E o Seu Wagner acabou de ganhar um episódio próprio. Apropriação indébita."], ["CAÍQUE", "Temporada dois."], ["*", "Helena olha para ele, sem entender. Caíque dá de ombros."]]}, {"s": "INT. CONDOMÍNIO JARDIM DAS ACÁCIAS — ESCRITÓRIO DA ADMINISTRAÇÃO — DIA", "l": [["*", "Wagner, de camisa polo, organiza pastas como se nada tivesse acontecido. Helena e Caíque entram sem bater. Caíque coloca o tablet sobre a mesa: a imagem da câmera de segurança, Wagner de capuz, duas da manhã, arrancando folhas de uma pasta."], ["WAGNER", "Isso... eu estava organizando o arquivo."], ["HELENA", "Às duas da manhã. De capuz."], ["WAGNER", "Eu trabalho até tarde."], ["CAÍQUE", "A conta que recebeu os oitenta mil é da Assunção Reformas e Pinturas. Sua empresa. E quatro transferências foram feitas quando a síndica estava viajando."], ["*", "Wagner se senta devagar. Roe a unha do polegar."], ["WAGNER", "Eu ia devolver. Eu juro que ia devolver. A empresa estava quebrando. Eram só uns meses."], ["HELENA", "O senhor deixou uma mulher inocente ser chamada de ladra no grupo. Ficou sentado ao lado dela na assembleia, defendendo ela, enquanto sabia de tudo."], ["WAGNER", "Eu não mandei o Osvaldo gravar aquele áudio!"], ["HELENA", "Não. Mas também não abriu a boca quando ele gravou."], ["*", "Helena se levanta."], ["HELENA", "O senhor vai ser indiciado por apropriação indébita. E o que o senhor arrancou daquela pasta também vai virar problema."], ["*", "Wagner olha para a mochila, no canto da sala. Caíque já a está pegando."], ["CAÍQUE", "Com licença."]]}, {"s": "INT. CADEIA PÚBLICA — PARLATÓRIO — DIA", "l": [["*", "Vinícius, mais magro, do outro lado do vidro. Otávio segura um formulário."], ["OTÁVIO", "Consegui autorização do juiz para pegar umas roupas suas na casa do seu tio. Você precisa de quê?"], ["VINÍCIUS", "Meu casaco preto. Uns livros. E, se der, o violão. Disseram que posso ter um violão aqui se o diretor autorizar."], ["OTÁVIO", "Vou tentar."], ["VINÍCIUS", "Doutor... Otávio. A Dona Zuleica me mandou um bolo pelo meu primo. Com um bilhete. Ela disse que viu uma mulher ruiva com o meu tio no quintal uma vez."], ["OTÁVIO", "A delegada já está atrás dessa mulher."], ["VINÍCIUS", "Meu tio namorando. Setenta e quatro anos. Saindo de terno, comprando perfume."], ["*", "Ele ri, os olhos molhados."], ["VINÍCIUS", "E eu brigando com ele porque achei que estavam roubando ele. E se estavam mesmo?"], ["OTÁVIO", "Se estavam, a gente vai descobrir."], ["VINÍCIUS", "E se ele estava só feliz? E eu estraguei a última manhã dele com dinheiro?"], ["*", "Otávio não tem resposta. Coloca a palma da mão no vidro. Vinícius, depois de um segundo, coloca a dele do outro lado."]]}, {"s": "EXT. CASA DE JAIRO — PORTÃO — DIA", "l": [["*", "Otávio, com autorização judicial na mão, abre o portão. Dona Zuleica, regando as plantas, se aproxima pelo muro."], ["ZULEICA", "O senhor é da polícia?"], ["OTÁVIO", "Defensor do Vinícius. Vim buscar umas roupas para ele, com autorização do juiz."], ["ZULEICA", "Coitado do menino. Eu falei da briga, mas nunca achei que ele fosse capaz."]]}, {"s": "INT. CASA DE JAIRO — QUARTO DE JAIRO — DIA", "l": [["*", "Quarto simples, cama arrumada, um terno pendurado atrás da porta. Otávio separa roupas numa sacola. Na mesa de cabeceira, um livro antigo: \"Dom Casmurro\", de Machado de Assis. Dele sai a ponta de um papel dobrado."], ["*", "Otávio não toca. Tira uma foto. Pega o celular e liga."], ["OTÁVIO", "Delegada? Encontrei um documento. Não mexi em nada. A senhora precisa vir aqui. E chame a perita."]]}, {"s": "INT. CASA DE JAIRO — QUARTO DE JAIRO — FIM DE TARDE", "l": [["*", "Lúcia, de luvas, abre o papel sobre um plástico. Helena, Caíque, Otávio e Iara em volta. Um testamento escrito à mão, com assinatura de Jairo e de três testemunhas."], ["LÚCIA", "(lendo) \"Eu, Jairo Mendes, em pleno juízo, deixo a casa da Rua dos Ipês, número 214, com tudo o que nela houver, à minha companheira Marisa Vilela, que me devolveu a alegria de dançar.\""], ["*", "Silêncio no quarto."], ["IARA", "A data?"], ["LÚCIA", "Seis semanas antes da morte."], ["CAÍQUE", "Três semanas antes do chip."], ["HELENA", "Marisa Vilela."], ["*", "Lúcia vira o livro. Na última página, a letra de Jairo, a lápis, trêmula: \"Quinta. Conversar com M. Rasgar o testamento?\""], ["OTÁVIO", "Ele ia mudar de ideia."], ["HELENA", "E morreu antes da quinta-feira."], ["*", "Iara olha para Otávio. Pela primeira vez, sem ironia."], ["IARA", "Isso muda o caso."], ["OTÁVIO", "Eu sei."], ["IARA", "Eu vou ter que pensar se mantenho a acusação."], ["OTÁVIO", "Eu sei. É por isso que eu te liguei."], ["*", "Pela janela, Dona Zuleica espia por cima do muro."], ["ZULEICA", "Esse livro... Ele lia esse livro no quintal pra uma moça. Ruiva. Eu vi uma vez só. Ele estava tão feliz que eu fiquei com vergonha de perguntar."]]}, {"s": "INT. CONDOMÍNIO JARDIM DAS ACÁCIAS — HALL DOS ELEVADORES — NOITE", "l": [["*", "Osvaldo espera o elevador. Dona Gilda chega com o celular de letra gigante."], ["GILDA", "Seu Osvaldo, o senhor viu? Disseram que foi o Wagner. O senhor vai ser preso?"], ["OSVALDO", "Ninguém vai ser preso, Dona Gilda."], ["GILDA", "E eu? Eu repassei o áudio pra todo mundo!"], ["OSVALDO", "A senhora sabia que era mentira quando repassou?"], ["GILDA", "Claro que não! Eu nem ouvi direito, eu só encaminhei."], ["OSVALDO", "Então a senhora pode dormir. O Código só pune quem repassa sabendo que é falso."], ["*", "O elevador chega. Gilda entra aliviada. Osvaldo fica do lado de fora, olhando para o celular. Abre o grupo \"Moradores Acácias\". Segura o botão de gravar. Solta. Não grava."]]}, {"s": "INT. FÓRUM — 2ª VARA CRIMINAL — DIA", "l": [["*", "Segunda audiência. Marta, Iara, Otávio, Neide, Jurandir, Osvaldo."], ["MARTA", "Doutor Jurandir, a exceção da verdade."], ["JURANDIR", "Excelência... a perícia bancária demonstrou que as transferências foram feitas pelo tesoureiro."], ["OTÁVIO", "Excelência, o fato existiu. Mas quem o praticou não foi a querelante. A exceção da verdade exige provar que a pessoa acusada cometeu o crime. E a Dona Neide não cometeu. A imputação continua falsa."], ["*", "Iara se levanta."], ["IARA", "Como fiscal da lei, o Ministério Público concorda. E registra um ponto que a jurisprudência ainda discute: se um grupo de mensagens conta como rede social, o que triplicaria a pena. A doutrina se divide."], ["MARTA", "Senhor Osvaldo, deseja dizer alguma coisa?"], ["*", "Osvaldo se levanta devagar. Tira os óculos."], ["OSVALDO", "Excelência, eu achei que estava denunciando um crime. Eu vi os extratos e pensei: só pode ser ela. Eu estava com raiva da eleição. Eu acusei a pessoa errada."], ["JURANDIR", "Excelência, meu cliente se retrata. Artigo 143: o querelado que, antes da sentença, se retrata cabalmente da calúnia fica isento de pena."], ["OTÁVIO", "Excelência, a calúnia foi feita por um meio de comunicação. O parágrafo único do artigo 143 diz que, se a vítima quiser, a retratação deve ser feita pelos mesmos meios."], ["MARTA", "Dona Neide, a senhora quer?"], ["NEIDE", "Quero. No mesmo grupo. Com a mesma voz."]]}, {"s": "INT. CONDOMÍNIO JARDIM DAS ACÁCIAS — SALÃO DE FESTAS — DIA", "l": [["*", "O salão quase pronto para o casamento. Vizinhos ajudando. Osvaldo no centro, com o celular na mão, todos olhando para ele. Neide de braços cruzados ao fundo."], ["*", "Osvaldo aperta o botão de gravar."], ["OSVALDO", "Boa tarde, vizinhos. Aqui é o Osvaldo. Há três semanas eu mandei um áudio dizendo que a Dona Neide desviou dinheiro do fundo de obras. Era mentira. Ela não desviou nada. Quem desviou foi outra pessoa, e a polícia já sabe quem. Eu peço desculpas à Dona Neide, à Larissa e a todos. Eu errei."], ["*", "Ele solta o botão. Todos os celulares do salão vibram ao mesmo tempo. Dona Gilda já está encaminhando para os outros grupos."], ["*", "Neide descruza os braços. Vai até a escada e pega o arranjo de flores que tinha caído no primeiro dia."], ["NEIDE", "Seu Osvaldo, o senhor é alto. Pendura isso aqui pra mim."], ["*", "Osvaldo pega o arranjo, envergonhado, e sobe na escada."]]}, {"s": "INT. CONDOMÍNIO JARDIM DAS ACÁCIAS — SALÃO DE FESTAS — NOITE (CASAMENTO)", "l": [["*", "Luzes acesas, música. Larissa de vestido de noiva dança com o noivo. Neide ri no centro da pista. Osvaldo serve ponche num canto. Otávio está ali, de terno, convidado pela família, depois do fim do caso."], ["*", "Neide puxa Otávio para dançar. Ele dança mal. Ela ri."], ["NEIDE", "O senhor acusa melhor do que dança, doutor."], ["OTÁVIO", "A senhora não viu a outra pessoa acusando."], ["*", "Otávio olha o celular. Uma mensagem de Iara: \"Aquele testamento muda muita coisa. Ainda não basta para soltar o Vinícius. Mas obrigada por ter me ligado.\" Ele sorri e guarda o celular."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — NOITE", "l": [["*", "Helena diante do quadro de cortiça. Ela retira o post-it \"Mulher do enterro. Quem?\" e escreve um novo: \"MARISA VILELA\". Cola no centro. Liga o fio vermelho ao açucareiro, à terceira chave, ao chip."], ["*", "Caíque entra com um papel impresso."], ["CAÍQUE", "Marisa Vilela. Cinquenta e oito anos. Sem antecedentes. Endereço: Rua das Camélias, 90. Profissão registrada: professora de dança de salão."], ["HELENA", "Onde?"], ["CAÍQUE", "Clube Atlético Aurora. Às quintas-feiras."], ["*", "Helena olha o calendário na parede. Amanhã é quinta-feira."]]}, {"s": "TELA PRETA", "l": [["VOZ", "Acusar alguém de um crime que não cometeu também é crime. Mesmo que o crime tenha acontecido. Mesmo que tenha sido só um áudio. No próximo episódio: uma garçonete, uma ofensa diante de todos e um baile de quinta-feira. Artigo 140."]]}, {"s": "O VEREDITO — CARDS NARRADOS", "l": [["*", "Tela preta. Os cards do Veredito surgem um a um."], ["VOZ", "Artigo 138 do Código Penal: caluniar alguém, imputando-lhe falsamente fato definido como crime. A pena é de detenção de seis meses a dois anos e multa. Quem, sabendo que a acusação é falsa, a espalha ou divulga, responde pela mesma pena."], ["VOZ", "Na calúnia, em regra, o acusado pode provar que o fato é verdadeiro. É a exceção da verdade. Mas precisa provar que foi a vítima quem cometeu o crime. Se o crime existiu, mas foi outra pessoa, a calúnia continua."], ["VOZ", "A pena aumenta de um terço se o crime é cometido na presença de várias pessoas ou por meio que facilite a divulgação. E é aplicada em triplo se cometido ou divulgado nas redes sociais."], ["VOZ", "Se o acusado se retrata por completo antes da sentença, fica isento de pena. Se a calúnia foi feita por um meio de comunicação, a vítima pode exigir que a retratação seja feita pelo mesmo meio."], ["VOZ", "Não confunda: difamação é atribuir um fato ofensivo que não é crime. Injúria é ofender sem atribuir fato nenhum. E nos crimes contra a honra de uma pessoa comum, quem acusa é a vítima, por queixa-crime, em até seis meses."]]}]}, "140": {"dur": 20, "logline": "Numa quinta-feira lotada, um cliente chama a garçonete Jéssica de \"burra e incompetente\" na frente do salão inteiro. No dia seguinte, ela descobre que ele é o professor que vai avaliar seu estágio na faculdade de Direito. Na mesma noite, a delegada Helena vai a um baile de bolero para dançar com a principal suspeita do caso Jairo.", "twist": "Injúria é ofender a dignidade de alguém sem atribuir um fato: só o xingamento. Feita diante de várias pessoas, a pena aumenta de um terço. Ao contrário da calúnia, na injúria a retratação não isenta de pena. E o juiz só pode deixar de aplicar a pena se a vítima provocou a ofensa ou respondeu na hora com outra ofensa, o que não aconteceu.", "guests": [{"n": "Jéssica Moraes", "r": "Vítima, garçonete e estudante de Direito, 23 anos", "d": "Trabalhadora, tímida, firme quando decide"}, {"n": "Henrique Valle", "r": "Ofensor, professor de Direito Civil, 50 anos", "d": "Arrogante, impaciente, acha que a posição o protege"}, {"n": "Tiago Ferreira", "r": "Cozinheiro do Sabor da Praça, 26 anos", "d": "Calado, gentil, apaixonado por Jéssica"}, {"n": "Dra. Beatriz Lemos", "r": "Advogada de Jéssica, coordenadora do Núcleo de Prática Jurídica, 52 anos", "d": "Calorosa com alunos, temida por colegas"}, {"n": "Marisa Vilela", "r": "Professora de dança, suspeita", "d": "Professora de dança de salão, encantadora em público e calculista em particular. Sempre com um lenço de seda."}, {"n": "Seu Alcides", "r": "Dono do Sabor da Praça", "d": "Dono do Sabor da Praça. Conhece todo mundo pelo nome e dança bolero às quintas."}, {"n": "Professora Ângela Ribas", "r": "Coordenadora do curso de Direito, 60 anos", "d": "Severa e justa"}, {"n": "Dona Celeste", "r": "Aluna de dança, 80 anos", "d": "Doce e curiosa"}], "scenes": [{"s": "ANTERIORMENTE", "l": [["*", "Imagens rápidas dos episódios anteriores."], ["VOZ", "Anteriormente, na JURISPLAY. No quarto de Seu Jairo, dentro de um livro, o defensor Otávio encontrou um testamento: a casa ficava para a companheira dele, Marisa Vilela. Na última página, uma anotação: \"Quinta. Conversar com M. Rasgar o testamento?\" Jairo morreu antes da quinta-feira. Marisa é professora de dança no Clube Atlético Aurora. E o baile é toda quinta."], ["*", "Corte para a cena de abertura."]]}, {"s": "INT. RESTAURANTE SABOR DA PRAÇA — NOITE (QUINTA-FEIRA)", "l": [["*", "Casa cheia, barulho de talheres. Seu Alcides, de camisa social e gravata-borboleta em vez do avental, atende no caixa. Helena, de blazer, come sozinha ao balcão."], ["ALCIDES", "Hoje não tem baile, doutora. O clube está trocando o piso do salão. Só reabre daqui a umas semanas."], ["HELENA", "Então, quando reabrir, o senhor me leva."], ["ALCIDES", "Levo. E ensino o passo básico. Dois para lá, dois para cá. O resto é coragem."], ["*", "JÉSSICA, 23, garçonete, rabo de cavalo, avental azul-marinho, equilibra três pratos em direção à mesa 12, nos fundos. Ali, HENRIQUE VALLE, 50, blazer azul, óculos de tartaruga, olha o relógio."], ["JÉSSICA", "O seu filé, senhor. Desculpe a demora, a cozinha está..."], ["HENRIQUE", "Quarenta minutos. Quarenta minutos. Eu pedi mal passado. Isto está cinza."], ["JÉSSICA", "Eu peço para refazerem agora mesmo."], ["HENRIQUE", "(alto, para o salão inteiro ouvir) Você é burra? É incompetente? Por isso que está aí, carregando prato a vida inteira."], ["*", "O salão fica em silêncio. Os garfos param no ar. Jéssica segura a bandeja com força. Os nós dos dedos ficam brancos. Ela não diz nada."], ["*", "Pela janela da cozinha, TIAGO, 26, o cozinheiro, para de mexer a panela."], ["*", "Ao balcão, Helena larga o garfo e vira a cabeça devagar na direção da mesa 12."], ["*", "Corte seco para preto."]]}, {"s": "VINHETA", "l": [["*", "O triângulo laranja da JURISPLAY. ART. 140. \"Mesa 12\"."]]}, {"s": "INT. RESTAURANTE SABOR DA PRAÇA — COZINHA — NOITE", "l": [["*", "Jéssica encostada na câmara fria, chorando em silêncio. Tiago coloca na mão dela um pratinho com um pudim."], ["TIAGO", "Pudim de leite. O último da noite. Eu guardei."], ["JÉSSICA", "Você sempre guarda o último."], ["TIAGO", "Sempre guardo pra você."], ["*", "Ela ri entre as lágrimas. Seu Alcides entra bufando."], ["ALCIDES", "Eu pus aquele homem pra fora. Disse que aqui ninguém fala assim com a minha equipe."], ["JÉSSICA", "Eu estudo Direito, Seu Alcides. Eu sei o nome do que ele fez. Injúria. Artigo 140."], ["ALCIDES", "Então faz alguma coisa, menina."], ["JÉSSICA", "É ação privada. Precisa de advogado. Eu mal pago o ônibus pra faculdade."], ["*", "Helena aparece na porta da cozinha."], ["HELENA", "Eu vi tudo. Se precisar de testemunha, eu estava no balcão."]]}, {"s": "INT. FACULDADE DE DIREITO — SALA DE AULA — NOITE", "l": [["*", "Sala cheia de estudantes cansados depois do trabalho. Na lousa, escrito à mão: \"CRIMES CONTRA A HONRA: CALÚNIA · DIFAMAÇÃO · INJÚRIA\". Dra. Beatriz Lemos, de brincos de madeira, anda entre as carteiras. Jéssica, na terceira fileira, não tira os olhos do caderno."], ["BEATRIZ", "Vamos testar. Eu digo uma frase, vocês dizem o crime. \"Fulano é um ladrão.\""], ["ESTUDANTE 1", "Calúnia!"], ["BEATRIZ", "Errado. Ladrão é um xingamento. Não tem fato. Injúria. Agora: \"Fulano furtou a carteira da professora na terça-feira, no estacionamento.\""], ["ESTUDANTE 2", "Calúnia. Fato determinado e definido como crime."], ["BEATRIZ", "Se for falso. Muito bem. E: \"Fulano chega bêbado no trabalho toda segunda-feira.\""], ["ESTUDANTE 1", "Calúnia de novo?"], ["BEATRIZ", "Chegar bêbado no trabalho é crime?"], ["ESTUDANTE 1", "...Não."], ["BEATRIZ", "Então é difamação. Fato ofensivo à reputação, mas que não é crime. Jéssica, você está muito quieta. \"Você é burra e incompetente.\""], ["*", "A sala fica em silêncio. Jéssica levanta a cabeça devagar."], ["JÉSSICA", "Injúria, professora. Ofensa à dignidade e ao decoro. Sem fato nenhum."], ["BEATRIZ", "E se for dita na frente de vinte pessoas?"], ["JÉSSICA", "Aumenta de um terço. Artigo 141, inciso três."], ["*", "Beatriz percebe alguma coisa no rosto dela. Para ao lado da carteira."], ["BEATRIZ", "Fica depois da aula, Jéssica."]]}, {"s": "INT. FACULDADE DE DIREITO DE PORTO AURORA — SALA DE ENTREVISTA — DIA", "l": [["*", "Sala com mesa comprida. Jéssica, de camisa social, nervosa, segura uma pasta com o currículo. A porta se abre. Entra o examinador do processo seletivo de estágio: Henrique Valle."], ["*", "Os dois se reconhecem. Ele para por meio segundo. Depois se senta como se nada fosse."], ["HENRIQUE", "Jéssica Moraes. Estágio no escritório-modelo de Direito Civil."], ["JÉSSICA", "Sim, professor."], ["HENRIQUE", "Boa média. Trabalha à noite?"], ["JÉSSICA", "Num restaurante. O senhor sabe qual."], ["*", "Silêncio. Henrique fecha a pasta dela."], ["HENRIQUE", "Eu espero que a senhorita não confunda as coisas. O que acontece num restaurante fica no restaurante. E o que acontece nesta sala depende só do seu desempenho."], ["*", "Ele sorri. Não é um sorriso gentil. Jéssica entende perfeitamente a mensagem."]]}, {"s": "INT. FACULDADE DE DIREITO — NÚCLEO DE PRÁTICA JURÍDICA — DIA", "l": [["*", "Sala cheia de estudantes atendendo pessoas. DRA. BEATRIZ LEMOS, 52, cabelo crespo grisalho volumoso, ouve Jéssica de braços cruzados."], ["BEATRIZ", "Ele disse isso? Na sua cara? Na entrevista?"], ["JÉSSICA", "Não com essas palavras. Mas disse."], ["BEATRIZ", "Querida, o Núcleo de Prática Jurídica existe para quem não pode pagar advogado. Você pode. Quer dizer, você pode não pagar. Eu faço a queixa."], ["JÉSSICA", "Professora, ele é seu colega."], ["BEATRIZ", "Por isso mesmo. Eu sei exatamente quem ele é."], ["*", "Beatriz abre o Código."], ["BEATRIZ", "Injúria, artigo 140: \"Injuriar alguém, ofendendo-lhe a dignidade ou o decoro.\" Detenção de um a seis meses, ou multa. Feita na presença de várias pessoas, aumenta de um terço, pelo artigo 141. Ação penal privada: a queixa é nossa. Prazo de seis meses."], ["JÉSSICA", "E a entrevista?"], ["BEATRIZ", "Isso é com a coordenação. Um professor não pode avaliar uma aluna que vai processar ele. Conflito de interesse. Ele sai da banca hoje."]]}, {"s": "INT. FACULDADE DE DIREITO — GABINETE DA COORDENAÇÃO — DIA", "l": [["*", "Sala da coordenadora do curso, PROFESSORA ÂNGELA RIBAS, 60. Henrique Valle está de pé diante da mesa, indignado."], ["HENRIQUE", "Me tirar da banca de estágio? Por causa de uma garçonete?"], ["ÂNGELA", "Por causa de uma aluna, Henrique. Que vai entrar com uma queixa-crime contra você. Você não pode avaliar alguém com quem tem um processo. É conflito de interesse. Você ensina isso no segundo período."], ["HENRIQUE", "Ela vai usar isso para passar no estágio!"], ["ÂNGELA", "Ela tem a maior média da turma. Não precisa de você para nada."], ["*", "Henrique abre a boca, mas não diz nada."], ["ÂNGELA", "E, sinceramente, Henrique? Gritar com uma funcionária num restaurante lotado? Você foi meu aluno. Eu não te ensinei isso."], ["*", "Henrique pega a pasta e sai. Bate a porta. Ângela suspira e risca o nome dele de uma lista na mesa."]]}, {"s": "EXT. FÓRUM — ESCADARIA — FIM DE TARDE", "l": [["*", "Começa a chover forte. Iara sai do fórum com a pasta sobre a cabeça. Otávio desce atrás dela."], ["OTÁVIO", "Iara! O testamento, o chip, o lenço. Você tem mais do que precisa para pedir a soltura do Vinícius."], ["IARA", "Eu tenho uma mulher que comprou um chip e herdou uma casa. Isso não prova que ela envenenou ninguém. E também não prova que o Vinícius não envenenou."], ["OTÁVIO", "Ele está preso há dois meses por um crime que você já não acredita que ele cometeu."], ["IARA", "Não diga o que eu acredito!"], ["*", "Os dois param sob a marquise do fórum. A chuva cai em cortina na frente deles."], ["OTÁVIO", "Você tem medo de admitir que pode ter errado."], ["IARA", "Eu tenho medo de errar de novo."], ["OTÁVIO", "De novo?"], ["IARA", "Da última vez que eu segui o coração em vez da razão, eu fiquei esperando você no aeroporto."], ["*", "Otávio fica imóvel."], ["OTÁVIO", "Você foi."], ["IARA", "Eu fui. E você não estava lá. Você tinha trocado o voo e não me avisou."], ["OTÁVIO", "Eu troquei o voo porque achei que você não ia."], ["*", "Silêncio. Só a chuva. Otávio se aproxima. Iara não se afasta. Ele a beija. Ela segura a gola do terno dele."], ["*", "Ela se afasta de repente, ofegante."], ["IARA", "Não. Isso não pode acontecer."], ["OTÁVIO", "Já aconteceu."], ["IARA", "Não enquanto a gente estiver no mesmo processo, Otávio. Você defende o Vinícius. Eu acuso."], ["*", "Ela desce a escadaria na chuva, sem a pasta sobre a cabeça. Otávio fica sob a marquise, encharcado por dentro."]]}, {"s": "INT. APARTAMENTO DE IARA — SALA — NOITE", "l": [["*", "Apartamento elegante e silencioso, estantes de livros jurídicos em ordem. Iara, ainda de roupa molhada, sentada no chão encostada no sofá, o celular na mão."], ["*", "Ela digita: \"Desculpa ter saído daquele jeito.\" Apaga."], ["*", "Digita: \"Eu também pensei em você esses quinze anos.\" Apaga."], ["*", "Digita: \"Isso não pode acontecer de novo.\" Olha para a mensagem por muito tempo. Apaga também."], ["*", "Ela joga o celular no sofá e encosta a cabeça para trás, de olhos fechados. Ri sozinha, um riso que mistura raiva e alegria."], ["IARA", "(para si) Quinze anos, Iara. Quinze anos e um beijo na chuva."]]}, {"s": "INT. CADEIA PÚBLICA — PARLATÓRIO — DIA", "l": [["*", "Otávio e Vinícius, separados pelo vidro. Vinícius segura um violão velho, autorizado pela direção."], ["VINÍCIUS", "Consegui. O diretor deixou. O Seu Toninho pede bolero todo dia agora."], ["OTÁVIO", "Que bom."], ["VINÍCIUS", "Você está estranho."], ["OTÁVIO", "Eu?"], ["VINÍCIUS", "Você não anotou nada desde que sentou. Você sempre anota."], ["*", "Otávio ri, pego em flagrante."], ["OTÁVIO", "Eu beijei uma pessoa."], ["VINÍCIUS", "E isso é ruim?"], ["OTÁVIO", "Ela é do outro lado."], ["VINÍCIUS", "Do outro lado de quê?"], ["OTÁVIO", "Do processo. Do seu processo."], ["*", "Vinícius arregala os olhos. Depois começa a rir, um riso de verdade, o primeiro em semanas."], ["VINÍCIUS", "A promotora? A que quer me condenar a trinta anos?"], ["OTÁVIO", "Ela não quer te condenar. Ela quer a verdade."], ["VINÍCIUS", "Cara, eu estou preso por um crime que eu não cometi e o meu advogado está apaixonado pela promotora. Se isso fosse música, ia ser um bolero."], ["*", "Ele dedilha três acordes no violão. Otávio balança a cabeça, sorrindo."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — MANHÃ", "l": [["*", "Jéssica e Dra. Beatriz diante de Helena, que assina um termo de depoimento."], ["HELENA", "Eu vou depor como testemunha. Eu estava a três metros. Ela não respondeu nada. Nenhuma palavra."], ["BEATRIZ", "Isso é importante. Ele vai dizer que ela provocou."], ["JÉSSICA", "Por que isso importa?"], ["HELENA", "Porque o artigo 140 permite ao juiz deixar de aplicar a pena em dois casos: se a vítima provocou a ofensa de forma reprovável, ou se respondeu na hora com outra ofensa. A retorsão imediata. Se você tivesse xingado ele de volta, o juiz podia perdoar os dois."], ["JÉSSICA", "E eu fiquei calada porque não queria perder o emprego."], ["HELENA", "E esse silêncio agora é a sua melhor prova."]]}, {"s": "INT. JUIZADO ESPECIAL CRIMINAL — SALA DE AUDIÊNCIA — DIA", "l": [["*", "Marta preside. Iara, como fiscal da lei, à direita. Jéssica e Dra. Beatriz de um lado. Henrique Valle, de terno impecável, sozinho do outro."], ["MARTA", "O senhor vai se defender sem advogado?"], ["HENRIQUE", "Sou advogado, Excelência. E professor há vinte anos. Posso me defender."], ["MARTA", "Pode. Não sei se deve."], ["*", "Risadas contidas no fundo da sala, onde estão Tiago e Seu Alcides."], ["HENRIQUE", "Excelência, eu me excedi. Foi uma noite ruim. Eu peço desculpas à senhorita. Eu me retrato. E, pelo artigo 143, a retratação isenta de pena."], ["BEATRIZ", "Excelência, o professor deveria rever as aulas. O artigo 143 diz: o querelado que se retrata da calúnia ou da difamação fica isento de pena. Calúnia ou difamação. A injúria ficou de fora."], ["*", "Henrique abre a boca e fecha."], ["IARA", "O Ministério Público confirma. Na injúria, a ofensa atinge a dignidade da pessoa no momento em que é dita. Não há fato para desmentir. Por isso a lei não admite retratação."], ["HENRIQUE", "Então eu alego provocação. A garçonete me olhou com desprezo, resmungou alguma coisa."], ["BEATRIZ", "Excelência, temos uma testemunha que estava a três metros."], ["*", "Helena entra e se senta no banco das testemunhas."], ["HELENA", "Ela não disse uma palavra, Excelência. Segurou a bandeja e ficou parada. Eu me lembro porque ela segurou com tanta força que os dedos ficaram brancos."], ["*", "Marta tira os óculos."], ["MARTA", "Senhor Henrique, ser cliente não dá a ninguém o direito de humilhar. Nem ser professor."], ["MARTA", "Julgo procedente a queixa. Condeno o querelado por injúria, com o aumento de um terço por ter sido praticada na presença de várias pessoas, a dois meses e vinte dias de detenção, pena substituída por multa."], ["*", "Henrique recolhe os papéis em silêncio. Na saída, passa por Jéssica. Para."], ["HENRIQUE", "A senhorita vai ser uma boa advogada."], ["JÉSSICA", "Eu já sei disso, professor."]]}, {"s": "INT. ÔNIBUS NOTURNO — NOITE", "l": [["*", "Ônibus quase vazio, onze da noite. Jéssica, de mochila, sentada perto da janela. Tiago entra no ponto seguinte, de dólmã dobrado debaixo do braço. Vê Jéssica, hesita, e se senta no banco ao lado."], ["TIAGO", "Você pega esse ônibus?"], ["JÉSSICA", "Todo dia. Há um ano."], ["TIAGO", "Eu também. Há um ano."], ["*", "Os dois se olham e riem. Um ano no mesmo ônibus sem nunca se sentarem juntos."], ["JÉSSICA", "Você sempre senta lá atrás."], ["TIAGO", "E você sempre está lendo."], ["JÉSSICA", "Código Penal. Não é uma leitura muito romântica."], ["TIAGO", "Lê um pedaço para mim."], ["JÉSSICA", "Sério?"], ["TIAGO", "Sério. Qualquer artigo."], ["*", "Jéssica abre o Código cheio de post-its. Procura. Lê baixinho."], ["JÉSSICA", "\"Artigo 5º da Constituição, inciso dez: são invioláveis a intimidade, a vida privada, a honra e a imagem das pessoas.\""], ["TIAGO", "Honra. Igual o que ele fez com você."], ["JÉSSICA", "Igual."], ["*", "O ônibus faz uma curva. O ombro dela encosta no dele. Nenhum dos dois se afasta."]]}, {"s": "INT. RESTAURANTE SABOR DA PRAÇA — COZINHA — NOITE", "l": [["*", "Fim de expediente. Jéssica tira o avental. Tiago lava as panelas. Na bancada, um pratinho com um pudim."], ["JÉSSICA", "Passei no estágio. A nova banca me escolheu."], ["TIAGO", "Eu sabia."], ["JÉSSICA", "Vou sair daqui mais cedo três dias por semana."], ["TIAGO", "Eu guardo o pudim do mesmo jeito."], ["*", "Jéssica pega o pratinho. Hesita. Coloca de volta na bancada."], ["JÉSSICA", "E se em vez do pudim você me levasse para tomar um sorvete no domingo?"], ["*", "Tiago deixa a panela cair na pia. Barulho enorme. Seu Alcides grita lá do salão: \"Quebrou alguma coisa?\""], ["TIAGO", "(para Jéssica) Domingo. Sim. Domingo."]]}, {"s": "INT. CLUBE ATLÉTICO AURORA — SALA DE AULA DE DANÇA — TARDE (QUINTA-FEIRA, SEMANAS DEPOIS)", "l": [["*", "Sala com espelhos e barra de balé. Marisa, de vestido vermelho e sapato de dança, conduz uma aula para seis casais de idosos. Uma vitrola toca bolero."], ["MARISA", "Dois para lá, dois para cá. Seu Ernesto, o senhor não está carregando um saco de cimento. Está carregando uma dama."], ["*", "Os alunos riem. Uma aluna, DONA CELESTE, 80, de lenço na cabeça, se aproxima de Marisa no intervalo."], ["CELESTE", "Marisa, querida. Eu soube do Jairo. Que tragédia."], ["*", "Marisa fecha os olhos. Uma lágrima desce, perfeita."], ["MARISA", "Ele era o meu melhor aluno, Dona Celeste. Chegou aqui sem saber dar um passo. Em três meses, dançava como um galã."], ["CELESTE", "Vocês estavam namorando, não estavam? A turma toda comentava."], ["MARISA", "A gente se fazia companhia. Na nossa idade, companhia é tudo."], ["CELESTE", "E dizem que foi o sobrinho."], ["MARISA", "Dizem. Pobre Jairo. Tão bom com todo mundo. Até com quem não merecia."], ["*", "Marisa enxuga a lágrima com a ponta do lenço de seda e bate palmas."], ["MARISA", "Vamos, turma! Bolero não espera ninguém."], ["*", "Ela volta para o centro da sala sorrindo. A câmera fica um instante no espelho, onde o reflexo dela não sorri."]]}, {"s": "INT. APARTAMENTO DE HELENA — QUARTO — NOITE (QUINTA-FEIRA, SEMANAS DEPOIS)", "l": [["*", "Helena diante do espelho do guarda-roupa, de vestido escuro, sem blazer, desconfortável. Pedro, encostado na porta, come uma maçã."], ["PEDRO", "Você vai a um baile de bolero?"], ["HELENA", "A trabalho."], ["PEDRO", "De vestido?"], ["HELENA", "Disfarce."], ["PEDRO", "Mãe, você parece uma delegada de vestido."], ["HELENA", "E como é uma delegada de vestido?"], ["PEDRO", "Assim. Com essa cara de quem vai prender o garçom."], ["*", "Helena tenta sorrir para o espelho. Não consegue. Pedro larga a maçã e estende a mão."], ["PEDRO", "Vem. O vô me ensinou bolero quando eu tinha dez anos. Dois para lá, dois para cá."], ["HELENA", "Seu avô dançava?"], ["PEDRO", "Com a vovó, toda sexta, na cozinha. Você nunca viu porque estava sempre trabalhando."], ["*", "Helena para. Depois pega a mão do filho. Os dois dançam desajeitados no quarto apertado, Pedro contando os passos em voz alta."], ["PEDRO", "Viu? Você conduz demais."], ["HELENA", "Todo mundo me diz isso."]]}, {"s": "INT. CARRO DE CAÍQUE — EM FRENTE AO CLUBE ATLÉTICO AURORA — NOITE", "l": [["*", "Música de bolero escapa pelas janelas abertas do clube. Caíque, ao volante, entrega a Helena um pequeno fone sem fio."], ["CAÍQUE", "Se precisar, fala \"que calor\". Eu entro em trinta segundos."], ["HELENA", "Eu vou dançar, Caíque, não invadir um cativeiro."], ["CAÍQUE", "A senhora vai dançar com uma suspeita de homicídio."], ["HELENA", "Que ainda não sabe que é suspeita."], ["CAÍQUE", "Ela comprou um chip para ameaçar a senhora. Ela sabe."], ["*", "Helena olha para o clube iluminado."], ["HELENA", "Então vamos ver quem conduz."], ["*", "Ela desce do carro, ajeita o vestido e entra. Seu Alcides a espera na porta, de gravata-borboleta, oferecendo o braço."]]}, {"s": "INT. CLUBE ATLÉTICO AURORA — SALÃO DE BAILE — NOITE (QUINTA-FEIRA, SEMANAS DEPOIS)", "l": [["*", "Salão antigo de piso de madeira, lustres de cristal, uma banda ao vivo toca bolero. Casais de cabelos brancos dançam com elegância. Seu Alcides conduz Helena na pista."], ["ALCIDES", "Dois para lá. Dois para cá. A senhora conduz demais, doutora. Aqui quem conduz sou eu."], ["HELENA", "Força do hábito."], ["*", "No centro do salão, MARISA VILELA, 58, vestido verde-esmeralda, o lenço de seda de flores vermelhas no pescoço, ensina um casal de alunos. Ela olha na direção de Helena. Sorri. Vem até eles."], ["MARISA", "Seu Alcides, me empresta a sua dama?"], ["*", "Alcides se afasta, sem graça. Marisa pega a mão de Helena e a conduz como uma profissional."], ["MARISA", "Delegada Helena Rocha. Eu vi a senhora no enterro do Jairo."], ["HELENA", "E eu vi a senhora. A senhora foi embora muito rápido."], ["MARISA", "Eu não gosto de despedidas. Prefiro lembrar das pessoas dançando."], ["HELENA", "A senhora e o Seu Jairo dançavam aqui."], ["MARISA", "Toda quinta. Ele era tão doce. Tímido como um menino. E tinha manias. O café às seis e meia. Duas colheres de açúcar. Sempre do pote azul da falecida esposa."], ["*", "Helena erra o passo."], ["HELENA", "O pote azul."], ["MARISA", "Ele me contava tudo, delegada."], ["HELENA", "O pote nunca apareceu no jornal, Dona Marisa. Só quem esteve naquela cozinha sabe dele."], ["*", "Marisa não perde o ritmo. Gira Helena com leveza."], ["MARISA", "Eu já tomei muito café naquela cozinha. Ele me fazia café toda sexta de manhã, depois do baile. Não é crime tomar café com um homem viúvo, é?"], ["HELENA", "Não. E herdar uma casa também não."], ["MARISA", "O testamento? Ele quis fazer. Eu disse que não precisava. Eu nunca pedi nada a ele."], ["HELENA", "Ele ia rasgar o testamento, Dona Marisa. Na quinta-feira."], ["*", "Pela primeira vez, Marisa hesita. Um quarto de segundo. Depois sorri."], ["MARISA", "A senhora dança bem, delegada. Mas está pisando no meu pé."], ["*", "A música termina. Marisa solta a mão de Helena, faz uma pequena reverência e volta para os alunos."]]}, {"s": "EXT. CLUBE ATLÉTICO AURORA — SAÍDA — NOITE", "l": [["*", "Helena e Seu Alcides saem do baile. Helena entra no carro. Caíque está no volante."], ["CAÍQUE", "E aí?"], ["HELENA", "Ela sabia do pote azul."], ["CAÍQUE", "E isso é prova?"], ["HELENA", "Isso é um fio. Ela diz que tomava café naquela cozinha. Pode ser verdade. Mas ela hesitou quando eu falei do testamento rasgado. Ela não sabia que a gente sabia."], ["CAÍQUE", "E agora sabe."], ["*", "O carro arranca."]]}, {"s": "INT. CLUBE ATLÉTICO AURORA — VESTIÁRIO DOS PROFESSORES — NOITE", "l": [["*", "Marisa sozinha diante do espelho. Tira o lenço de seda devagar e o dobra com cuidado. Abre a bolsa e tira um molho com uma única chave."], ["*", "No chaveiro, uma pequena castanhola de madeira. Idêntica à do molho pendurado no segundo gancho da casa de Jairo."], ["*", "Marisa olha a chave por um longo tempo. Depois a guarda no fundo da bolsa e fecha o zíper."]]}, {"s": "TELA PRETA", "l": [["VOZ", "Na injúria não há fato para desmentir. A ofensa acontece no instante em que é dita. Por isso, pedir desculpas não apaga o crime. No próximo episódio: um idoso trancado num quarto e um amor de juventude que bate na porta. Artigo 148."]]}, {"s": "O VEREDITO — CARDS NARRADOS", "l": [["*", "Tela preta. Os cards do Veredito surgem um a um."], ["VOZ", "Artigo 140 do Código Penal: injuriar alguém, ofendendo-lhe a dignidade ou o decoro. A pena é de detenção de um a seis meses, ou multa."], ["VOZ", "Na injúria não se atribui fato nenhum: é a ofensa em si, o xingamento. Basta que a vítima tome conhecimento dela. Se for cometida na presença de várias pessoas, a pena aumenta de um terço."], ["VOZ", "Se a injúria usa violência ou vias de fato que, pela natureza ou pelo meio, são aviltantes, é a injúria real, com pena de três meses a um ano e multa, além da pena da violência. Se usa elementos de religião ou da condição de pessoa idosa ou com deficiência, a pena é de reclusão de um a três anos e multa."], ["VOZ", "O juiz pode deixar de aplicar a pena se a vítima provocou a ofensa de forma reprovável, ou se respondeu na hora com outra ofensa. Ao contrário da calúnia e da difamação, a retratação não isenta de pena na injúria."], ["VOZ", "Não confunda: desde 2023, a injúria racial está na Lei do Racismo, com pena de reclusão de dois a cinco anos, e o processo não depende da vítima."]]}]}, "148": {"dur": 21, "logline": "Às onze da noite, Dona Zilda ouve pela parede batidas que ela não escutava há quase sessenta anos: o código secreto do primeiro namorado, Seu Benedito, que o filho diz estar viajando. Enquanto isso, a principal suspeita do caso Jairo compra uma passagem para a fronteira e a promotora Iara toma uma decisão que muda sua vida.", "twist": "Privar alguém da liberdade é sequestro ou cárcere privado. Quando a vítima é pai do autor ou tem mais de 60 anos, ou fica presa por mais de 15 dias, a pena sobe de 1 a 3 para 2 a 5 anos. É um crime permanente: enquanto a vítima está trancada, o crime continua acontecendo. Por isso a polícia pode entrar na casa a qualquer hora, mesmo de noite e sem mandado, porque há flagrante. E o processo não depende do perdão da vítima.", "guests": [{"n": "Benedito Souza", "r": "Vítima, ferroviário aposentado, 81 anos", "d": "Gentil, bem-humorado, ama o filho apesar de tudo"}, {"n": "Ronaldo Souza", "r": "Filho e autor, 50 anos", "d": "Envergonhado, explosivo, viciado em apostas online"}, {"n": "Dona Zilda Martins", "r": "Vizinha e primeiro amor de Benedito, 77 anos", "d": "Valente, teimosa, romântica escondida"}, {"n": "Marisa Vilela", "r": "Suspeita do caso Jairo", "d": "Professora de dança de salão, encantadora em público e calculista em particular. Sempre com um lenço de seda."}, {"n": "Dr. Saraiva", "r": "Promotor que assume o caso Jairo, 50 anos", "d": "Promotor correto e econômico nas palavras. Assume o caso Jairo quando Iara se declara suspeita."}, {"n": "Dra. Flávia", "r": "Geriatra, 45 anos", "d": "Gentil e objetiva"}, {"n": "Márcia", "r": "Assistente social, 38 anos", "d": "Acolhedora e prática"}, {"n": "Coordenador do grupo", "r": "Jogadores Anônimos, 60 anos", "d": "Sereno"}], "scenes": [{"s": "ANTERIORMENTE", "l": [["*", "Imagens rápidas dos episódios anteriores."], ["VOZ", "Anteriormente, na JURISPLAY. Num baile de bolero, Marisa Vilela deixou escapar um detalhe que só quem esteve na cozinha de Seu Jairo conhecia: o pote azul de açúcar. Na chuva, em frente ao fórum, a promotora Iara e o defensor Otávio se beijaram, e ela disse que aquilo não podia acontecer enquanto estivessem no mesmo processo. E, sozinha no vestiário, Marisa guardou uma chave com um chaveiro de castanhola, igual ao da casa de Jairo."], ["*", "Corte para a cena de abertura."]]}, {"s": "INT. CASA DE DONA ZILDA — COZINHA — NOITE", "l": [["*", "Onze horas da noite. Cozinha antiga, rádio desligado, uma xícara de chá esfriando. DONA ZILDA, 77, coque com grampos de tartaruga, faz palavras cruzadas."], ["*", "Um som abafado vem da parede que divide a casa dela da casa vizinha. Três batidas. Uma pausa. Três batidas."], ["*", "Zilda ergue a cabeça. A caneta cai no chão."], ["*", "FLASHBACK, tons de sépia: 1968. A mesma parede, sem reboco. De um lado, ZILDA JOVEM, 19, de tranças, encosta a orelha nos tijolos. Do outro lado, BENEDITO JOVEM, 23, bate três vezes, pausa, três vezes. Ela ri e bate de volta."], ["*", "VOLTA AO PRESENTE. Zilda se levanta devagar, encosta a orelha na parede."], ["*", "Três batidas. Pausa. Três batidas. E depois, muito fraca, uma voz:"], ["BENEDITO", "(abafado) Zilda..."], ["*", "Zilda tapa a boca com a mão. Bate três vezes na parede. Do outro lado, as batidas param."], ["*", "Ela pega o telefone fixo com a mão tremendo."], ["ZILDA", "Alô, polícia? O meu vizinho... O filho dele diz que ele viajou. Mas ele está aí dentro. Ele está me chamando pela parede."], ["*", "Corte seco para preto."]]}, {"s": "VINHETA", "l": [["*", "O triângulo laranja da JURISPLAY. ART. 148. \"O Quarto dos Fundos\"."]]}, {"s": "EXT. RUA DAS MANGUEIRAS — CASA DE BENEDITO — NOITE", "l": [["*", "Onze e quarenta. Uma viatura para. Helena e Caíque descem. Dona Zilda espera no portão de casaquinho de tricô."], ["ZILDA", "Três semanas, doutora. Faz três semanas que eu não vejo o Benedito. O Ronaldo diz que ele foi para a casa da irmã em Minas. A irmã dele morreu em 2015."], ["HELENA", "E as batidas?"], ["ZILDA", "Era o nosso código. Em 1968, antes de ele ir trabalhar na ferrovia e eu casar com outro. Ninguém mais no mundo sabe disso."], ["*", "Helena bate na porta da casa vizinha. Demora. RONALDO, 50, camiseta de time desbotada, abre só uma fresta."], ["RONALDO", "Que é isso a essa hora?"], ["HELENA", "Polícia Civil. Viemos falar com o Seu Benedito."], ["RONALDO", "Meu pai está viajando."], ["HELENA", "Para onde?"], ["RONALDO", "Para a casa da minha tia."], ["ZILDA", "(do portão) A tua tia morreu, Ronaldo! Eu fui no enterro!"], ["*", "Ronaldo tenta fechar a porta. Caíque coloca o pé."], ["*", "De dentro da casa, ao fundo, três batidas fracas."], ["*", "Helena e Caíque se olham."], ["RONALDO", "A senhora não pode entrar. São quase meia-noite. Cadê o mandado?"], ["HELENA", "Seu Ronaldo, a casa é inviolável. De noite, sem mandado, ninguém entra. A não ser em caso de flagrante."], ["RONALDO", "E qual é o flagrante?"], ["HELENA", "Se tiver alguém trancado aí dentro contra a vontade, o crime está acontecendo agora. Enquanto a pessoa estiver presa, o crime não para. É flagrante a cada minuto."], ["*", "Três batidas outra vez, mais altas. Helena empurra a porta. Ronaldo recua."], ["HELENA", "Caíque, vamos."]]}, {"s": "INT. CASA DE BENEDITO — CORREDOR E QUARTO DOS FUNDOS — NOITE", "l": [["*", "Corredor escuro, cheiro de mofo. No fim, uma porta de madeira com um cadeado novo e reluzente por fora."], ["CAÍQUE", "Cadeado por fora."], ["HELENA", "Seu Ronaldo, a chave."], ["*", "Ronaldo está parado no início do corredor. Não se mexe. Depois tira a chave do bolso da bermuda e joga no chão."], ["*", "Caíque abre o cadeado. A porta range."], ["*", "Quarto pequeno, janela pregada com tábuas. Um colchão de solteiro, um balde, uma garrafa d'água pela metade, pratos de plástico empilhados. Sentado na cama, de pijama listrado puído, magro demais, BENEDITO, 81."], ["*", "Ele levanta os olhos. Pisca contra a luz da lanterna."], ["BENEDITO", "É a Zilda?"], ["*", "Zilda aparece no batente, atrás de Helena. Quando vê Benedito, perde a força nas pernas. Caíque a ampara."], ["ZILDA", "Benedito."], ["BENEDITO", "Você ainda lembrava do código."], ["ZILDA", "Quase sessenta anos, seu velho bobo. Eu lembro de tudo."], ["*", "Ela atravessa o quarto e o abraça. Benedito chora no ombro dela, um choro silencioso e envergonhado."], ["*", "No corredor, Ronaldo escorrega pela parede e se senta no chão, com o rosto nas mãos."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE INTERROGATÓRIO — MADRUGADA", "l": [["*", "Ronaldo na mesa de metal. Otávio entra com a mochila, com cara de quem foi acordado."], ["OTÁVIO", "Otávio Lins, Defensoria. Ronaldo, você tem o direito de ficar calado."], ["RONALDO", "Eu não quero ficar calado. Eu quero que alguém entenda."], ["*", "Helena se senta."], ["HELENA", "Então me faça entender."], ["RONALDO", "Eu perdi o emprego há um ano. Comecei a apostar no celular. Primeiro dez reais. Depois cem. Depois o carro. Depois o cartão do meu pai. A aposentadoria dele. Tudo."], ["HELENA", "E ele descobriu."], ["RONALDO", "Ele disse que ia no banco cancelar o cartão. Que ia me denunciar. Eu entrei em pânico. Tranquei a porta do quarto. Era pra ser uma noite só. Pra ele se acalmar."], ["HELENA", "Foram vinte e dois dias."], ["RONALDO", "Cada dia que passava ficava mais difícil abrir aquela porta."], ["*", "Otávio coloca a mão no ombro dele."], ["OTÁVIO", "Ele precisa de tratamento, delegada. Vício em apostas é doença."], ["HELENA", "Pode ser doença, doutor. Mas o que ele fez com o pai é crime."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — MADRUGADA", "l": [["*", "Caíque traz café. Helena preenche o auto de prisão em flagrante."], ["CAÍQUE", "Sequestro ou cárcere privado. Artigo 148."], ["HELENA", "\"Privar alguém de sua liberdade, mediante sequestro ou cárcere privado.\" Pena simples de um a três anos de reclusão. Mas olha o parágrafo primeiro."], ["CAÍQUE", "Inciso um: se a vítima é ascendente do agente. O pai. E se a vítima é maior de sessenta anos."], ["HELENA", "As duas coisas. E o inciso três: se a privação dura mais de quinze dias. Foram vinte e dois. Pena de dois a cinco anos."], ["CAÍQUE", "E se o Seu Benedito tivesse sofrido muito? Física ou psicologicamente?"], ["HELENA", "Parágrafo segundo: grave sofrimento físico ou moral. Dois a oito anos. O laudo vai dizer."], ["CAÍQUE", "E o dinheiro da aposentadoria?"], ["HELENA", "Estatuto da Pessoa Idosa, artigo 102. Apropriar-se dos rendimentos do idoso, dando a eles outro destino. Reclusão de um a quatro anos. Outro crime, somado."], ["*", "Caíque olha pela janela da sala. Na recepção, Zilda e Benedito estão sentados lado a lado, de mãos dadas, esperando a ambulância."], ["CAÍQUE", "Ela não soltou a mão dele a noite toda."]]}, {"s": "EXT. QUERMESSE DA PARÓQUIA — FLASHBACK — NOITE (1968)", "l": [["*", "Tons de sépia. Bandeirinhas coloridas, barracas de pescaria, uma sanfona tocando. BENEDITO JOVEM, 23, de camisa branca engomada, e ZILDA JOVEM, 19, de vestido rodado e tranças, dançam um bolero desajeitado no meio do terreiro."], ["ZILDA JOVEM", "Você pisou no meu pé três vezes."], ["BENEDITO JOVEM", "É que eu estou nervoso."], ["ZILDA JOVEM", "Por quê?"], ["BENEDITO JOVEM", "Porque segunda-feira eu vou embora. Passei no concurso da ferrovia. Vou trabalhar no interior. Três anos, no mínimo."], ["*", "Zilda para de dançar."], ["ZILDA JOVEM", "E você me conta isso dançando?"], ["BENEDITO JOVEM", "Eu ia te pedir para esperar."], ["*", "Silêncio. A sanfona continua."], ["ZILDA JOVEM", "Três anos é muito tempo, Benedito."], ["BENEDITO JOVEM", "Eu sei."], ["ZILDA JOVEM", "Então não pede. Porque eu vou dizer que espero. E eu não sei se consigo."], ["*", "Ele segura a mão dela. Os dois voltam a dançar, mais devagar, sem falar mais nada."], ["ZILDA", "(voz, sobre a imagem) Eu não consegui. Casei dois anos depois. Ele também. E por mais de cinquenta anos, a gente morou parede com parede, cada um na sua vida."]]}, {"s": "INT. HOSPITAL MUNICIPAL — ENFERMARIA GERIÁTRICA — DIA", "l": [["*", "Benedito, de banho tomado e barba feita, sentado na cama com soro no braço. A geriatra, DRA. FLÁVIA, 45, examina os olhos dele. Uma assistente social, MÁRCIA, 38, segura uma prancheta. Zilda sentada na cadeira ao lado, com um pote de sopa no colo."], ["FLÁVIA", "Desidratação, perda de peso, uma infecção leve na pele por causa do colchão. Nada que a gente não trate. O senhor é forte, Seu Benedito."], ["BENEDITO", "Quarenta anos carregando dormente na ferrovia, doutora. A gente fica duro."], ["MÁRCIA", "Seu Benedito, eu preciso fazer algumas perguntas. O senhor tem para onde ir quando sair daqui? Algum parente?"], ["BENEDITO", "Só o Ronaldo."], ["MÁRCIA", "E o senhor quer voltar a morar com ele?"], ["*", "Benedito olha para as próprias mãos. Demora."], ["BENEDITO", "Eu quero que ele fique bom. Mas eu não quero mais aquela porta."], ["ZILDA", "Ele vai para a minha casa."], ["MÁRCIA", "A senhora é parente?"], ["ZILDA", "Sou vizinha há setenta anos. É quase a mesma coisa."], ["MÁRCIA", "E a aposentadoria dele? O cartão estava com o filho."], ["FLÁVIA", "Isso já é com a polícia e o banco. A Márcia vai ajudar o senhor a pedir um novo cartão e a cadastrar o senhor no programa de proteção à pessoa idosa."], ["*", "Zilda abre o pote de sopa e coloca a colher na mão de Benedito."], ["ZILDA", "Agora come. Você está com cara de cabo de vassoura."], ["BENEDITO", "E você está mandona igual era em 1968."], ["ZILDA", "Pior. Eu treinei a vida inteira."]]}, {"s": "EXT. GARAGEM DE CARROS SEMINOVOS — DIA (VÉSPERA)", "l": [["*", "Uma revenda de carros usados, bandeirinhas coloridas, um vendedor de gravata. Do outro lado da rua, Caíque, dentro do carro descaracterizado, de boné e óculos escuros, fotografa com uma teleobjetiva."], ["*", "Marisa, de óculos escuros e lenço de seda, entrega a chave de um sedã vermelho ao vendedor. Recebe um envelope grosso. Conta as notas sem pressa."], ["CAÍQUE", "(ao telefone) Doutora, ela está vendendo o carro. À vista. Em dinheiro vivo."], ["HELENA", "(telefone) Quanto?"], ["CAÍQUE", "Pelo tamanho do envelope, bem abaixo do valor de mercado. Ela tem pressa."], ["*", "Marisa sai da revenda e caminha até um ponto de táxi. No caminho, para em frente a uma agência de turismo. Olha os cartazes na vitrine por um longo tempo. Entra."], ["CAÍQUE", "Ela entrou numa agência de viagens."], ["HELENA", "(telefone) Não perca ela de vista. E não deixe ela te ver."], ["*", "Caíque abaixa no banco quando Marisa sai da agência, olhando para os dois lados da rua. Ela entra num táxi. Caíque espera dois segundos e liga o carro."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE INVESTIGAÇÃO — MANHÃ", "l": [["*", "Caíque, olheiras de quem não dormiu, chama Helena até o monitor."], ["CAÍQUE", "Doutora, enquanto a gente estava no quarto dos fundos, a Marisa Vilela estava ocupada. Ontem ela vendeu o carro. À vista, abaixo da tabela. E hoje cedo comprou uma passagem de ônibus. Só de ida."], ["HELENA", "Para onde?"], ["CAÍQUE", "Foz do Iguaçu. Fronteira com o Paraguai e a Argentina. Sábado, às seis da manhã."], ["HELENA", "Amanhã de manhã."], ["CAÍQUE", "A senhora vai pedir a prisão?"], ["HELENA", "Vou pedir a prisão e uma busca na casa dela. Eu preciso do veneno, Caíque. Do resto do pesticida, da terceira chave, de alguma coisa que ligue as mãos dela ao açucareiro."], ["CAÍQUE", "Com quem a senhora fala? A doutora Iara?"], ["*", "Helena demora a responder."], ["HELENA", "Com quem estiver no caso."]]}, {"s": "INT. PROMOTORIA DE JUSTIÇA — GABINETE DE IARA — DIA", "l": [["*", "Iara sozinha no gabinete, diante de um documento na tela do computador. No topo: \"Declaração de suspeição por motivo de foro íntimo — Processo Vinícius Mendes\". O cursor pisca sobre \"Assinar\"."], ["*", "Batem na porta. Helena entra."], ["HELENA", "A Marisa Vilela comprou uma passagem para a fronteira. Sábado, às seis. Eu vou representar hoje pela prisão temporária e pela busca na casa dela. Eu queria a senhora do meu lado."], ["IARA", "Delegada, eu não posso mais estar nesse caso."], ["HELENA", "Por quê?"], ["*", "Iara vira o monitor para Helena. Helena lê. Não pergunta mais nada. Ela entende."], ["IARA", "Quando a gente tem um envolvimento pessoal com alguém do processo, a imparcialidade fica em dúvida. A lei permite que o promotor, como o juiz, se declare suspeito por motivo íntimo, sem precisar explicar. É o que eu estou fazendo."], ["HELENA", "Justo agora."], ["IARA", "Justo agora que eu talvez esteja errada sobre o Vinícius. Se eu pedir a prisão da Marisa, vão dizer que foi para ajudar o defensor do Vinícius. Se eu não pedir, vão dizer que foi orgulho. Em qualquer caso, quem perde é a verdade."], ["*", "Iara clica em \"Assinar\"."], ["IARA", "O doutor Saraiva assume a partir de agora. Ele já está com o processo. E é bom."], ["HELENA", "A senhora fez a coisa certa."], ["IARA", "Eu sei. É por isso que dói."]]}, {"s": "INT. FÓRUM — AUDIÊNCIA DE CUSTÓDIA — DIA", "l": [["*", "Sala pequena. Marta preside. Ronaldo, algemado, ao lado de Otávio. Um promotor de plantão do outro lado. No banco do público, Benedito, de camisa de botão e boné da ferrovia, com Zilda ao lado."], ["MARTA", "Senhor Ronaldo, esta é a audiência de custódia. Toda pessoa presa em flagrante deve ser levada a um juiz em até vinte e quatro horas, para que eu verifique se a prisão foi legal e decida se o senhor responde preso ou solto."], ["MARTA", "A entrada na casa foi feita à noite, sem mandado. Doutor Otávio, alguma impugnação?"], ["OTÁVIO", "Excelência, a defesa reconhece que havia flagrante de crime permanente e fundadas razões, as batidas, o relato da vizinha, a mentira sobre a tia. A entrada foi legal. O que eu peço é outra coisa. O Ronaldo não tem antecedentes e precisa de tratamento para o vício em apostas. Peço liberdade provisória com medidas cautelares."], ["MARTA", "Seu Benedito, o senhor quer dizer alguma coisa?"], ["*", "Benedito se levanta com dificuldade. Zilda segura o braço dele."], ["BENEDITO", "Excelência, ele é o meu filho. Eu troquei a fralda dele. Eu não quero ele preso. Eu perdoo."], ["*", "Ronaldo começa a chorar, de cabeça baixa."], ["MARTA", "Seu Benedito, o senhor pode perdoar o seu filho. É um direito do seu coração. Mas o processo não depende disso. Neste crime, quem decide se haverá processo é o Estado, não a vítima. A lei não pode deixar de proteger o senhor, nem mesmo de quem o senhor ama."], ["MARTA", "Homologo o flagrante. Concedo liberdade provisória com as seguintes medidas: afastamento da casa da vítima, proibição de contato com ela, monitoramento eletrônico e comparecimento mensal em juízo. Qualquer descumprimento, e a prisão preventiva será decretada."], ["*", "Benedito se senta, exausto. Zilda segura a mão dele."], ["ZILDA", "(baixinho) Você fica lá em casa até se recuperar."], ["BENEDITO", "O que os vizinhos vão dizer?"], ["ZILDA", "Que demorou quase sessenta anos."]]}, {"s": "INT. SALÃO PAROQUIAL — GRUPO DE APOIO — NOITE", "l": [["*", "Cadeiras em círculo, café em copos descartáveis. Uma faixa simples: \"Jogadores Anônimos — Só por hoje\". Ronaldo, com a tornozeleira eletrônica recém-colocada aparecendo por baixo da calça, sentado entre desconhecidos. Um COORDENADOR, 60, de voz calma, olha para ele."], ["COORDENADOR", "Você quer falar hoje?"], ["*", "Ronaldo demora. Depois fala olhando para o chão."], ["RONALDO", "Meu nome é Ronaldo. Eu... apostei tudo o que eu tinha. Depois tudo o que o meu pai tinha. E quando ele quis me impedir, eu tranquei ele num quarto. Por vinte e dois dias."], ["*", "Ninguém no círculo desvia o olhar. Ninguém julga em voz alta."], ["RONALDO", "Eu tenho uma tornozeleira. Não posso chegar perto dele. A juíza disse que se eu descumprir, vou preso. E ela tem razão."], ["COORDENADOR", "E o que você quer, Ronaldo?"], ["RONALDO", "Eu quero um dia poder bater na porta da casa da vizinha, onde ele está morando agora, e ele querer abrir."], ["*", "O coordenador assente."], ["COORDENADOR", "Só por hoje, Ronaldo."], ["RONALDO", "Só por hoje."]]}, {"s": "INT. CAFÉ DO FÓRUM — FIM DE TARDE", "l": [["*", "Otávio no balcão, cansado da madrugada. Iara chega e se encosta ao lado dele."], ["IARA", "Um café pequeno. Sem açúcar."], ["OTÁVIO", "Ainda sem açúcar."], ["IARA", "Eu me declarei suspeita no caso Mendes, Otávio. Hoje de manhã."], ["*", "Otávio larga a caneca."], ["OTÁVIO", "Você fez isso por minha causa."], ["IARA", "Eu fiz isso pela minha causa. Pelo processo. Pelo Vinícius. E, sim, por sua causa."], ["OTÁVIO", "Agora você não está mais no meu processo."], ["IARA", "Não estou. E também não vou estar lá quando você ganhar."], ["OTÁVIO", "Se eu ganhar."], ["IARA", "Você vai ganhar. A delegada está atrás da pessoa certa. Eu sei disso há duas semanas. Só não podia dizer."], ["*", "Os dois ficam em silêncio. O barista coloca o café dela no balcão. Otávio empurra a xícara para ela com dois dedos, como sempre."], ["OTÁVIO", "Quando isso tudo acabar, eu te levo para jantar."], ["IARA", "No Sabor da Praça."], ["OTÁVIO", "Numa sexta-feira."], ["IARA", "Numa sexta-feira."]]}, {"s": "INT. CADEIA PÚBLICA — PARLATÓRIO — FIM DE TARDE", "l": [["*", "Vinícius do outro lado do vidro, o violão no colo. Otávio senta, cansado da madrugada."], ["OTÁVIO", "A promotora Iara saiu do seu caso."], ["VINÍCIUS", "Saiu? Por quê?"], ["OTÁVIO", "Ela se declarou suspeita. Por motivo de foro íntimo."], ["*", "Vinícius demora um segundo para entender. Depois arregala os olhos."], ["VINÍCIUS", "Por sua causa."], ["OTÁVIO", "Por causa do processo. Para ninguém poder dizer que a decisão dela foi torta, para um lado ou para o outro."], ["VINÍCIUS", "E isso é bom ou ruim para mim?"], ["OTÁVIO", "Para você, não muda o principal. Um novo promotor assume, o doutor Saraiva. E a delegada vai pedir hoje uma busca na casa da Marisa Vilela."], ["*", "Vinícius aperta o braço do violão."], ["VINÍCIUS", "Se acharem alguma coisa..."], ["OTÁVIO", "Se acharem alguma coisa, eu peço a sua liberdade no mesmo dia."], ["VINÍCIUS", "E se não acharem?"], ["OTÁVIO", "Aí a gente continua. Eu não vou a lugar nenhum."], ["*", "Vinícius dedilha um acorde, nervoso."], ["VINÍCIUS", "Ela abriu mão de um caso grande por você, cara. Isso é um bolero inteiro."], ["OTÁVIO", "Toca alguma coisa, vai. Eu preciso ouvir outra coisa que não seja o Código."], ["*", "Vinícius toca. Otávio fecha os olhos do outro lado do vidro."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — NOITE", "l": [["*", "Oito da noite. Helena digita a representação no computador. A mesa está coberta de papéis: o laudo do açucareiro, a foto do testamento, a imagem do lenço na câmera da banca, o relatório do chip. Caíque e Lúcia entram com café e um pacote de biscoitos."], ["LÚCIA", "Trouxe o laudo do sapato do Seu Jairo, que a senhora pediu. Sola de couro de dança. Tem restos de cera de piso de madeira. O mesmo tipo usado no salão do Clube Atlético."], ["HELENA", "Mais um fio."], ["CAÍQUE", "Doutora, a senhora acha que é suficiente para a juíza autorizar a busca?"], ["HELENA", "Para a busca, a lei exige fundadas razões. Para a prisão temporária de crime hediondo, indícios de autoria. Eu tenho uma mulher que tinha motivo, que tinha a chave, que sabia do pote, que me ameaçou e que está fugindo. Separado, cada fio é fraco. Junto..."], ["LÚCIA", "Junto vira corda."], ["*", "Helena olha para Lúcia, surpresa."], ["HELENA", "Isso foi bonito, Lúcia."], ["LÚCIA", "Eu leio muito. Não conte para o Caíque."], ["CAÍQUE", "Eu estou bem aqui."], ["LÚCIA", "Eu sei."], ["*", "Helena volta a digitar. No fim do documento, escreve: \"Requer-se, com urgência, a expedição de mandado de busca e apreensão domiciliar e a decretação da prisão temporária de Marisa Vilela.\""], ["HELENA", "E o que eu não tenho é a prova que fecha tudo. O resto do veneno. Se ainda existir."]]}, {"s": "INT. FÓRUM — GABINETE DA JUÍZA MARTA — NOITE", "l": [["*", "Dez da noite de sexta-feira. Marta, de casaco, lê a representação de Helena. Helena e Caíque de pé diante da mesa. Ao lado, o promotor DR. SARAIVA, 50, terno escuro, assina um parecer."], ["SARAIVA", "O Ministério Público é favorável, Excelência. Há indícios fortes: o testamento, a nota sobre rasgá-lo, o chip, o lenço, o conhecimento do açucareiro, a venda do carro e a passagem para a fronteira."], ["*", "Marta assina."], ["MARTA", "Defiro a busca e apreensão domiciliar na Rua das Camélias, número 90. E decreto a prisão temporária de Marisa Vilela por trinta dias, por se tratar de investigação de crime hediondo."], ["HELENA", "Obrigada, Excelência."], ["MARTA", "Delegada. A senhora sabe a que horas pode cumprir este mandado."], ["HELENA", "Sei."], ["MARTA", "Diga em voz alta. Para o investigador ouvir."], ["HELENA", "Busca domiciliar só durante o dia. A Constituição diz \"durante o dia\". A Lei de Abuso de Autoridade diz o que é dia: entre as cinco da manhã e as nove da noite. Antes das cinco, é crime de quem entra."], ["MARTA", "E o ônibus dela sai às seis."], ["CAÍQUE", "A rodoviária fica a vinte minutos da casa dela. Ela vai sair de casa antes das cinco e meia."], ["MARTA", "Então a senhora tem meia hora, delegada. Use bem."]]}, {"s": "EXT. CASA DE MARISA — QUINTAL — NOITE (SEXTA-FEIRA)", "l": [["*", "Onze da noite. O quintal de Marisa, cheio de rosas vermelhas iluminadas pela luz da cozinha. Marisa, de roupão de seda, rega as rosas com um regador de metal, devagar, uma por uma."], ["*", "Ela para diante do pequeno depósito de madeira no fundo do quintal. Olha para a porta fechada por um longo momento. Dá um passo na direção dela. Para."], ["*", "Volta para dentro de casa. A luz da cozinha se apaga. O depósito fica no escuro."]]}, {"s": "EXT. RUA DAS CAMÉLIAS — DENTRO DO CARRO DA POLÍCIA — MADRUGADA", "l": [["*", "Quatro e trinta e dois da manhã. Rua silenciosa. O carro descaracterizado parado a cinquenta metros de uma casa amarela de janelas brancas: número 90. Uma luz acesa no andar de cima."], ["*", "Helena no banco do passageiro. Caíque ao volante. Uma garrafa térmica de café entre os dois."], ["CAÍQUE", "A luz acendeu às quatro e dez."], ["HELENA", "Ela está arrumando a mala."], ["*", "Silêncio. O relógio do painel: 4:41."], ["CAÍQUE", "E se ela sair às quatro e cinquenta?"], ["HELENA", "Fora de casa, na rua, é diferente. A temporária me autoriza a prender na rua a qualquer hora. O que eu não posso é entrar na casa antes das cinco."], ["CAÍQUE", "E se ela sair sem nada, com a mala, e deixar o veneno lá dentro?"], ["HELENA", "Então eu entro às cinco e um."], ["*", "O relógio: 4:52. A luz do andar de cima se apaga. A luz do andar de baixo acende."], ["*", "Helena coloca a mão no rádio. Caíque segura a maçaneta da porta. Os dois olham para o relógio do painel."], ["*", "4:57."], ["*", "Corte seco para preto."]]}, {"s": "TELA PRETA", "l": [["VOZ", "Enquanto a porta estiver trancada, o crime continua acontecendo. Por isso, para salvar alguém, a lei abre qualquer porta. Para procurar uma prova, só depois das cinco. No último episódio da temporada: a chave reserva. Artigo 150."]]}, {"s": "O VEREDITO — CARDS NARRADOS", "l": [["*", "Tela preta. Os cards do Veredito surgem um a um."], ["VOZ", "Artigo 148 do Código Penal: privar alguém de sua liberdade, mediante sequestro ou cárcere privado. A pena é de reclusão de um a três anos."], ["VOZ", "A pena sobe para dois a cinco anos se a vítima é ascendente, descendente, cônjuge ou companheiro do autor, ou tem mais de sessenta anos; se a privação dura mais de quinze dias; se a vítima é menor de dezoito anos; se é internada em casa de saúde ou hospital com esse fim; ou se o crime tem fins libidinosos."], ["VOZ", "Se a vítima sofre grave sofrimento físico ou moral, por maus-tratos ou pela natureza da detenção, a pena é de dois a oito anos."], ["VOZ", "É um crime permanente: enquanto a vítima estiver privada da liberdade, o crime está acontecendo. Por isso, a qualquer hora, há flagrante, e a polícia pode entrar na casa, mesmo à noite e sem mandado, desde que tenha fundadas razões."], ["VOZ", "Não confunda: se a liberdade é usada para exigir resgate, é extorsão mediante sequestro, artigo 159. E quem se apropria da aposentadoria de uma pessoa idosa comete outro crime, previsto no Estatuto da Pessoa Idosa."]]}]}, "150": {"dur": 21, "logline": "Às 4h58, a delegada Helena espera na porta de Marisa Vilela o minuto em que a lei permite entrar. No mesmo dia, uma inquilina descobre pela câmera que o dono do apartamento entra na casa dela quando ela não está. O final da temporada responde quem envenenou Seu Jairo e mostra que nem a polícia, nem o dono do imóvel, entram onde querem.", "twist": "A casa é asilo inviolável. Entrar ou ficar na casa de alguém contra a vontade de quem mora ali é crime, mesmo que quem entra seja o dono do imóvel alugado. \"Casa\" é qualquer lugar onde a pessoa mora, inclusive alugado. A lei só permite entrar sem consentimento em flagrante, para socorro ou, durante o dia, com ordem judicial. Para a busca policial, \"dia\" é das 5h às 21h. O proprietário só pode vistoriar o imóvel com dia e hora combinados com o inquilino.", "guests": [{"n": "Patrícia Lemos", "r": "Vítima, ilustradora, 33 anos", "d": "Independente, metódica, sensível à própria privacidade"}, {"n": "Seu Armando Quintela", "r": "Proprietário do apartamento, 67 anos", "d": "Solitário, viúvo há um ano, educado e antiquado"}, {"n": "Dr. Saraiva", "r": "Promotor que assume o caso Jairo, 50 anos", "d": "Correto, econômico nas palavras"}, {"n": "Bia Fontes", "r": "Advogada, cliente da mesa 7 (ponte para a Temporada 2), 34 anos", "d": "Distraída, simpática"}, {"n": "Dr. Lacerda", "r": "Advogado de Marisa, 60 anos", "d": "Frio, caro, econômico nas palavras"}, {"n": "Marisa Vilela", "r": "Culpada pela morte de Jairo", "d": "Professora de dança de salão, encantadora em público e calculista em particular. Sempre com um lenço de seda."}, {"n": "Vinícius Mendes", "r": "Sobrinho de Jairo", "d": "Músico endividado, impulsivo e irônico quando tem medo. O suspeito perfeito."}, {"n": "Pedro Rocha", "r": "Filho de Helena", "d": "Filho de Helena, estudante de Engenharia. Cozinha macarrão medido no grama."}, {"n": "Dona Zuleica", "r": "Vizinha de Jairo", "d": "Vizinha de muro de Seu Jairo há quarenta anos. Sabe tudo o que acontece na rua."}], "scenes": [{"s": "ANTERIORMENTE", "l": [["*", "Imagens rápidas dos episódios anteriores."], ["VOZ", "Anteriormente, na JURISPLAY. Marisa Vilela vendeu o carro e comprou uma passagem só de ida para a fronteira, num ônibus que sai às seis da manhã de sábado. A promotora Iara se declarou suspeita e deixou o caso. A juíza Marta autorizou a busca e a prisão temporária. Mas a lei só permite entrar numa casa com mandado depois das cinco da manhã. E às quatro e cinquenta e sete, a luz da casa de Marisa se acendeu."], ["*", "Corte para a cena de abertura."]]}, {"s": "EXT. RUA DAS CAMÉLIAS — DENTRO DO CARRO DA POLÍCIA — MADRUGADA", "l": [["*", "O relógio do painel: 4:57. Helena e Caíque imóveis. A luz do andar de baixo da casa amarela, número 90, está acesa."], ["CAÍQUE", "Três minutos."], ["*", "4:58. Um táxi vira a esquina com o pisca-alerta ligado e para em frente à casa 90."], ["CAÍQUE", "Ela chamou um táxi."], ["HELENA", "Calma."], ["*", "A porta da casa se abre. MARISA VILELA, casaco de viagem cor de vinho, o lenço de seda no pescoço, sai puxando uma mala de rodinhas. Fecha a porta com a chave. Desce os três degraus da varanda."], ["*", "4:59. Marisa abre o portão. O motorista do táxi desce para pegar a mala."], ["HELENA", "Agora."], ["*", "Helena e Caíque descem do carro. Atravessam a rua. Marisa vê os dois e para no meio da calçada, com a mão no puxador da mala."], ["MARISA", "Delegada. A senhora acorda cedo."], ["*", "Helena olha o relógio de couro do pai no próprio pulso. O ponteiro dos minutos chega ao doze."], ["HELENA", "Cinco horas em ponto, Dona Marisa. A senhora está presa temporariamente pela morte de Jairo Mendes. E eu tenho um mandado de busca para a sua casa."], ["*", "Marisa não se mexe. Depois, com calma, solta o puxador da mala."], ["MARISA", "Posso ao menos pagar o táxi?"], ["*", "Caíque entrega uma nota ao motorista, que volta para o carro sem entender nada. Helena estende a mão."], ["HELENA", "A chave da casa, por favor."], ["*", "Marisa abre a bolsa devagar e entrega um molho de chaves. Pendurada nele, uma pequena castanhola de madeira."], ["*", "Corte seco para preto."]]}, {"s": "VINHETA", "l": [["*", "O triângulo laranja da JURISPLAY. ART. 150. \"A Chave Reserva\"."]]}, {"s": "INT. CASA DE MARISA — SALA E COZINHA — AMANHECER", "l": [["*", "Casa cheia de fotos de bailes, troféus de dança de salão, uma vitrola. Lúcia e dois peritos de luvas azuis, fotografando tudo. Marisa sentada numa poltrona, algemada, acompanhada por uma agente. O céu clareia lá fora."], ["LÚCIA", "Delegada. O molho que ela entregou tem duas chaves. Uma é desta casa. A outra..."], ["*", "Lúcia ergue uma chave antiga, presa à castanhola."], ["LÚCIA", "...tem o mesmo segredo das chaves da Rua dos Ipês, 214."], ["CAÍQUE", "A terceira chave."], ["HELENA", "O gancho vazio."], ["*", "Marisa olha pela janela, como se nada daquilo fosse com ela."], ["MARISA", "O Jairo me deu essa chave. Eu era companheira dele. Não é crime ter a chave da casa do namorado."], ["HELENA", "Não, senhora. Não é."]]}, {"s": "INT. CASA DE MARISA — ESCRITÓRIO — MANHÃ", "l": [["*", "Um escritório pequeno com uma escrivaninha antiga. Caíque, de luvas, abre as gavetas. Na primeira, cartas de banco empilhadas, envelopes abertos com carimbos vermelhos: \"COBRANÇA\", \"ÚLTIMO AVISO\", \"NEGATIVAÇÃO\"."], ["CAÍQUE", "Doutora. Quatro bancos. Cartão de crédito, empréstimo pessoal, cheque especial. Uma financeira que cobra juros de agiota."], ["*", "Helena se aproxima. Pega uma carta com cuidado, pela ponta."], ["HELENA", "Data?"], ["CAÍQUE", "A mais antiga, há um ano e meio. A mais recente, de três semanas atrás. \"Ação de execução. Penhora do imóvel.\""], ["HELENA", "Ela ia perder esta casa também."], ["*", "Na parede do escritório, fotos emolduradas: Marisa jovem, campeã de concursos de dança, troféus, aplausos. Numa foto mais recente, Marisa e Jairo dançam no salão do clube. Ele de terno escuro, com um lenço vermelho no bolso. Ela de vestido verde. Os dois rindo."], ["*", "Helena olha a foto por muito tempo."], ["CAÍQUE", "Eles pareciam felizes."], ["HELENA", "Ele parecia."]]}, {"s": "INT. CASA DE MARISA — QUINTAL E DEPÓSITO DE JARDINAGEM — MANHÃ", "l": [["*", "Um quintal cheio de rosas vermelhas. No fundo, um pequeno depósito de madeira. Lúcia abre armários com cuidado: adubo, pás, regadores. No fundo de uma prateleira, uma lata antiga de biscoitos."], ["*", "Lúcia abre a lata. Dentro, um saquinho plástico fechado com granulado escuro."], ["LÚCIA", "(sem levantar a voz) Delegada."], ["*", "Helena se aproxima. Lúcia não toca no saquinho. Fotografa."], ["LÚCIA", "Vou precisar do laboratório para confirmar. Mas pela cor e pela forma é o mesmo produto que estava no açucareiro. É proibido no Brasil há anos. Ninguém tem isso para adubar rosas."], ["*", "Embaixo do saquinho, no fundo da lata, um envelope. Dentro, uma carta escrita à mão. Lúcia lê em voz baixa."], ["LÚCIA", "(lendo) \"Minha flor. Vi a carta do banco na sua bolsa. Quatrocentos mil reais de dívida. Por que você nunca me contou? Eu não estou bravo. Mas quinta-feira precisamos conversar. Vou rever o testamento. Não por mal, mas preciso pensar com calma. Do teu Jairo.\""], ["*", "Silêncio no depósito."], ["CAÍQUE", "Ela ia perder a casa."], ["HELENA", "E guardou a carta junto com o veneno."], ["LÚCIA", "As pessoas guardam juntas as coisas de que têm medo."]]}, {"s": "INT. PROMOTORIA DE JUSTIÇA — CORREDOR — MANHÃ", "l": [["*", "Iara sai do elevador com uma pasta. O promotor Saraiva vem na direção contrária, ao telefone. Ele desliga e para diante dela."], ["SARAIVA", "A delegada achou. Uma lata no depósito do quintal. O mesmo produto. E uma carta do Seu Jairo."], ["*", "Iara fica imóvel. Aperta a pasta contra o peito."], ["IARA", "E o Vinícius?"], ["SARAIVA", "Vou pedir a revogação da preventiva hoje. Não há mais motivo para ele continuar preso."], ["IARA", "Obrigada, Saraiva."], ["SARAIVA", "Por quê? O caso é meu agora."], ["IARA", "Por isso mesmo."], ["*", "Saraiva segue pelo corredor. Iara entra no banheiro feminino, vazio, e se apoia na pia. Olha para o próprio reflexo. Respira fundo, os olhos marejados."], ["IARA", "(para o espelho) Você errou, Iara. E agora acertaram por você."], ["*", "Ela lava o rosto, ajeita os óculos e sai."]]}, {"s": "INT. 3ª DELEGACIA — RECEPÇÃO — MANHÃ", "l": [["*", "A recepção está cheia. Helena entra com Marisa algemada; jornalistas lá fora tentam fotografar. Caíque abre caminho. No balcão, uma mulher espera com um tablet nas mãos e cara de quem não dormiu: PATRÍCIA LEMOS, 33, cabelo preto curtinho, macacão jeans manchado de tinta."], ["PATRÍCIA", "Com licença, eu estou esperando há duas horas. Eu preciso registrar uma coisa."], ["CAÍQUE", "Senhora, hoje está um pouco..."], ["PATRÍCIA", "Alguém está entrando na minha casa quando eu não estou."], ["*", "Helena para no meio da recepção."], ["HELENA", "Caíque, leve a Dona Marisa para a sala dois. Eu atendo a senhora."], ["CAÍQUE", "Agora?"], ["HELENA", "Hoje é um bom dia para falar de portas."]]}, {"s": "INT. APARTAMENTO DE PATRÍCIA — FLASHBACK — DIA (TRÊS SEMANAS ANTES)", "l": [["*", "Letreiro: \"Três semanas antes\". Patrícia chega do trabalho, larga a bolsa e para no meio da sala. O sofá está virado para a janela. Ela não lembra de ter virado."], ["*", "Ela o arrasta de volta para o lugar, desconfiada. Na cozinha, uma xícara lavada no escorredor. Ela mora sozinha e não tomou café de manhã."], ["PATRÍCIA", "(para si) Eu estou ficando doida."], ["*", "CORTE PARA: dias depois. Patrícia abre o guarda-roupa e congela: os cabides estão empurrados para um lado, como se alguém tivesse procurado alguma coisa no fundo."], ["*", "CORTE PARA: noite. Patrícia, sentada na cama com o notebook, compra uma câmera pequena num site. Depois se levanta e passa a corrente da porta, coisa que nunca fazia."], ["*", "CORTE PARA: dias depois. Patrícia, no trabalho, no meio de uma reunião, recebe uma notificação no celular: \"Movimento detectado — Sala\". Ela abre o aplicativo. Na tela, a porta do apartamento dela se abrindo com uma chave."], ["*", "Ela se levanta da reunião sem dizer nada a ninguém."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE HELENA — MANHÃ", "l": [["*", "Patrícia coloca o tablet na mesa. Helena se senta à frente dela."], ["PATRÍCIA", "Eu moro de aluguel há dois anos num apartamento no Edifício Bellavista. Há uns três meses, comecei a achar coisas fora do lugar. A gaveta da cômoda aberta. Uma xícara na pia que eu não usei. O sofá virado para a janela."], ["HELENA", "E a senhora achou que estava ficando louca."], ["PATRÍCIA", "Exatamente. Até que eu comprei uma câmera. Pequena, de prateleira."], ["*", "Ela aperta o play. No tablet: o apartamento vazio de dia. A porta se abre com chave. Entra SEU ARMANDO QUINTELA, 67, alto, curvado, suéter bege, um molho enorme de chaves na mão."], ["*", "Ele anda pelo apartamento devagar. Abre o guarda-roupa de Patrícia e fica olhando para dentro. Fecha. Vai até a cozinha, faz um café, leva a xícara até o sofá, vira o sofá para a janela, se senta e fica olhando a cidade. Quarenta minutos sem se mexer."], ["PATRÍCIA", "É o proprietário. O dono do apartamento. Ele tem a chave reserva. Ele entra, faz café, senta no meu sofá. Ele abriu o meu guarda-roupa, delegada."], ["HELENA", "A senhora autorizou alguma vez?"], ["PATRÍCIA", "Nunca. Ele nem avisa. Eu nem sei há quanto tempo isso acontece."], ["HELENA", "Ele é o dono do imóvel. Mas a casa é sua."], ["PATRÍCIA", "Como assim?"], ["HELENA", "Artigo 150. \"Entrar ou permanecer, clandestina ou astuciosamente, ou contra a vontade expressa ou tácita de quem de direito, em casa alheia.\" Durante a locação, quem tem o direito de deixar alguém entrar ou de impedir é quem mora. A senhora. Ser dono não dá a ele esse direito."], ["PATRÍCIA", "Mesmo sendo o apartamento dele?"], ["HELENA", "O parágrafo quarto do artigo diz o que é \"casa\": qualquer compartimento habitado. Alugado, emprestado, um quarto de pensão. Casa é onde a pessoa vive."]]}, {"s": "INT. 3ª DELEGACIA — SALA DE INTERROGATÓRIO 2 — MANHÃ", "l": [["*", "Marisa sentada, as mãos algemadas sobre a mesa, o lenço ainda no pescoço. Helena entra e se senta. Caíque fica de pé ao lado da porta. Otávio não está ali: é o advogado particular de Marisa, DR. LACERDA, 60, terno caro, quem está ao lado dela."], ["LACERDA", "Minha cliente vai exercer o direito ao silêncio."], ["HELENA", "É direito dela."], ["*", "Helena coloca sobre a mesa, em sacos plásticos de prova, a chave com a castanhola, a fotografia da lata de biscoitos e a carta de Jairo."], ["HELENA", "Eu só vou dizer o que eu sei, Dona Marisa. A senhora tinha a chave da casa. Sabia do pote azul. Sabia que só ele usava aquele açúcar. Comprou um chip com um nome de defunto para me ameaçar. Tinha quatrocentos mil de dívida. E ia perder a casa na quinta-feira."], ["*", "Marisa olha para a carta. Pela primeira vez, a máscara treme."], ["MARISA", "Ele dançava tão mal, delegada. Pisava no meu pé o baile inteiro."], ["LACERDA", "Marisa."], ["MARISA", "E eu ensinava ele mesmo assim. Toda quinta."], ["*", "Ela não diz mais nada. Helena se levanta."], ["HELENA", "O resto a senhora conta ao júri. Ou não conta. É seu direito."]]}, {"s": "INT. EDIFÍCIO BELLAVISTA — APARTAMENTO 803 — TARDE", "l": [["*", "Apartamento pequeno, cheio de pranchetas de desenho e plantas. Patrícia está na porta com Helena e Caíque. A campainha toca. Patrícia abre. Seu Armando, de suéter, com o molho de chaves, para no batente ao ver a polícia."], ["ARMANDO", "Patrícia, eu... vim ver o vazamento do banheiro."], ["PATRÍCIA", "Não tem vazamento nenhum, Seu Armando."], ["*", "Armando olha para Helena, para Caíque, para o tablet na mão de Patrícia com a imagem dele no sofá. Encolhe-se dentro do suéter."], ["HELENA", "Seu Armando, o senhor entrou neste apartamento sem autorização da moradora?"], ["ARMANDO", "Eu tenho a chave. O apartamento é meu."], ["HELENA", "O apartamento é seu. A casa é dela. O senhor pode entrar quando ela permitir. A Lei do Inquilinato garante ao proprietário o direito de vistoriar o imóvel, mas com dia e hora combinados com quem mora. O senhor combinou?"], ["ARMANDO", "Não."], ["CAÍQUE", "E por que o senhor vinha aqui, Seu Armando?"], ["*", "Armando olha para o sofá virado para a janela. A voz falha."], ["ARMANDO", "Este apartamento era da minha esposa. A Giovanna. Ela comprou com o dinheiro das aulas de piano. Morreu no ano passado. Ela gostava de tomar café ali, olhando a cidade. Eu não aguentei vender. Aluguei. E às vezes eu... eu só vinha sentar onde ela sentava."], ["*", "Patrícia fica em silêncio. A raiva no rosto dela vira outra coisa."], ["PATRÍCIA", "E o guarda-roupa?"], ["ARMANDO", "Era o guarda-roupa dela. Eu esqueci que não era mais. Desculpe. Eu juro que não mexi em nada seu."], ["*", "Silêncio longo."], ["PATRÍCIA", "(baixinho) O senhor podia ter pedido."], ["ARMANDO", "Eu tive vergonha."], ["HELENA", "Seu Armando, eu entendo a sua saudade. De verdade. Mas a lei não pergunta o motivo. Entrar na casa de alguém sem permissão é crime, mesmo por saudade."], ["PATRÍCIA", "Ele vai ser preso?"], ["HELENA", "Violação de domicílio de dia, sem violência, sozinho: detenção de um a três meses, ou multa. Vai para o Juizado Especial. E não depende da sua vontade: é ação pública. O Ministério Público vai propor uma transação."], ["*", "Patrícia olha para Armando. Depois estende a mão aberta."], ["PATRÍCIA", "A chave reserva, Seu Armando."], ["*", "Ele procura no molho enorme, solta uma chave e coloca na mão dela."]]}, {"s": "INT. CASA DE ARMANDO — SALA — NOITE", "l": [["*", "Casa grande e silenciosa, móveis antigos cobertos com lençóis. No canto, um piano de parede fechado, com uma fotografia em cima: Armando jovem e uma mulher de cabelo preso, sorrindo ao piano."], ["*", "Armando chega, tira o suéter, coloca o molho de chaves na mesa. Uma chave a menos. Ele olha o espaço vazio na argola."], ["*", "Senta no banquinho do piano. Abre a tampa. Toca três notas com um dedo só, desafinadas. Para."], ["ARMANDO", "(para a fotografia) Ela é uma boa moça, Giovanna. Ela tem plantas na varanda, como você."], ["*", "Ele fecha a tampa do piano devagar e fica sentado no escuro."]]}, {"s": "INT. FÓRUM — GABINETE DA JUÍZA MARTA — FIM DE TARDE", "l": [["*", "Marta lê um pedido. Dr. Saraiva e Otávio diante da mesa. Lá fora, o céu alaranjado."], ["SARAIVA", "Excelência, diante das provas encontradas na busca, o Ministério Público requer a revogação da prisão preventiva de Vinícius Mendes. Não há mais indícios suficientes de que ele seja o autor. O Ministério Público vai apresentar nova acusação contra Marisa Vilela."], ["OTÁVIO", "A defesa concorda, Excelência. Evidentemente."], ["*", "Marta assina sem pressa."], ["MARTA", "Prisão preventiva não é pena, doutor Saraiva. Quando o motivo desaparece, ela também tem que desaparecer. E, na dúvida, a liberdade."], ["MARTA", "Revogo a prisão preventiva. Expeça-se o alvará de soltura de Vinícius Mendes."], ["*", "Otávio fecha os olhos por um segundo."], ["MARTA", "Doutor Otávio. Um bom trabalho."], ["OTÁVIO", "Obrigado, Excelência. Não foi só meu."]]}, {"s": "INT. CADEIA PÚBLICA — CORREDOR DE TRIAGEM — NOITE", "l": [["*", "Corredor comprido de azulejo verde, grades nas pontas. O agente Bráulio conduz Vinícius, já com a roupa do dia em que foi preso e a sacola plástica na mão, em direção à saída."], ["*", "Pela outra ponta do corredor, duas agentes trazem Marisa, de uniforme bege, sem maquiagem, sem o lenço de seda. O cabelo ruivo preso de qualquer jeito."], ["*", "Os dois param, a três metros um do outro. Os agentes também param."], ["*", "Vinícius olha para ela. Nunca a viu antes. Mas entende quem é."], ["VINÍCIUS", "Ele estava feliz naquela manhã. Ele cantava. Disse que pra ele era sexta-feira."], ["*", "Marisa olha para ele. Por um instante, algo atravessa o rosto dela. Ela abre a boca, como se fosse dizer alguma coisa."], ["*", "Não diz nada. Baixa os olhos."], ["BRÁULIO", "Vamos, rapaz."], ["*", "As duas filas se cruzam. Vinícius segue para a saída. Marisa segue para dentro. Nenhum dos dois olha para trás."]]}, {"s": "EXT. CADEIA PÚBLICA — PORTÃO — NOITE", "l": [["*", "Portão de ferro. O AGENTE BRÁULIO abre a portinhola. Vinícius sai com uma sacola plástica com roupas. Mais magro, barba crescida. Para na calçada e respira fundo o ar da noite, como se fosse a primeira vez."], ["*", "Do outro lado da rua, encostado num carro velho, Otávio. Ao lado dele, com uma marmita nas mãos, Dona Zuleica."], ["ZULEICA", "Trouxe arroz, feijão e bife. Você está um palito, menino."], ["*", "Vinícius ri e chora ao mesmo tempo. Abraça Zuleica com marmita e tudo. Depois se vira para Otávio."], ["VINÍCIUS", "Doutor."], ["OTÁVIO", "Otávio."], ["VINÍCIUS", "Otávio. Eu fiz o café. Eu fiz o café todo dia por seis meses. E fiquei dois meses preso porque fiz o café."], ["OTÁVIO", "Você ficou preso porque tudo apontava pra você. E porque às vezes a verdade demora mais que a prisão."], ["VINÍCIUS", "Eu quero ir ao cemitério. Eu não pude ir ao enterro dele."], ["OTÁVIO", "Amanhã cedo eu te levo."], ["*", "Vinícius olha o céu."], ["VINÍCIUS", "Ele estava tão feliz naquela manhã. Disse que pra ele era sexta-feira."]]}, {"s": "EXT. CEMITÉRIO DA SAUDADE — MANHÃ", "l": [["*", "Manhã de sol, sem garoa desta vez. Vinícius, de banho tomado e barba feita, diante do túmulo de Jairo. Otávio, alguns passos atrás. Dona Zuleica arruma flores no vaso."], ["*", "Sobre a lápide, ainda seca e murcha, a rosa vermelha do enterro. Vinícius a pega e a deixa de lado."], ["*", "Ele tira do bolso um pequeno alto-falante e o celular. Escolhe uma música. O bolero do primeiro episódio começa a tocar baixinho entre os túmulos."], ["VINÍCIUS", "Eu achava isso música de velho, tio."], ["*", "Ele ri, os olhos molhados."], ["VINÍCIUS", "Ainda acho. Mas eu aprendi a tocar no violão lá dentro. O Seu Toninho pedia todo dia."], ["*", "Dona Zuleica enxuga os olhos com a ponta do lenço."], ["VINÍCIUS", "O senhor podia ter me contado da Marisa. Eu ia rir do senhor. Ia encher o saco. Mas eu ia ficar feliz."], ["*", "Ele coloca a mão sobre a lápide."], ["VINÍCIUS", "Eu vou abrir outro bar, tio. Pequeno. Com música ao vivo. Vai ter bolero às quintas."], ["*", "Otávio se aproxima e coloca a mão no ombro dele. Os três ficam ali até a música acabar."]]}, {"s": "INT. JUIZADO ESPECIAL CRIMINAL — SALA DE AUDIÊNCIA — DIA", "l": [["*", "Marta preside. Dr. Saraiva de um lado. Seu Armando, de suéter, ao lado de um defensor de plantão. Patrícia sentada no lugar da vítima."], ["SARAIVA", "Excelência, o autor não tem antecedentes. A pena máxima é de três meses. O Ministério Público propõe a transação penal: prestação de serviços à comunidade por dois meses."], ["MARTA", "Seu Armando, o senhor aceita?"], ["ARMANDO", "Aceito, Excelência. E eu queria pedir desculpas à moça. Na frente de todo mundo."], ["*", "Ele se vira para Patrícia."], ["ARMANDO", "Eu entrei na sua casa como se ela ainda fosse da minha mulher. Não era. Era sua. Desculpe."], ["*", "Patrícia assente."], ["MARTA", "Homologo a transação. Seu Armando, a casa é de quem mora nela. A saudade não tem chave."], ["*", "Na saída, Patrícia alcança Armando no corredor."], ["PATRÍCIA", "Seu Armando. Eu continuo morando lá. E eu faço café todo domingo às quatro da tarde. Se o senhor tocar a campainha, eu abro."], ["*", "Armando não consegue responder. Só segura a mão dela com as duas mãos."]]}, {"s": "INT. FÓRUM — 2ª VARA CRIMINAL — DIA", "l": [["*", "Sala de audiências. Marta lê um documento. Dr. Saraiva de um lado. Do outro, o Dr. Lacerda, advogado de Marisa."], ["SARAIVA", "Excelência, o Ministério Público oferece denúncia contra Marisa Vilela por homicídio qualificado pelo emprego de veneno e por motivo torpe, artigo 121, parágrafo segundo, incisos um e três, e por coação no curso do processo, artigo 344, pela ameaça à delegada. E requer a conversão da prisão temporária em preventiva."], ["LACERDA", "A defesa se opõe. A minha cliente não tem antecedentes, tem residência fixa..."], ["SARAIVA", "Tinha. Estava a caminho da fronteira com uma passagem só de ida."], ["MARTA", "Recebo a denúncia. Decreto a prisão preventiva para garantir a aplicação da lei penal."], ["*", "Marta tira os óculos e se dirige à sala."], ["MARTA", "Para quem nos assiste: a partir de agora, o processo segue o rito do Tribunal do Júri. Primeiro, a instrução. Depois, eu decido se há provas suficientes para levar a acusada a julgamento: é a pronúncia. Se houver, sete jurados vão decidir se ela é culpada. Até lá, ela é presumida inocente."], ["LACERDA", "Obrigado, Excelência."], ["MARTA", "Não me agradeça, doutor. É a Constituição."]]}, {"s": "INT. INSTITUTO DE CRIMINALÍSTICA — LABORATÓRIO — NOITE", "l": [["*", "Lúcia tira as luvas e assina o laudo final. Caíque entra com dois copos de café."], ["CAÍQUE", "O granulado da lata é o mesmo do açucareiro?"], ["LÚCIA", "Mesma composição. Mesmo lote, provavelmente. E as digitais na lata são da Marisa."], ["CAÍQUE", "Então acabou."], ["LÚCIA", "O meu trabalho acabou. O do júri começa."], ["*", "Caíque estende um dos copos."], ["CAÍQUE", "Sem açúcar."], ["LÚCIA", "Eu sei. Você perguntou para a minha equipe."], ["CAÍQUE", "Na verdade, desta vez eu perguntei para você. Quer tomar um café de verdade comigo? Num lugar sem cadáver?"], ["*", "Lúcia olha para ele por um longo momento. Pega o copo."], ["LÚCIA", "Sábado. E você paga."], ["CAÍQUE", "Eu pago."], ["LÚCIA", "E tira o boné."], ["*", "Caíque tira o boné na hora. Lúcia, finalmente, sorri de verdade."]]}, {"s": "INT. APARTAMENTO DE HELENA — COZINHA — NOITE", "l": [["*", "Pedro mexe uma panela. Helena chega, larga a bolsa, tira o relógio de couro do pai e o coloca na mesa com cuidado."], ["PEDRO", "Macarrão de engenheiro. Desta vez sem queimar o alho."], ["HELENA", "Milagre."], ["PEDRO", "Acabou?"], ["HELENA", "A minha parte acabou. Agora é com o júri."], ["PEDRO", "Foi ela?"], ["*", "Helena pensa antes de responder."], ["HELENA", "As provas dizem que sim. Quem decide se foi é o júri."], ["PEDRO", "Fato primeiro."], ["HELENA", "Artigo depois."], ["*", "Pedro serve dois pratos. Helena olha o relógio do pai sobre a mesa."], ["HELENA", "O seu avô dizia que o mais difícil nessa profissão não é achar o culpado. É não se apaixonar pelo primeiro suspeito."], ["PEDRO", "E você quase se apaixonou?"], ["HELENA", "Todo mundo quase se apaixonou. O caso estava pronto. Era só assinar."], ["PEDRO", "E por que você não assinou?"], ["HELENA", "Por causa de um pote de açúcar."]]}, {"s": "INT. RESTAURANTE SABOR DA PRAÇA — NOITE (SEXTA-FEIRA)", "l": [["*", "Sexta-feira, casa cheia. Seu Alcides de avental circula entre as mesas. Na mesa 8, Iara, de vestido azul-marinho, sem os óculos, e Otávio, de camisa sem gravata pela primeira vez. Um vinho entre os dois."], ["IARA", "Você está sem gravata."], ["OTÁVIO", "Você está sem coque."], ["IARA", "Hoje eu não sou promotora."], ["OTÁVIO", "E eu não sou defensor."], ["IARA", "Então quem a gente é?"], ["OTÁVIO", "Dois alunos de Direito que perderam um voo há quinze anos."], ["*", "Iara ri. O garçom traz dois cafés. Otávio empurra o dela com dois dedos."], ["OTÁVIO", "Sem açúcar."], ["IARA", "Hoje... hoje eu quero com açúcar."], ["*", "Otávio para, surpreso. Iara pega o açucareiro e coloca uma colher no café. Prova. Faz careta. Os dois riem."], ["*", "Na mesa 7, ao lado, BIA FONTES, 34, advogada, blazer cinza, levanta-se, deixa o celular sobre a mesa e vai até o caixa pagar a conta."], ["*", "Um rapaz de boné passa pelo corredor entre as mesas, apoia a mão na mesa 7 como quem se equilibra e segue até a porta. Quinze segundos."], ["*", "Iara, por instinto, vira a cabeça na direção da porta. Franze a testa."], ["OTÁVIO", "Ei. Hoje você não é promotora."], ["IARA", "Eu sei."], ["*", "Ela volta a olhar para Otávio. Atrás deles, Bia volta do caixa e olha para a mesa 7 vazia."], ["BIA", "Seu Alcides... meu celular estava aqui."]]}, {"s": "TELA PRETA", "l": [["VOZ", "A casa é de quem mora nela. Nem o dono, nem a polícia entram como querem. E a verdade também tem hora para entrar: às vezes ela espera até as cinco da manhã. Fim da Temporada 1. Na próxima temporada: um celular, uma mesa, oito artigos. Dos crimes contra o patrimônio."]]}, {"s": "O VEREDITO — CARDS NARRADOS", "l": [["*", "Tela preta. Os cards do Veredito surgem um a um."], ["VOZ", "Artigo 150 do Código Penal: entrar ou permanecer, clandestina ou astuciosamente, ou contra a vontade expressa ou tácita de quem de direito, em casa alheia ou em suas dependências. É a violação de domicílio. A pena é de detenção de um a três meses, ou multa."], ["VOZ", "A pena sobe para seis meses a dois anos se o crime é cometido à noite, em lugar ermo, com violência ou arma, ou por duas ou mais pessoas."], ["VOZ", "Casa é qualquer compartimento habitado, o aposento ocupado de uma habitação coletiva e o lugar fechado ao público onde alguém exerce profissão. Durante o aluguel, a casa é do inquilino, e o proprietário só pode vistoriar o imóvel com dia e hora combinados."], ["VOZ", "Não é crime entrar, durante o dia, seguindo as formalidades legais, para prender alguém ou cumprir outra diligência. Nem entrar a qualquer hora quando um crime está acontecendo ali dentro. Pela Constituição, a casa é asilo inviolável, salvo em flagrante, desastre, para prestar socorro ou, durante o dia, por ordem judicial."], ["VOZ", "E a Lei de Abuso de Autoridade define o que é dia para cumprir um mandado de busca: entre as cinco da manhã e as nove da noite. Fora desse horário, quem entra comete crime."]]}]}});
